window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150223-5","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","agenda":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"下線が引いてあったり、９号議案と書いてあったり、その次の１０号議案は１０号議案となかったり、全体に統一感を持ってもらえると、渡された資料を見るときにこんがらがらないというのでしょうか、特にこうやって並ぶときにはすごくそれを感じるので、これはどこがどういうふうに統一性を持って行うのかわかりませんけれども、これは要望だけにとどめますので。","respondent":"柏原行財政改革担当課長","answer":"こういったところを迅速かつ的確に対応していきたいといったところがあります。そういったこともございまして、事業部を部という形にいたしまして進めていきたいといった内容のところから、今回、組織改正ということで、部の形も含めてやらせていただいたといったところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"今までもたくさん議論しているので、中身というよりは、この条例の内容で、いろいろな第２条の関係の附属機関なのですが、どこの附属機関がどこに所属しているのかというのは、条例の中にはそういう指示をするところがあるのでしょうか。これがどこに入っているということがわかりにくいので、それがはっきりしていただけばというふうに思ったのですけれども。","respondent":"柏原行財政改革担当課長","answer":"会議をどうやって進めていくかといったところもありますので、その課に所管してもらうということで、そういった意味も含めて組織改正を子ども未来部のほうでしていますので、そういった観点でこちらのほうに移ったといったものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"附属機関のほうが、要は、これら一覧のいろいろありますけれども、どこの部署に入っているのかというのがわかりやすく条例の中で明記はあるのでしょうか。例えば、わかりやすいようにするのであれば、附属機関のところの一覧をつけるかなにかわかりませんけれども、何々部といって、それぞれの機関を列記すれば、これはここの機関にあるというふうに理解しやすいと思うのです。いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"私の説明がちょっとあれだったので、こちらは、条例のほうにはこういった形で、今回の報酬および費用弁償に関する条例というのは、どういう費用弁償を、どのぐらいの費用で、どういうふうに払うかというようなところを決めたものが、一括してまとめたものがこの条例です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"提案","question":"だけど、これを見たら疑問に思います。今回の説明の中で、これは組織改正がなかったのでという話から説明が入っているので、そうすると、この附属機関は一体どこに附属していたのかということがかなりわかりやすいように、資料添付も必要なのでしょうけれども、条例を見たときにわかりやすいような工夫もできるのではないかという提案なので、今後の検討という形でお願いしたいと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私も大変不勉強で、これを委員に向かって言うのか、区民に向かって言うのか、そうすると、別にこれ、行政順がどうでも、我々はどこの所管かということがわからなくてもいいと思っているときもあるわけです。だから、どこの所管で、どこの、例えばこういう審議会があってということを、まさにこれ、内部的なことというのだったら、我々は何も言うことはないわけではないですか。資料として。行政順であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"}]},{"id":"topic-02","title":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","agenda":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"引用条項の変更というのは必要だと思うのですけれども、教えていただきたい点だけなのですけれども、この独立行政法人が３法人に分類され、そのうち国家公務員の身分がここだと、正直この変更の意味が私はわからなくて、もともとの法律の改正の趣旨に当たるのかとは思うのですけれども、ここだけ少し解説していただけますでしょうか。","respondent":"荒井広報広聴課長","answer":"特定独立行政法人が３つの法人に分離されました。中期目標管理法人と、国立研究開発法人と、行政執行法人です。このうちの行政執行法人のみに国家公務員の身分が付与されることになりました。","voiceIndex":27,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"よくわからないので教えていただきたいのですけれども、この第８条そのものが公開の義務を規定しているものでありますので、公開の義務を例えば緩めたり狭めたり、そういうものになるのか、ならないのであれば、そこを中心にもう１回ご説明いただけますでしょうか。","respondent":"荒井広報広聴課長","answer":"失礼いたしました。公開の義務を定めているもので、この(2)については、公開の義務を定めている個人情報の中に入っているものとして今挙げたものがあるわけですが、それについては以前と変わりはありません。","voiceIndex":29,"id":"exchange-007"}]},{"id":"topic-03","title":"の第１１号議案 品川区行政手続条例の一部を改正する条例","agenda":"の第１１号議案 品川区行政手続条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１つ、行政手続法の改正に伴って区の条例の権利利益の保護の充実というご説明ですけれども、この行政手続法の改正であったり、区の規定の改正であったり、例えば念頭に置いている事業だったり、要するに、区民と行政、また区民と業者というのでしょうか、この条例そのものにはそういう部分はない、実際、区民生活の中でいろいろ問題があるからこういう改正がされて、区条例も改正ということなので、例えば。","respondent":"江部総務課長","answer":"それにつきまして、特にうちのほうでもどういうことで回答しないとか、内容に不備が求められるものではなくて、これまでも責任の根拠を明確にしなければいけないということはありましたが、それにつきまして、少し具体的にどの条文で、どの条項で。","voiceIndex":43,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"そのときにされて、区が受理をして審査をして、応答の義務がないというふうになれば、この権利義務の保護の充実にどうしてそれでなるのかと思うのです。もちろんいろいろな案件、ケースはありますけれども、やはり申出者に対してしっかり経過や処理の中身を報告するということは当然進めていくべきではないのかと思うのですけれども、その点はいかがですか。","respondent":"江部総務課長","answer":"申し出につきまして、各所管の状況の中できちんと調査をして対応していくということになるのだと思いますけれども、特に問題がないと思った場合に、何もしないかという部分につきましては、運用の中でこれを考えていくことになろうかとは思います。","voiceIndex":47,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる初めの第３３条第２項関係の行政指導の方式のところ、要するに、行政の説明責任をしっかり果たしましょうという趣旨だと思いますので、そういう意味でも、やはり申し出があったときに、その結果がどうなのかということも説明責任をしっかり果たすというスタンスをしっかり持っていかなければいけないと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしますが、今回、改正の内容ということで出ていますけれども、こういうことは今まで、こういう条例をつくらなくても、実際やっているわけですよね。というのは、そこで摩擦が起きてしまったら大変なので、ただそれを今回、条文としてきちんと明記するということなのですか。それだけ教えてください。","respondent":"江部総務課長","answer":"委員おっしゃるとおり、例えば第３３条のところの新旧で見ていただきたいのですけれども、旧の中にも、行政指導に携わる者については、相手方に対して、指導の趣旨、内容、責任者を明確にしなければならない、これもそのまま横引きで第１項であるのですけれども。","voiceIndex":50,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問としては、教育委員会定例会に諮って合意を得ているものなのか、それとも、こういう条例というのは教育委員会と区長部局とのそれぞれの独立した関係で、そういうふうに扱っているものなのか、そこを伺いたいと思います。","respondent":"江部総務課長","answer":"今回の条例改正につきましては、基本となります地教行法が改正されたことで、教育長が特別職に変わったという法の変更による形式的な整理ということになろうかと思います。","voiceIndex":64,"id":"exchange-012"},{"speaker":"中塚委員","kind":"提案","question":"法律の改正に伴うものなので、教育委員会に情報提供はしているけれども、審議をするものではないというところですけれども、私が伺ったのは、それぞれの教育委員会の施策の決定と、教育長だったり、教育委員だったり、出席に伴う費用弁償だったり、そういう身分の保証、これは教育委員会に諮らなくても、いわゆる区長部局の判断で行うべきものなのか。","respondent":"江部総務課長","answer":"今、委員のご指摘のとおり、基本的には、執行自体は教育委員会なわけなのですけれども、予算提案権は区長にあるですので、金額ですとか、その辺については、十分教育委員会と協議しながら、最終的には区長部局で決めるですので、実際の執行は教育委員会でやっているということは。","voiceIndex":66,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"今回の改正そのものは、法律の改正に伴って、新しいポストができるということで、そこに必要な規定の改定だという範囲では必要なことだとは私も思いますけれども、この地方教育行政の改正に伴って区長部局から教育委員会への権限介入というのは慎むべきだというふうに申し述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今回もいろいろ法改正があったということなのですが、そもそも教育長、今の教育長の給料額というのは、どういう規定になっていたのでしょうか。それから、第３条のところに、「１５人以内」という、これ、「以内」というふうにしたのは何か理由があるのでしょうか。お聞きします。","respondent":"江部総務課長","answer":"実際、一覧表の中では、教育長職も入っておりまして、２３区の中での位置づけみたいなものも資料としては出ておりますが、形式的には、審議対象ではありません。","voiceIndex":69,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"逆に言うと、自由度がなくなったという部分もあるので、その辺をどうお考えになっているのかということ。１５人いなくてもというのだったら何人がいいのですかという話になります。今まで１５人いなかったのに、なぜ１５人という数字にこだわるのかと、実際、現実的にないのであれば、それに現実的に合った数値を入れてもいいのではないかと思うのですが、いかがでしょうか。","respondent":"中山総務部長","answer":"もちろんその範囲が全く青天井ということではなくて、１５とある限りは、基本的には１５人を目指すということだけれども、若干の幅が出ることについて、条例上きちんとその範囲を保っているという形をとろうということでやっているものです。","voiceIndex":71,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"最後に１つ、現行と教育長の給料上に違いというのは大きく出て来るのか、来ないのかということだけお聞きしたいと思います。","respondent":"江部総務課長","answer":"実態は今までも審議会の対象ではないのですけれども、それを区長等の給与を横引きしているということはきちんとやってきたということになりますので、特に変わってくるものではないかと思います。","voiceIndex":73,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときに、この改正は、議員たる者、議会もしっかりそういうことは学んでいって、物を申していくところは申していくということを議員各個人がしっかりやれるようになったのだから、その勉強会では、そこはよく理解をしてくれというようなハッパをかけられた我々もいたわけなのですけれども、ここで今、法律の一部が改正されたということで、お聞きしたいのは、今の第１２条、第１３条、第１４条。","respondent":"江部総務課長","answer":"それを受けてというのは、その区の事情によって変わってくると思うのですけれども、特別職の報酬のこれまでの審議の仕方であったり、それから、第１４号議案につきましては、職務専念義務という扱いにつきましても。","voiceIndex":75,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすると、第１２号議案の、例えば特別職の身分を有することになったから、ここは改正しますと。だけど、特別職の報酬等審議会があるかどうかという、一部ないかもしれないからそれはわからない。だけど、１４とか１６については、結構いろいろな教育委員会のやり方は、他の自治体あるので、額は品川区が今までやってきたことを踏襲しながら、それに見合った改正をしてきているという理解でいいのかどうか。","respondent":"江部総務課長","answer":"特別職の報酬につきましては、恐らく２３区なども全体調査をかけられるということは、報酬等審議会はそれぞれお持ちだと思いますので、同じような扱いになっています。","voiceIndex":77,"id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ言わせていただきます。今回は教育長が特別職になったということで条例改正ということですが、教育委員会の教育長職務代理者および委員の報酬も今回載っておりますが、やはり全国の自治体の中では、だんだんに変わっているという、進んでいく方向性を考えると、品川区の報酬等審議会でも、その辺はしっかり議論してほしいと思います。それだけ意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"済みません、ちょっと確認というか、よくわからないので教えていただきたいのですけれども、今回、教育委員長がなくなって、委員長の職務代理者というのが教育長職務代理者になりますけれども、この教育長の職務代理者は、教育委員会の中から恐らく選定されるかと思うのですけれども、今までの旧の場合でいくと、教育長という方がもし職務を遂行できなくなった場合、その代理というのは。","respondent":"江部総務課長","answer":"役割はそれぞれ違うというふうに認識しております。","voiceIndex":80,"id":"exchange-021"},{"speaker":"塚本副委員長","kind":"確認","question":"そういうことがきっと起こるのだろうと思っていて確認させていただいて、正直言って、代理が務まるのかということを、もう少しわかりやすく言うと、教育委員の中で教育長が今まで持っていたような職務を果たすということが果たして大丈夫なのでしょうかというところがちょっと心配、懸念があるので、その辺はどのようにお考えでしょうか。","respondent":"江部総務課長","answer":"その職責がどのように変わって、それに対応できる方がどういう方がということは、まさに今、意見が交わされているところであるというふうに聞いております。","voiceIndex":82,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案を我々議会にしてくるときに、そこら辺のところの説明も必要になってくるのだろう、非常にそこら辺の重みが変わってくるのだろうということの意識を我々も持っておかないと、我々、レクチャーを受けた中で我々の責任も問われますという話が大分あったのは事実で、だから、そこら辺のところだけは、今みたいにただ聞いているというだけの話ではなくなってくるということだけは、そのときに出てきた例は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-023"}]},{"id":"topic-04","title":"の第１７号議案 品川区職員定数条例の一部を改正する条例","agenda":"の第１７号議案 品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"保育士がプラス１８ということで、この間進めている区立認可保育園の新設という、４歳児、５歳児クラスの追加というのでしょうか、こういうところは必要な手立てだし、区民にも求められていると思いますので、今後もぜひ進めていただきたいと思います。例えば、今、念頭に置いている定数減や定数増や、そういう今後の見通しや考え方をどう考えているのか、そこだけ１点伺いたいと思います。","respondent":"堀越人事課長","answer":"委員ご紹介ありましたように、保育士等増員を図る一方、工夫を図りながら減員を進めていくということですので、必要なところにはしっかりと配置をして、区政運営をしっかりと対応していくというのが考え方です。","voiceIndex":112,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"用務員が７人減るということなのですが、保育園を増設したりとかしている関係で、用務員は非常に大切な役割を担っているのではないかと思うのです。これ、４０とか、５０とか、７０とかありますけれども、この数値はどこから来ている数値、何か法則があって７０とかにするというのがあるのでしょうか。実態も含めて、これがどう反映されていて、運用に使われているのかということも含めてお伺いします。","respondent":"堀越人事課長","answer":"７０の内訳といたしましては、新規の保育士の採用が大体約５０名で、それから、若い職員の採用が増えていますので、育児休業の代替という形の職員が２０数名ぐらいの予定をしておりますので、そういった形であわせて弾力的に対応していくために一定数。","voiceIndex":114,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"確かに効率を上げるためにというのはわからないではないし、当然、行財政改革ですから無駄のないような形で仕事をしていくというのは当然だと思うのです。それを保育士ができるからというふうに安易に考えないでほしいとは思うのですが、そのノウハウとか、それについてはどういうふうにしていって、こういう７という減を決められたのかということをもう一度お聞きしたいと思います。","respondent":"堀越人事課長","answer":"清掃等もそうですし、いろいろな消耗品の管理なども、今、いろいろなインターネット関係等もかなり進んでまいりまして、特に在庫をそれほど持たなくても迅速に発注ができるというふうな状況にもなってありますので、そういう中で保育士としてのいろいろな。","voiceIndex":116,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"職員定数と考えたときに、これからいろいろな事業展開をする中で、本当に必要な人材、人数はどうなのかというのは、当然、人材育成にもかかわってくる部分ではあると思うのですけれども、それを含めながら改革のほうは進めていくなり、増やすところについてはしっかりと増やしていただきたいということで意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"現在、区民の人口が増えてきている中で、この２３区、とりわけ品川区でもこれから高齢化がますます加速すると思うのです。区民の人数が減っている中、高齢化も進まないような、さまざまな事業も品川区は結構一生懸命やっていると思うのですが、これは大丈夫なのですよねというのをちょっと確認だけお願いいたします。","respondent":"堀越人事課長","answer":"４ページの表を見ていただきますと、今までの推移が出てきておりますけれども、やはりいろいろな課題等、保育園の増設等もございまして、見直しの人数的にもここ最近の変化は見てとれると思いますので、これは必要なところにはしっかりと配置をして。","voiceIndex":119,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"必ずいつもこういう時期にはこれが出てきて、話を今みたいに必要なところは必要な手当てをしてという話が出るのだけれども、１つだけ先にお聞きしたいのは、これは品川区も一地方自治体で、必ず人件費比率というのは出てくるわけで、人件費比率をどう捉えていらっしゃるのかという部分をまずお聞きしたいのと、この間、ずっと減ってきている部分については、民間の力を活用してよりよい区民サービスが。","respondent":"堀越人事課長","answer":"その結果、人件費比率等が数字となってあらわれているというふうに思ってありますが、いろいろ工夫を図りながら最小限の人数でしっかりと対応していくということが、これも繰り返しで、全部繰り返しで申しわけないのですが、そのような考え方です。","voiceIndex":121,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは今までもそうされてきたと思っています。では、それを全部大所帯を移動できるぐらいの政策判断があるかどうかというのは、これは議論が必要だと思いますし、それは区長判断もあるでしょうから、ここで皆さまがどうということではないでしょうけれども、それは検討していただきたいと思います。余裕がないと我々はすごく思う。","respondent":"中山総務部長","answer":"職員、直営と言っていいかもしれませんけれども、民間の力の活用、そういう中で区政をどうやっていくかみたいなところの設定ですけれども、１つは、これはサービスの低下を招かないといいますか、さらに言えば、今回の図書館の指定管理などでも、単純に業務に関して。","voiceIndex":123,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ、こんな質問していいのか。変な質問で悪いけれども。","respondent":"中山総務部長","answer":"職員の全てを語るだけの立場ではありませんけれども、よく品川区の行政運営において、我々は、区長がいろいろな場面で言われるのですけれども、不断の行政改革というふうなものについては、１つＤＮＡとして同じやり方を踏襲するのではなく、工夫がないのか、あるいは。","voiceIndex":125,"id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"一言意見表明したいと思います。図書館の指定管理者制度はやめるべきだと思います。民間の活用というお話が繰り返されていましたけれども、実態は自治体自身が生活できないワーキングプアをつくるものだと私は思います。住民福祉を削る行革には反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-032"}]},{"id":"topic-05","title":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","agenda":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"給料表が１.７％下がるということになると、退職金等々もこれに準じて下がるわけですね。実際は、この計算でいうと、とんとんという形、プラスマイナスゼロみたいな感じになるのですけれども、実はそうではなくて、職員の方々の退職金を含めた形で考えると、大分下がるのではないかと思うのですけれども、それはどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"そうですね。では、それは次にします。済みません。では、次の質問、もう１つあるのですが、(2)の単身赴任手当のところですけれども、こういう該当する方は品川区にいるのか、多分被災者支援で行かれている方などは、定期的に帰られていると思うのですけれども、その方たちが該当するようになるのか、そこら辺を教えてください。","respondent":"堀越人事課長","answer":"単身赴任手当ですけれども、今現在は、宮古市被災地支援派遣で行っている職員が７名おりますけれども、そのうちの２名が単身赴任手当の該当になっているというものです。","voiceIndex":143,"id":"exchange-034"}]},{"id":"topic-06","title":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","agenda":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"いろいろと退職金関係で改正になるということなのですが、かなりポイント制になって上がるというふうな感覚にはなるのですけれども、実際どうなのでしょうか。かなり改善されたというふうに受け取っていいのだろうかということなのですが。この適用区分の中に、保育園の園長先生はどの辺に入るのかと思っているのですが、それを教えてください。","respondent":"堀越人事課長","answer":"そのほか職層が下に行くに従いまして、少しそれが減ってくるというふうな形になってございまして、全体としては、支給水準は変わらないのですけれども、より職層に応じた形でポイントを増やしていますので、その分、反映されているというふうに考えてあります。","voiceIndex":157,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":39951,"voices":182}},{"id":"h27-20150224-6","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"区民委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)ウーマンズビジネスグランプリ2015in品川","agenda":"はじめに、(1)ウーマンズビジネスグランプリ2015in品川","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"何点かお伺いしたいのは、審査員のメンバー構成はどういう形なのかということと、プレゼン審査の通過が８件となのですけれども、今回、１回から４回、４回目なので、通過件数の経過を教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"特に私のほうは、先ほどのご説明をさせていただいた審査基準を重点に見るようなことを立場として担わせていただいて、ビジネスモデルの収支ですとか、それぞれの得意分野を分けまして、チェックをさせていただいて、８名選定をしたというような流れでやってきたものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"最終的にプレゼンの発表は８件ということなのですけれども、これは午後の時間帯を使ってということで、８件という枠をあらかじめ決めるのか、それとも、プランとして優秀であれば、どのくらいまでということになっているのかをお聞きしたいということで、１回、２回、３回、４回までの最終プレゼンの件数をお伺いしたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"その結果、過去３回、それから今回も８名ずつということですから、４回掛ける８名ということで、今までファイナリストの進出者は３２名というようなことになっているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど来街者の方の投票システムも用意するということで、これはやはり専門家だけじゃなくて、来た方たちも、自分もこういうことができるかもというような意識啓発にもすごく有効なことだと思うのですけれども、それは今回、４回目、初めてということなのかと思うのですが、それについて具体的に教えていただきたいのと、あとグランプリになった方たちが経過してどうだったかというようなことも。","respondent":"山崎ものづくり・経営支援課長","answer":"今回はプランの提出がメーンなのですけれども、その裏では、審査の集計ですとか、いろいろライブでやっておりますので、その間、会場のほうでは、昨年のグランプリの受賞者でありますとか、ファイナリストの方の１年たってのプレゼンテーションというようなものも。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは全国の女性起業家ということなのですけれども、はじめに、なぜ全国ということにしたのかということと、それからあと、こういう形でのウーマンズビジネスグランプリというような中身のものをやっているところはほかにあるのかということを１つ教えていただきたい。そして、どういうふうにこれをＰＲしているのかというところも教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"区の武蔵小山創業支援センターのコンセプトとしまして、従前、製造業を中心にして西大井と天王洲に創業支援センターを持っていまして、武蔵小山の地域特性を考えますと、やはり商店街があったり、そうした武蔵小山の地域特性に合わせた創業支援センター。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それからあとは、先ほどもありましたけれども、今回が４年目ということで、起業して出店をするところもあるということなのですが、こういうすごく豊かな発想があるというふうな思いがするのですけれども、これが実際にそういうふうにビジネスになっていくというふうなところの支援というのが、品川区のほうでもいろいろされているところだと思うのですが、そういうことで、プランを提出された。","respondent":"山崎ものづくり・経営支援課長","answer":"４件がまだ未創業あるいは起業の準備中というような方もいますので、そうした段階といいますか、内容別にまだ起業を果たせないということであれば、少し不足しているものとか、ニーズがありますので、そうしたところは武蔵小山創業支援センターの支援員なり。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後に残った８件はすごく選りすぐられたというふうなところだと思うのですけれども、書類審査の中を通過したのが２３件とか、こういうところまでも含めての相談とか支援とかというところについてはいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"ファイナリストの８名のみ手厚くその後の創業支援をしているということではなくて、グランプリとすればそういうことでもって、いろいろ対象が絞り込まれてというようなことでやらせていただいていますというご説明なのですけれども、それ以外の方も、もちろん提案内容ですとか。","voiceIndex":15,"id":"exchange-006"},{"speaker":"木村委員","kind":"質問","question":"素朴な質問なのですけれども、第１回から第４回までウーマンズビジネスグランプリということでやっているのですが、どうして女性だけのこういうグランプリが始まったのか。先ほど武蔵小山商店街にちなんで、関係があるというようなことでしたけれども、これがどうして男性はないのか、お聞かせください。","respondent":"山崎ものづくり・経営支援課長","answer":"さまざまな産業を支援する切り口の中で、武蔵小山創業支援センターの特徴としては、女性の起業に特化した支援をする場と区としては考えておりまして、その中の１つの事業としてグランプリを開き、いろんな機会を差し上げてというようなことで位置づけをしているものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"木村委員","kind":"質問","question":"先ほど武蔵小山の商店街の話もちらっと出ましたけれども、ここから卒業、グランプリをとったりした製品というものは、実際に販売をされているのかどうか。どうでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"やはり女性の起業の１つの特徴として、女性固有の１つの生活感ですとか感覚というのがビジネスモデルに反映しているというような特徴があります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"木村委員","kind":"質問","question":"今度はちょっと違うのですけれども、年代別に、例えば子ども用だとか、高校生ぐらいのものとかというものに対しては、その年代の、例えば中学生までの子どもたち、小学生だけの子どもたちの考え方、また、高校生以上の考え方というものが製品化されていくという可能性とか、あと、そういうものをこれから子どもたちだけのアイデアで。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした年代の方々と産学の連携等もあって、例えば品川区内では、北品川エリアに品川女学院という、そうした活動を一生懸命やられている高校もありますので、そういう意味での連携というのは、アイデアとして、いろんな交流というのは考えられるかなというふうに思っております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"木村委員","kind":"意見","question":"ぜひ、それはお試しでも構わないと思いますし、子どもたちというのは、すごくそういうアイデア的なものというのは何か持っていると思うのです。そういうもので、メードイン品川というものに対して、何か大きく波及できる可能性もありますので、もしできたら、これはただのアイデアですけれども、行政としてのそういう考えがあるかどうか、お願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"先ほどの答弁漏れになっていたので、通常のビジネス創造コンテスト、品川ビジネスクラブと共催してやっているコンテストにつきましては、小学生の部でありますとか中学生の部あるいは高校生の部ということで、一般枠以外に区民枠という枠を設けて。","voiceIndex":23,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"ウーマンズビジネスグランプリということで、ほとんど質問は出されているかと思うのですけれども、スクエア荏原ひらつかホールで行うということで、最初のとはまた違う会場だったのかと思うのですが、過去３回の入場者数、そこら辺のイメージと、あと男女比率というのでしょうか、それと、年代でいうとやはり同じぐらいの年代の方が比率的に多かったのかどうかとか。","respondent":"山崎ものづくり・経営支援課長","answer":"ほぼ埋まっていると、盛況な状況です。それから、やはり参加者は、私の私見、感覚かもしれないですけれども、女性の方が多いということと、３０代、４０代の、これから起業を考えるような年齢の方が多いというふうに、感覚的にはそう思っております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"交流会ということで、参加費は２,０００円とあるのですけれども、これはどのような会なのかということ。プレゼンテーションをした方といろいろ懇談をしながら、自分もこれから何か起業を目指そうという方がいろいろ質問をしたりとかというための交流会だとは思うのですけれども、その概要については。","respondent":"山崎ものづくり・経営支援課長","answer":"ビジネスプランを発表した側、それから参加者といいますか来場者で交流をされたりというような形の希望者につきましては、一定のご負担をいただきながら、当日は会場で、会議室のほうでやらせていただくようなことを考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"最後の質問をしますけれども、この参加者の中に、例えば事業として何かいいものはないかということで参加するような方というのも来ているというように思うのですけれども、そこら辺が多くなってくると、またそういうチャンスも膨らんでくると思うのですが、例えば案内もそういう方々に出すとか、ちょっとはっきりしませんけれども、そういうような考えはあるのかどうか。現状と今後の見通しは。","respondent":"山崎ものづくり・経営支援課長","answer":"その中には、そうした起業を応援するベンチャー学会ですとか、それから区内の中小企業の同友会の経営者の方々なども来場していただいて、ビジネスモデルをいろいろ聞いてというような方が交流会に出られて。","voiceIndex":29,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"改めてお伺いするのですけれども、私はこの施策、ウーマンズビジネスグランプリができた頃から質問していると思うのですが、区がなぜ区内創業者を重点にしないで、いわゆる他地区の方でも、こういう形でやっていくのかという質問をしていました。だから、区内だけに限定しなかったのは、こういう形でよかったのですというような答弁を含めていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"そういう意味では、そういう波及という意味ではあったということが１つ言えると考えています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、この施策をやっていく上で、いつも区内産業にどういう形で効果が出ているかというのだけはしっかり押さえて、この施策には、僕は賛成なのです。という意味でやっていっていただきたいと思っているので、そこはよろしくお願いいたします。個人です。どういう考えで、こういうデザインにしたのか教えていただければ。この二人の女性の起業というのは、どういうコンセプトなのですか。","respondent":"山崎ものづくり・経営支援課長","answer":"こうしたＰＲチラシによって、このグランプリの意図が伝わったり、伝わらなかったり、こういったものは難しいということは承知しておりまして、さまざま工夫をして作成をしてまいりたいとは思っております。","voiceIndex":33,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"今、説明を受けて、やはり説明は大事ですね。今、これで感覚が変わりました。違和感が全くなくなってよかったと、心からいいチラシだと。説明を受けていないと、何なのになってしまうではないですか。書けないと思うけれども、そういうあれだったのですねということで、この質問は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５番のその他の女性起業家のテストマーケティングイベント「羽ばたけ！アントレーヌ」を同時に開催してということの中身をちょっと教えていただけますでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"その他のところ、説明を漏らしまして恐縮です。","voiceIndex":36,"id":"exchange-017"}]},{"id":"topic-02","title":"品川産業支援交流施設「ＳＨＩＰ」内の貸会議室・多目的ルームの利用予約開始","agenda":"品川産業支援交流施設「ＳＨＩＰ」内の貸会議室・多目的ルームの利用予約開始","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところの割引をもっと拡大して、品川区民がもっと使えるように、せめて半額という形での区民割引にしていただきたいと思うのですけれども、そこの考え方と、１０％というところについてもなぜか、もう一回お聞かせいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"今回の施設について、協定内で、区内企業の方々にとって、あるいは関係団体の方にとって、しっかり利用を促進するようなプランとか割引なども、今後、柔軟に考えていただくようなことを残しておりますし、オープン前に協定を締結する予定になっておりますので。","voiceIndex":43,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、そこのところは、もう本当にほかの施設から比べても特段に高すぎるところになっていまして、条例は上限で、協定で定めていくことはできるということですので、条例の上限そのものも変えていただきたいという思いもありますけれども、より多くの区民が気軽に使えるというふうな形での料金の割引と、それから料金そのものを引き下げるというところでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"１点、確認なのですけれども、品川産業支援交流施設という名称で、結構、今までは出ていたと思うのですが、これからはＳＨＩＰで通るように役所内でもなっていくのですねというのが、まず１つ、確認なのと、それと、この間の大田区の施設で、ＰｉＯの１階で、ものすごい広いところで中小零細企業の交流会、自分も見に行ってきたのですけれども、ものすごく活気が本当にありました。","respondent":"山崎ものづくり・経営支援課長、小川オリンピック・パラリンピック推進担当課長","answer":"オリンピックという意味は、グローバルなということに言葉を変換しますと、今、オフィス、事務室の入居企業の選定といいますか、いろいろそちらの募集をかけて、やらせていただいている中には、外資系の。ただ、オリンピック・パラリンピックという名称と、それから五輪のマークにつきましては、大変厳しい、いろいろ規制がございまして、めったやたらに使えるということではございませんので。","voiceIndex":46,"id":"exchange-020"}]},{"id":"topic-03","title":"住民基本台帳事務における特定個人情報保護評価の実施結果","agenda":"住民基本台帳事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"井上委員","kind":"意見","question":"今後のスケジュールの平成２７年度の作業工程のところで、４月の住民記録システム改修というところで、結局、予算措置みたいなところでは、これは国から全てあるのか、それに伴って、品川区のほうでシステム改修、コンピューターをこの機に変えていくというような自治体もあるようなのですけれども、そういう部分について品川区は行われるのか、今までのコンピューターとかでオーケーなのか。","respondent":"井浦戸籍住民課長","answer":"現在予定されている国庫補助のシステム関連につきましては、平成２６年度に準備的な改修も行いまして、平成２７年度もこのご案内のとおり改修していくということで、あらあらの概算ですが、金額ベースで２,７００万円程度と考えてございまして。","voiceIndex":56,"id":"exchange-021"},{"speaker":"井上委員","kind":"意見","question":"後半のほうの社会保障と防災のほうのシステム変更というのは、単費予算で行われていくというものなのか、その辺はどうなっていますか。","respondent":"井浦戸籍住民課長","answer":"こちらにつきましては、現在、国のほうから、税につきましては補助率が示されておりまして、総経費の３分の２について補助するです。社会保障につきましては、厚生労働省所管になりますので、厚生労働省から国庫補助のものについては示されているです。","voiceIndex":58,"id":"exchange-022"},{"speaker":"浅野委員","kind":"質問","question":"１ページの第三者点検の実施結果の中で、点検実施機関で品川区情報公開等審議会とありますが、人数はたしか３名だったと思うのですが、そこで、ちょっと聞き漏らしたかもしれないですけれども、情報システムの専門家にというふうな表現があったと思うのですが、合計で５名で点検を実施するということなのでしょうか。この点、お伺いします。","respondent":"井浦戸籍住民課長","answer":"第三者点検の点検実施機関の構成メンバーについてのお尋ねです。この全体としての品川区情報公開等審議会は、これまで３名でございまして、２名を新たに委嘱しまして、総勢５名になってあります。そして、さまざまな専門家がいらっしゃいます。","voiceIndex":60,"id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"そうすると、品川区情報公開等審議会は、５名の委員でこれからはずっと運用されるということなのか、その点を１つお伺いしたいのと、あと、その他の参考意見の中でウイルス対策ソフトの効果的活用についてというのがあるのですけれども、対策ソフトは多分、必要になってくるとは思うのですが、最近、またどこかの対策ソフトがちょっとトラブルを起こして問題にもなって。","respondent":"井浦戸籍住民課長","answer":"２つ目としまして、今回、番号法の定めで第三者点検を行う機関として、国からも指名されてありますので、この第三者点検を中心に、情報安全について専門的に取り組むというところの大きく２つございまして、それぞれ専門家の方がいらっしゃいますので。","voiceIndex":62,"id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはりウイルスですとか、サイバー攻撃とか、当然、考えられると思いますので、その中でいろいろやられるかと思うのですが、小まめな更新もそうですけれども、ここの部分については、区民の個人情報を守るという観点から、特に力点を置いて、これからも進めていっていただきたいと思いますので、よろしくお願いします。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この３番の第三者点検の実施結果の(3)の修正意見のところのリスク軽減措置の宣言文というのは、どこがどこに向かって、どういう中身で出すのかというところを教えていただきたいのと、私はこういう宣言文もぜひこの委員会でもご報告いただきたいと考えていますけれども、その点が１点と、それからあと、今度は全項目評価書の修正決定をして。","respondent":"井浦戸籍住民課長","answer":"全文については、委員会には提出ということではございません。それで、全項目評価書の公表、あるいはパブコメの回答についての公表ですが、３月中に公表するということで考えてあります。","voiceIndex":65,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、ここの委員会がそういう報告を受ける委員会というところでは、今回のこういう報告にしても、できる限り、そこの中身がわかるようなものにしていただきたいというのは要望なのですけれども、宣言文にしても、それから評価書にしても、６０ページもあるものですから、全てということにはならないのですが、概要なり、そういうものをぜひ報告するという、前にこのご報告があったときも。","respondent":"井浦戸籍住民課長","answer":"このマイナンバー制度につきましては、全国的な統一の制度で、全ての自治体あるいは国の行政機関を含む、個人情報を取り扱う大事な仕組みになっておりますので、委員会等々でのご報告につきましても工夫をしまして。","voiceIndex":67,"id":"exchange-027"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"１日目の代表質問の部分で、プレミアム付区内共通商品券についてという質問への答弁の中で、拡大をするというようなところ、簡単な答弁でしたので、その真意というところで、大型店舗とかといった部分での見直しとか、今までの方針転換があるのか、その辺についての状況をお知らせいただきたいと思います。","respondent":"米田商業・観光課長","answer":"それに対しまして、区側のほうは、取り扱い店舗の拡大については従前もやっておりますが、今回、国からの交付金もあり、規模の拡大も予定されていることから、品川区商店街連合会を通じまして、取り扱いの小売店舗。","voiceIndex":75,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"小売店舗の拡大という部分で、今までやってきて、何がその拡大につながっていかなかったかの現状と、働きかけていくことが今までもされていたのだと思うのですけれども、そこでいっていなかったということでもっと拡大をするという趣旨なのか、その辺の、小売店舗の拡大の具体策みたいなものはあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-029"}]},{"id":"topic-05","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"木村委員","kind":"意見","question":"先ほどの僕の発言の中で不適切なところがありました。それで、不適切な言葉がありましたので、それの取り消しをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-030"},{"speaker":"あべ委員長","kind":"確認","question":"本当に皆様、１年間ありがとうございました。区民委員会、比較的、常任委員会の中では、議案、報告事項とも少ない委員会であるということで、その分、１件１件に対して非常にしっかりと議論ができたと思いますし、また、行政視察だけではなくて、区内外の現場視察もかなりの数を入れられたと思います。私のほうから確認をいたします。先ほどの個人名を出されての発言の一部ということでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":29781,"voices":99}},{"id":"h27-20150224-7","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"厚生委員会","time":"午前１０時００分～午前１１時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の品川区障害者計画・障害福祉計画","agenda":"の品川区障害者計画・障害福祉計画","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認させていただきたいのですけれども、障害者差別解消法に基づいた事由が見当たらないのですけれども、「品川区障害者計画・品川区障害福祉計画」が策定される前に法律が成立していると私は思うのですが、その法の趣旨はどういうところに反映しているかの確認を簡単にお願いします。","respondent":"中山障害者福祉課長","answer":"「品川区障害者計画」の４１ページになりますが、ここの中の「2)合理的配慮を共通基盤とした行政サービスの整備」あるいは「1)インクルージョンに基づく、障害者にやさしいまちづくりの推進」、項目としては。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん、健常者でも大変なわけでありますから、ましてや障害をお持ちの方で地震が起こったことすらわからない、そういう中でさまざまパニックになったということをたくさん聞いたわけであって、そうであるならば、具体的な展開はさまざま防災課にあるのかもしれないけれども、「品川区障害福祉計画」の中でより具体化していくべきではないかと思いますが、合わせてお答えを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"知的障害者の親の会ともお話しする中では、地域の中でまず身近なそれぞれのご家族の方がお知り合いの方にお話ししたり、日ごろの防災の意識を高めたり、家の中の設備を整えることもしていく必要があるとの認識も持たれておりますので、そういった親の会とも連携しながら。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"だけれども、町会や自治会は、名簿はあるのかもしれないけれども、そのＡさん、Ｂさん、Ｃさんの障害の特徴はわかっていないわけであって、そうすると、そういう方々が、では避難所で町会長や自治会長の指導のもとに対応できるかと思うと、それは非常にやりにくいことは目に見えている話であって、そこの部分だけははっきりとした、いろいろな防災対策があるのだけれども。","respondent":"中山障害者福祉課長","answer":"ただ、そうはいいましても、本当にこの話は、個々によってその障害の方の事情も違いますし、実際に災害が起こる時間・場所によっても、かなり差がありますので、できるだけ個別のイメージを持ちながら、どういうふうな避難をしたらいいか。","voiceIndex":9,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"移動支援のことも、相当、私たちもヒアリング等をしてお話を聞いているのですが、たしか約１万２,０００時間になるということですけれども、例えば事業量を増やすと同時に申込みや申請の仕方を簡素化していくとか、それから、例えば突発的に急に何らかの理由で移動支援が必要になるときもあるわけですから、そういうときに使いやすい制度にしてほしいと相当聞いたのですが。","respondent":"中山障害者福祉課長","answer":"移動支援につきましては、最初にその方にとって月々当たりどれぐらいの移動支援の量が必要かということを、一応、支給決定をして、その時間の付与の中で対応しているところです。ですので、突発的な事項に対応できるかというと、難しい一面があるのは確かです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"パブリックコメントですけれども、視覚障害の方向けにはどのような方法でされたのか、教えてください。","respondent":"中山障害者福祉課長","answer":"一応、ホームページにはアップしましたので、音声読み上げ装置を使っていただくと音声として確認することができるようにはしておきましたのと、それから、視覚障害者協会の会長にも。","voiceIndex":13,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"視覚障害者協会の会員には、もしかしたら会長から、こういうのが出ているので確認したい場合にはホームページで読み上げ装置を使ってということは伝えているということですね。それが違うかどうか確認です。そこで対応ができない等々があれば、福祉避難所もしくは二次避難所という考え方になっているのかと思いますが、そこはわかりますか。","respondent":"中山障害者福祉課長","answer":"委員おっしゃるとおり、一時的には避難場所に行っていただき、その中で対応が難しい方について、二次避難所、あるいは福祉避難所ということで、状態に合わせた避難所に移動していただくことになっております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問","question":"それはかなり重度の障害ですとか、難病があるという方で、それはおそらく区のほうでつかんでいらっしゃると思いますけれども、その方たちをどうするのかというところが、非常に今後の課題かと思いますけれども、では福祉避難所をどうやって開設するのかとか、その辺は防災課と今後連携をとっていくということでよろしいのでしょうか。","respondent":"中山障害者福祉課長","answer":"そことも連携しながら、避難所の開設のマニュアルも、今、つくっているところですので、実際に開設のシミュレーションをやりながら、ご利用者の避難の経路についても確認していければと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望ですけれども、いろいろな団体と懇談される機会があると思うので、そこら辺は、もしそういう話が出たときに、誤解されているといけないので、比較的軽度な方は最初から分かれてではないのですよというところですよね。皆さんの町会等で決められているお住まいの場所の避難所に行くのですよ。要望です、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"これは私の考えではなく、要望なので、障害者の皆さんからも、障害者本人でここに直接要望を言うのは難しい方もいるので、そういったところでは、家族、そして障害者本人に幅広く説明してほしいという切実な声もありますので、ここはぜひ説明会を今後は開いていただけたらと思います。ですので、そこにはぜひ応えていただきたいと思いますけれども、改めてお考えを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"本当に災害がいつ起こるか、時間帯によっても随分とその対応は変わってくるので、さまざまな想定をしておくことは必要だと考えておりますが、計画的なもので計画をつくればそれで終わるというようなものではないとも思っておりますので。","voiceIndex":20,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"多くの意見が集まってほしいというところであれば、説明会も開いて、さらに今まで届かなかったところまで広げていっていただきたいと思います。それから、災害時のところですけれども、具体的になっていないところがすごく不安です。就労支援もすごく障害者の方から多く出される要望ですけれども、このように目標値を掲げて、なのでこうしていきますよという確保の方策がどこにあるのか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"この中で、1)一般就労に向けての就労支援の強化ももちろんやってまいりますし、それだけではなく、例えば一般就労には行けない福祉的就労の方に対しても、2)のところでいろいろな作業メニューを用意することでご本人の特性に合った仕事をしていただきたい。","voiceIndex":22,"id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"「では、死ねということなのですか」とも訴えられました。それから、就労支援ですけれども、こういった拡充をしていきますとは書かれていますけれども、障害者の皆さんや障害者団体の皆さんからは、就労継続支援のＢ型も本当にいっぱいで、「拡充」と言うなら、ではその場所を増やすのか、増設するのかというところまで考えて、または要望もされているのです。","respondent":"中山障害者福祉課長","answer":"Ｂ型について言えば、平成２６年度中に定員が５人増えていますし、平成２７年度に向けては１８人増える計画でやっております。そのサービスを使うというところでは、４７ページの障害福祉計画のところで就労継続支援Ｂ型がどれぐらい伸びていくかという数値も設けています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"パブリックコメントのところで、１６ページの下に荏原第５地域センターのトイレの改修のことが出ていまして、平成２６年度中に改修を行うということで、ということは、もう進んでいる、私もここの要望を受けまして、一緒にトイレも見に行って、現場も見て要望もしてきたので、平成２６年度中に改修を行うということで。","respondent":"中山障害者福祉課長","answer":"私も現場を見に行かせていただいたのですが、施設整備課でも、確かにここは改修するとずっと使い勝手が良くなるということで準備をしていると聞いておりますので、多分、平成２６年度中にこちらは改修が進むものと考えています。","voiceIndex":26,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはりこういった当事者の声で個別に対応していただいているということだと思いますけれども、一つひとつ丁寧にやっていただいていると本当に思いますけれども、その声を集めるためのパブリックコメントと、さらに説明会もやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"提出人数１９名ということで、内容を見ると、提出された方は障害をお持ちの方がほとんどなのかと思いますが、出された方たちは、ある程度、そういう方が多いのでしょうか。","respondent":"中山障害者福祉課長","answer":"多くはご自身が障害者、あるいはその親の方というのが多かったです。ただ、障害をお持ちでない方につきましても、まちづくりのところで、障害者理解のことをするためにはこうしたほうがいいのではないかといった具体的なご意見もいただいているところです。","voiceIndex":29,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"一つその中で、「品川区障害福祉計画」の５２ページ、7)移動支援事業が、毎年、時間が増えるのは、現場の方にとっては大変いいことかと思いますけれども、その反面、パブリックコメントの１１ページにNo.３５「ヘルパーの増員をお願いしたい」という要望があって、区も、ヘルパー養成の研修をしていくということでありますが、実は私もガイドヘルプ研修を受けた一人ですが、現実、現場へ行っていますと。","respondent":"中山障害者福祉課長","answer":"なかなか難しい支援にはなってくると思うので、早急にここの数字が伸びるとは思っておりませんが、ヘルパーの質を高めていくことと、あとは利用者の状況をよく確認して、グループ支援でも対応できる方なのかどうなのか、そういったところも見合わせながら。","voiceIndex":31,"id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つですが、「品川区障害福祉計画」５２ページに6)手話奉仕員養成研修事業ということで、これは健常者の方が、多分、研修を受けて手話を習ってお役に立ちたいという思いだと思いますが、この中に中途聴覚障害のある方たちもいらっしゃるかと思いますが、その辺、区としては中途聴覚障害の方に対しての研修事業は何かお考えになっていることは、私の見た感じではなかったものですから。","respondent":"中山障害者福祉課長","answer":"中途障害の難聴の会もありますので、そういったところにつなげながら必要な手話を身につけていっていただいたり、あるいは相談も含めて、そういった対応をしていければと考えています。","voiceIndex":33,"id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"最初にお伺いしたいのが、パブリックコメント公表は広報しながわで来月２１日ということですけれども、この回答、区の考え方、ずらっと書いてありますけれども、これはこのままの文章で掲載されるということでしょうか。","respondent":"中山障害者福祉課長","answer":"ホームページはそういった文字数の関係がないので、こちらのまま載せられるかと考えています。そういったこともありますので、今回、パブリックコメントとしてまとめたものについて、障害者福祉課と区政資料コーナーに若干ご用意してお配りできればと考えています。","voiceIndex":35,"id":"exchange-017"},{"speaker":"向委員","kind":"質問","question":"となると、例えば空いている区営住宅の件でも転用できないかというパブリックコメントがありましたけれども、こういった区営住宅や区民住宅は、基本的に私たち議員であれば条例で目的を定めているので転用は難しいとすぐわかりますが、でも、区民の方で条例に触れていない方はすぐには理解できないから。","respondent":"中山障害者福祉課長","answer":"いただいたご意見をまた今後のパブリックコメントの回答の書き方というところでほかの課とも調整しながら、十分に配慮してまいりたいと思います。","voiceIndex":37,"id":"exchange-018"},{"speaker":"向委員","kind":"意見","question":"「障害者福祉課」という名前があるところは、本当に今後も整備を進めますとか、拡大に努めてまいりますとか、障害者福祉課の書き方はしっかりしてあると思ったのですけれども、都市計画課等はざっくりしていて、あまり難しい根拠を述べ過ぎても区民の方はわからないとか、万人受けする回答はないと私も思っているので、この辺りは今後の意見ということで心に留めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"１つだけ確認ですけれども、パブリックコメントのNo.９に、「発達障害の相談業務に従事していて」という表現があって、この方のご意見の中で「子どもの頃から適切な対応をしていれば、病状が進行しなかったのではないかと感じることが多い」という表現があります。まさしくそれが書いてあるわけでありますから、それは進めていくべきだと思いますけれども、改めて確認ということでお願いいたします。","respondent":"中山障害者福祉課長","answer":"できるだけ多くの方が認識を持って早くからの療育につながるように、そして療育の履歴がしっかりと療育ノートのようなものを通じて、乳幼児期から就学期、就学期から成人期へとつながるように、そういったところで療育ノートを来年度に向けて作成していきたいと考えております。","voiceIndex":40,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"その方向は、ぜひお願いします。誕生して間もなくさまざまな障害が見つかった時点で適切な医療を受けるなり、さまざまなケアを対処していけば、結果としてご本人が成長していく中で幸せな人生に近づいていくわけでありますし、それから環境も経済的な支援も、当然、少なくなっていくわけだから、それは非常に大切なことでありますので、進めていっていただきますようよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-021"}]},{"id":"topic-02","title":"の「しながわ健康プラン２１（素案）」のパブリックコメントの結果報告","agenda":"の「しながわ健康プラン２１（素案）」のパブリックコメントの結果報告","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"あれは男性の方々が対象だったのだけれども、自分で目標を立てて一定の成果を達成したときに、それを公表し合う、それから、表彰まではいかないけれども、ある程度褒め称えるようなこともやっていたわけで、そうすると、行動宣言した中に品川区も入っているわけだから、となると品川区も、行動した結果こうなりましたということをＰＲしていって、目標は職員の健康なのか。","respondent":"川島健康課長","answer":"この計画も、つくったらつくったままということではなくて、普及・啓発もそうですが、行動宣言している以上は進捗状況の報告ということで、品川区自らもこのような取組みをしていますという部分を、何らかの形で宣言する形の取組みもやっていく必要があると考えています。","voiceIndex":48,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区役所の名前が出てしまっているので言うのだけれども、しかも、行動目標をこのように宣言する予定なのでしょう。なので、それを品川区でもしやるとなれば、いろいろな方法が考えられると思うので、ここでは難しいから、ざっくりとしたことしか出てこないと思うのだけれども、せっかく行動宣言したら、その後の展開をぜひ検討していっていただきたいと思うのですが、いかがでしょうか。","respondent":"川島健康課長","answer":"人事課の健康管理の担当の部門と連携をとりまして、こういった宣言をしていますので、今のご指摘の部分を踏まえましてしっかり取組みを進めたいと考えています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この行動宣言は、今、後ろに４団体が出ていますけれども、２３団体、今は名前が出ていて、これがもう宣言した団体なのですよね。これは、ホームページなどに載せられているということでしたか。","respondent":"川島健康課長","answer":"こちらは厚生委員会の資料用に抜粋したものですが、２３団体全てが何らかの宣言をしていただいているということで、「しながわ健康プラン２１」の冊子に宣言の内容と団体を全部掲載する予定です。","voiceIndex":55,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほどさらっと見せていただいたチェックリストは、少しやってみようという形ですぐ取り組めるのではないかと思うので、とてもいいとは思いました。そういったものもＰＲしていただいて、意識を区民の皆さんに持ってもらうというところでは、区がイニシアチブをとっていかなければならないと思います。もう一回伺いたいと思います。","respondent":"川島健康課長","answer":"冊子につけるのではなく、別な形で枚数を多くつくって、いろいろなところに置いていただくような形で考えております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで多くの意見がまた戻ってくれば計画等にもさらに反映できるので、ここでも説明会を求めたいと思いますけれどもいかがでしょうか。","respondent":"川島健康課長","answer":"今のご意見とは違うようなやり方になってしまうのですが、我々健康課で、健康づくり推進委員という実践団体、実践をする委員と一緒に仕事をしておりますので、まずその方たちにこの「しながわ健康プラン２１」を説明して。","voiceIndex":59,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"健康づくり推進委員の方からも、みんな健康のことをどう思っているのかしらという、自分が推進している立場にあるので、顔を合わせている皆さんはそれをわかるのですけれども、そうではない、向こう側にいる区民の皆さんはどう考えているのかは、推進されている委員だからこそすごく疑問に思っているところだと思うので、より一層多くのコメントを集めていくためにも、説明会をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":25077,"voices":69}},{"id":"h27-20150224-8","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"建設委員会","time":"午前１０時００分～午後 ０時１８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、大崎駅西口バスターミナルの整備","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、大崎駅西口バスターミナルの整備","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ご説明ありがとうございました。私も地元ではないので詳しいことはまだわからないので、その計画書から伺いたいんですけれども、これだけの計画がもう立っているということは、ある程度の事業の見込みがおありかと思うのですが、国内他都市と連絡するというところで、どちらの都市と結ぶというところをお考えになっているのか。今、お考えになっているところを伺いたいというところ。","respondent":"溝口都市開発課長","answer":"品川線の関係になりますけれども、今回のターミナル、当然品川線も利用するような形にはなると思いますが、都内４か所の同じようなバスターミナルがありますので、そういったところとの連携も図りながらになりますので、大崎からすぐ品川線に乗るのか、または。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都内４か所というのはほかにどこがあるのか教えていただきたいのと、あと、施設の運営のところで、この前も他会派の議員さんから一般質問があったんですが、バス事業者からの使用料を施設の維持管理運営費に充てることはできるとあるのですけれども、もしかして、そのとき答弁があったら申しわけないのですが、どれぐらい、その使用料というのを見込んでおられるのか。その辺についてご説明願います。","respondent":"溝口都市開発課長","answer":"施設使用料につきましては、今後、バス事業者との協議になりますが、運営に大体年間五、六千万円かかるような形になりますので、それを収入としてしっかり入れられるような形で、今、バス事業者等との協議を進めているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、ご紹介していただいた都内４か所は、やはり聞いたことがあるので、かなり有名なところですし、そこと肩を並べていくのかなと思うと、非常にすごい話だなと今、改めて思いました。プレス発表が出た後、新聞にも出たので、やはり区民の方から何件か問い合わせをいただきました。最後にちょっとお聞かせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"全国から集まった人たち、先ほど方向の中でも、今後商業施設との施策の連携というのを図っていくというふうに考えておりますが、大崎に来て、すぐ山手線を使って行かれるのではなくて、できれば品川区内の列車もそうですし、しながわ水族館もそうですし。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この地域路線バス、今のお話を聞くと、あちこち回ってほしいのかなという思いもあったのですけれども、実際にルート的にどういうところを考えていらっしゃるのか。そこを一つ教えてほしいのと。１６３号線の関係で、どのくらいの高速バスが発着したりするのかを、よくわかりませんけれども、周辺の影響とか交通量の影響とか対策とか、何か考えていることがあったら教えてください。","respondent":"溝口都市開発課長","answer":"周辺の交通の関係ですが、１６３号線については、今回、バスを導入しても交通渋滞とかそういったものについては発生しないということで計画しているものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"今、ターミナルの１００台というと、かなり今までと雰囲気が変わるというか、出入りというところである程度やってくれるのかなと思いますが、今後の展開だと思いますけれども、これは地元の方のところには具体的にどのくらいまで話がいっているのか。今後どういうふうにご説明をするのか。その辺を教えてください。","respondent":"溝口都市開発課長","answer":"地元町会長等には個別に本計画についてはご説明していますので、改めて周知というのは考えておりませんが、今後、運行する段階で、せっかくつくった施設、それを区民の方に知ってもらうためにどういうＰＲをしていけばいいのかというのは。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も知っているのは新宿ぐらいですか、ターミナル。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"３点目が、ちょうどここのところというのは、今度、中へ入ってきちゃったのはいいけど、どういうふうに接点というのか、大崎と五反田のほうと、それから大井町と、国道１号にも接点を求めなくてはならないですけど、やはりある程度の大きさのバスが出入りしてくるわけなので、当然に、明電舎とか貿易センターさんも資本が入っていますから、その辺のノウハウは非常に持っているのでしょうけれども。","respondent":"溝口都市開発課長","answer":"そこと同じ話になってくると思います。大崎に来て大井町までどう行くのか。そういった観点も含めて、観光施策とも連携した形でどういう形がとれるのか、それについては今後詳細に検討していきたいというふうに考えているものです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"原委員","kind":"質問・要望","question":"一つ目はわかりました。ですから、もう少し大きく治安とかやはり重点である防災の関係とか、その辺のところでもう１回、もう少し全体を大きく考えてお返事いただきたいということ。それからあと、３番目のほうのところに関しては、これは通行の、単純に言ってしまうと道が狭いんじゃないのという感覚があるものですから、その辺のところについてお話をいただきたい。","respondent":"溝口都市開発課長","answer":"そういったものについては引き続き検討していきたいと考えているものです。バスの運行のどの路線が、特に大崎から大井町を結ぶ路線でいきますと、１６３号線の整備がされないと、今、路線バスが通れないような状況になっております。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"北品川五丁目第１地区再開発事業","agenda":"北品川五丁目第１地区再開発事業","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"きのうちょっと帰りに見てきたのですが、かなり進んでいて、あと外構とか公園施設、囲われているところの今、工事が進んでいるところを見てきたのですが、平成２４年からということで、まちがどんどん変わっていく、すごい変わりようだなと思って見てきたのですけれども、一つお伺いしたいのは、区有施設というところにあるのですけれども、実際に今回のこの開発のところで。","respondent":"溝口都市開発課長","answer":"経緯として、もともと持っている権利変換を受けている床といたしましては、まずは(1)大崎ブライトタワーの３階のホールの部分の床。それと(2)の事務所施設、それが区の権利変換で受けた施設となっているものです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"というところで、この３６０席のホールというのがちょっと具体的にどういうふうに使われるのか教えてほしいのと、あと、パークシティ大崎ザタワー、ここの幼保一体の施設が入りますが、この床というのはどういう経緯でどうなったのか。改めてもう１回お伺いいたします。","respondent":"溝口都市開発課長","answer":"基本的には一般に貸し出しをして、一応２分割して使えるようにはなっていますが、セミナーですとか、会社説明会、または入社式、そういったところに使えるような、また、ものづくりとしていろいろ産業交流のイベント。","voiceIndex":27,"id":"exchange-010"}]},{"id":"topic-03","title":"品川区の環境に関する各計画の実績報告等","agenda":"品川区の環境に関する各計画の実績報告等","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。それと、一番最後のページの６ページで、重点プロジェクトの１で民間活力の活用というところですが、平成２６年度アサヒビール株式会社から第二延山小学校に太陽光発電設備（１０Ｋｗ相当分）の寄贈を受けるとあるのですが、この経緯を教えていただきたい。これを民間でやるということを推進するということなのでしょうか。合わせて３点お伺いします。","respondent":"三ツ橋環境課長","answer":"３番目のカーシェアリングにつきましては、民間活力の導入も今、大分、例えば例を挙げますとタイムズとかカーシェアリングが進んでいると思いますけれども、その動向を見ながら活用してまいりたいと考えています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"保健センターは３０％削減というのはすごいのですけれども、この省エネ設備の導入というのは、最新の機器を使っていると思うのですが、例えば具体的にどんなものを使ったのか、ちょっとイメージがわかないので、そこだけ教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"省エネ設備というのと、民間のＢＥＭＳなどを導入しておりまして、そちらで大分省エネとして削減はしております。","voiceIndex":38,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"１点お伺いしたいのが、１ページ目の最初の１の(1)のところの基準年の考え方というか、平成２１年、２００９年を基準年としてその後の経緯が書かれているのですが、なぜ平成２１年なのか、基本的なところを教えてください。","respondent":"三ツ橋環境課長","answer":"基準年の考え方は、本来、直近の実績があります平成２３年度、２０１１年を基準年とすべきですけれども、当該年度は御存じのとおり、東日本大震災の直後であり、行政サービスの一部を縮小するなど、非常事態体制で節電に取り組んでおりました。","voiceIndex":40,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"基本的に今回の計画が平成２５年度から平成２９年度の５年間で区切られていますよね。そのときの基準年というのはいつも同じような考えで、その５年間の中で基準を持っていくという考えなのでしょうか。その辺を教えてください。","respondent":"三ツ橋環境課長","answer":"基準年としては平成２１年度を基準としておりまして、こちらは前年度比を１％削減していこうというふうに見ております。","voiceIndex":42,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"ちょっとよくわからなかったのですが、前年度をということで、この計画の中での基準年の設定の仕方、普通だったら５年計画だったら頭の年とか、あとそうではなくて、品川区が追っかけている基本的な位置があって、常にそことの比較をしていくのかという、ちょっと基準年がずれると前年度よりも下がりましたと言っても、全体的にどうなのかというのが見えないので、ちょっと基本的なところで。","respondent":"三ツ橋環境課長","answer":"この第三次実行計画といたしましては、基準年を平成２１年度としております。","voiceIndex":44,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"３ページと２ページを参照しながらなのですが、２ページでは、イのエネルギー種別ＣＯ２排出量、ＬＰＧ、実行計画と見直案が４倍になって、この３ページにおいては、このＬＰＧが利用に対して増えているのですけれども、そこの増えている状況と、逆にこの見直し案のところで、なぜ４倍近くなったかというところを教えてください。","respondent":"三ツ橋環境課長","answer":"２ページのＬＰＧにつきまして見直し案、こちらですね、エネルギーの対象となる施設を見直しましたので、そちらの対象となる施設の計算値になっておりますので、例えば住宅のところで、住宅などが入っていたのですけれども、それが対象外となっております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"３ページの表だと平成２１年、これは２ページは平成２１年、アとイとはリンクしていると思うのですけれども、平成２１年度を基準にした場合、この数字が違うのは何でなのですかということです。","respondent":"三ツ橋環境課長","answer":"こちらにつきましては、対象となるものが違っておりまして、そのトータルを見直しますと、こちらのＬＰＧが、対象となる施設が増えて……。","voiceIndex":49,"id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"そこの今、所長がおっしゃったように、入れるべき、入れないべきというのは、入れる入れないという基準はどういう基準に基づいて算入をされているのかを教えてください。","respondent":"三ツ橋環境課長","answer":"１ページの下にあります対象となる分は、こちらの計画の見直しの中でお伝えしたように、品川区地球温暖化防止対策実行計画の策定の後、環境省から発表された手引きに基づいて対象としております。","voiceIndex":59,"id":"exchange-018"}]},{"id":"topic-04","title":"水銀混入ごみによる品川清掃工場１号炉の停止","agenda":"水銀混入ごみによる品川清掃工場１号炉の停止","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"こういうもので、家庭的にはどういうところに使われているのか、業務的に。やはりそういう最初の段階でそちらで強化するのも大事ですが、やはり皆さんの意識を高めていただいて、そういうものは適切な処理をしていただくようにという啓発が必要だと思うのですが、家庭的なものと、主にどういったものに水銀というのは使われているのか、わかっている範囲で教えてください。","respondent":"小林品川区清掃事務所長","answer":"あれの含有水銀が一番多いというふうに思っております。ちなみに、それに対する対応なのですけれども、品川区では他区に先んじて、蛍光灯、体温計等を資源として回収しております。","voiceIndex":66,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひ、そういったたった１個や何かの出し方の誤りで全体がとまってしまうということが大変な損害ですので、ぜひ働きかけもしてほしいと思いますし、私たちもせっかく品川区は資源の回収をしているので、そういうところできちんと出していただくような努力をしていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-020"}]},{"id":"topic-05","title":"五反田ふれあい水辺広場等における平成２７年社会実験","agenda":"五反田ふれあい水辺広場等における平成２７年社会実験","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"売り上げが上がったというところの原因というか、何で売り上げが上がったのかというところでの区のお考えというか、周知がされたということもあるのでしょうけれども、その辺について伺いたいと思います。特に品川区の水辺というところでの、品川区というところに何かこだわりがあっての仕掛けみたいなものがあるのかどうかという点を教えてください。","respondent":"奥田河川下水道課長","answer":"もう１点が、イベントがあるとやはり売り上げが一緒に伸びるということで、区と一緒に季節ごとにイベント等を実施していこうということで、昨年もイベントは単発ではやったんですが、それを季節ごとにやっていこうということが大きな売りの点です、例えば防災まつりとか。","voiceIndex":74,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。いろいろなその地域地域のやり方というのがあるので、広島市のものを移植したからうまくいくとも限りませんし、そういう意味では本当に一生懸命やられているんだなというふうに感じますので、大切に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問・要望","question":"その他のところで、広報しながわおよび区ホームページ等ということで、等というのは好きな字なのですけれども、等をもう１回細かくというか具体的に説明をしていただきたいのが一つ。普通、我々の感覚だと、商業というか、休みのときに一番書き入れのような気がするのですけれども、なぜ土日がここのところが抜けているのかを説明をしていただきたいと思います。よろしくお願いします。","respondent":"奥田河川下水道課長","answer":"１点目の、３のその他のところの「等」ですが、地元のタウン誌ですとか、そういったものですとか、あるいはケータリングのほうでも地元でビラをまいたりですとか、そういったものを「等」ということで考えてあります。","voiceIndex":77,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"今、周知の等ということで、地元のタウン誌等々ということでお話しいただきましたけれども、それこそまさに外国人観光客という視点の中で、こちらに関してはやはりアピールする部分、外国の方、こういう水辺、非常に好まれる傾向があると思うのですけれども、どのようにそこを、区内のイベントが最初だよというこの土台を築いて、今後の展開になっていくと思うのですけれども、今後。","respondent":"奥田河川下水道課長","answer":"委員からお話がありましたように、外国人ということは、実は関係部署とまた調整しながら、そういった国内外の観光客にも当然親しんでいただきたいと思ってありますので、こちらは今後調整していきたいと思ってあります。","voiceIndex":79,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"調整する上で、やはり外国の方に周知するときに重要になってくるのは、ツールという問題があって、情報端末等々、これは結構周知すると意外とこれが見ている部分があるのですけれども、そこらの利用者の情報端末ツールに対して取り組みをするというような戦略の一部分なのですけれども、そこらのところについてどのような考えを持っているのか、教えてください。","respondent":"奥田河川下水道課長","answer":"今のそういった情報端末ですとか、あるいは広報などと調整していきながら、今、委員からお話があったように、積極的に進めていくということで思ってありますので、その辺は調整したいと思っていますのでよろしくお願いいたします。","voiceIndex":81,"id":"exchange-025"}]},{"id":"topic-06","title":"防災地図（関係機関用）の配布","agenda":"防災地図（関係機関用）の配布","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、平成２７年度の目玉で中央公園でヘリポートをつくることになっているのですけれども、荏原地区が全然ヘリポートがやはり少ないというところで、この辺、防災の関係の質問になってしまうのですけれども、ヘリポート、例えば林試の森を今後、そういうふうに考えていくのかとか、そこら辺についてのお考えをお聞かせいただきたい。その２点お伺いいたします。","respondent":"鈴木防災課長","answer":"ただ、実際の災害時、緊急時には、消防のヘリ、自衛隊のヘリ、学校の校庭等で一定程度の広さが確保できれば、離着陸は可能ということで聞いておりますので、常設の指定はできないにしても、実際には一定程度荏原の方面にもヘリの発着はできるだろうということで考えております。","voiceIndex":88,"id":"exchange-026"}]},{"id":"topic-07","title":"平成２６年度「品川区地域防災計画の修正」","agenda":"平成２６年度「品川区地域防災計画の修正」","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"幾つかお伺いさせてください。１ページ目の急傾斜地崩壊危険箇所６か所を警戒区域として優先的に選定したとあるのですが、具体的にはどちらなのでしょうか。資料１のほうに４３か所が都としてここに指定をされているのですが、現在は崖消滅により４０か所ということで、今まで４３か所と伺っていたのですけれども、これは今後は４０か所ということでよろしいのでしょうか。それが２点目です。それが３点目。","respondent":"鈴木建築課長","answer":"平成３１年の指定を目指して調査自体も早めていくということを伺っておりますので、区のほうが先行して来年度から崖の調査を行うわけですけれども、その辺の都の動きと連携協議をしながら調査を進めていきたいですけれども、基本的には今回、指定をかけする６か所について。","voiceIndex":95,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。この避難行動要支援者の定義の中に、特に支援を要する者、「特に」という言葉が入っているのですが、これによって、自分は助けていただきたいという希望される方も、今までは災害時要援護者には入っていたと思うのですが、「特に」と入れたことによって限定されてしまうのかどうか。この二つをお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"２点目の特に配慮を要する者という定義ですが、これは法律の用語をそのまま引用している表現でございまして、要するに、自助、自分の努力で対応ができない方という意味で、特に支援という表現をしているというものでございまして。","voiceIndex":97,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"毎年度見直しをして改訂されている。特に、(4)の災害時要援護者対策のところで、今日のところでは要点のところで名簿の作成が区市町村の義務になった。避難所も二次避難所と福祉避難所があったり、今、お話しされたように在宅で過ごされる方々のところというのは、今回のところはそこは全然含まれていない、検討はそこまでは至っていないということなのか、ちょっとそこの関係を教えてください。","respondent":"鈴木防災課長","answer":"要配慮者の方の対応全般ですが、特に先ほど申し上げましたように、避難行動の部分は特出しをして、避難行動要支援者という名前になっておりますが、法の中ではそれ以外にも避難所における配慮だとか、在宅についての言及もございまして、また。","voiceIndex":99,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、そこの修正の部分も今後、配布をされるというか、差しかえになっていくということなのでしょうか。","respondent":"鈴木防災課長","answer":"現時点の体制で、今でいう要援護者の方についての対応は、避難所等についても、もう記載がありますが、それを改めて新しい定義に合わせて整理をし直しまして、計画のほうの修正はほぼ完了しております。","voiceIndex":101,"id":"exchange-030"},{"speaker":"若林委員長","kind":"質問・要望","question":"その経験から、まず、呼びかけチラシの個別配布、これは丁寧に１軒１軒伺うということで現場を見させていただいて、大変に来ていただいた方は心強くご協力いただきました。一方で、全部で約２００所帯とかという、全部少ない職員だけで回る。そこについて、また、一般質問等でやったと思いますけれども、明確な答弁がなかったので、要望も含めてお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"チラシの配布と個別配布等による情報の伝達ですが、ご指摘のように、昨年の場合には６か所で２００世帯でしたので、職員を動員しまして何とか１時間程度で個別に対応することができたですが、今後、ほかの地域の指定とか、対象世帯が広がった場合には。","voiceIndex":103,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"１週間にわたる雪対策で防災課の方も徹夜等で本当にお疲れになっていると思いますし、そういうお仕事はちょっと……。たった２回のどか雪で命の危険まで高齢者の方が感じるような状況というのが大都会にあるのだなと。間の部分がやはりないと、私はそのとき考えたものですから、ぜひその辺についてのお考えをお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"それともう一つ、自助・共助は、基本的にはやはり地域のコミュニティでのつながりに基づく活動ですので、ボランティアを否定するものではありませんが、登録をしてボランティアの位置づけというよりは、構成員の一員としてお互いに自発的に助け合うというのが理想的な形ですので。","voiceIndex":110,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"意見","question":"例えばこれは本当に田舎というか地方のほうの小さな自治体であれば、みんな顔が見えているので、あそこのおばあちゃんが助けてくれと言った場合は、多分何らかの方法で助けられると思うのですけれども、やはり３７万区民がいるこの品川区において、たまたまその方は私に連絡してきたからあれでしたけれども、そうでない方でやはりどういうふうに、本当に救急車を呼ぶとか、本当に大変な事態。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"特に、不特定多数の集客の施設とか、私なんかも買い物をしていたりして、大きなところにいて、ここでは地震に遭いたくないなと、崩れてくるだろうなと思ったり、危険を感じるところもあるので、不特定多数の来訪者に対しての安全確保というのはすごく事業所さん、いっぱいあるので大変だとは思うのですが、この辺がどの辺まで進んでいるのか、課題だとかがどうなっているのか教えてください。","respondent":"鈴木防災課長","answer":"区内の事業所、特に多くのお客様等が集まる施設についての対応状況ですが、御存じのように、基本的に東京都の帰宅困難者対策条例におきまして、事業者としての努めということで努力規定ではありますが、一斉帰宅の抑制だけではなくて、必要な備蓄の準備。","voiceIndex":113,"id":"exchange-034"},{"speaker":"大倉副委員長","kind":"意見","question":"地域における自助と共助の支援というのが防災においても大事かなと、環境づくりという部分ではしっかりやっていっていただいているところだと思います。先ほどもお話がありましたけれども、企業と町会が連携をした防災訓練をやっているようなところもあり、こういったところを区としてどんどん増やしていっていただければなと思っていますが、その辺について何かお考えというのはありますか。","respondent":"鈴木防災課長","answer":"地域の事業者の方との協力体制ですが、今、大崎第１地区と品川第２地区には、三者連絡会議と言いまして、地域と事業者と区、三者で協力するというような会議体を立ち上げまして、そこでの訓練等が実施されておりまして、そこの運営につきましては、まさに地域の事業者の方。","voiceIndex":116,"id":"exchange-035"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"事業者の努めのところに、防災区民組織等と連携した応急活動とか訓練ということかなと思っているのですが、そういったところ、防災区民組織とか町会の方とかが企業と一緒に何かやろうというのはなかなか難しいと思うので、ぜひその辺とかも区のほうで少し積極的にかかわっていっていただいて、この自助・共助の環境づくりに向けて、防災訓練であったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-036"}]},{"id":"topic-08","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"あそこの東品川、歩けばあの話題になるということで、さまざまな流言飛語も飛んでいましたけれども、今回、でも本当に担当の方がすごくご苦労をされて、都との折衝、また今、調査をやられているということもよく理解をしておりますので、３月末に住民説明会をやられるということですけれども、住民の方、お祭りの神酒所になるところでもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"ごめんなさい、追加で一つだけ。先ほどの確認ですけど、平成２７年度末までに工事を終了するのは、これは全ての工事を終了する予定ということでよろしいですか、調査だけではなくて。","respondent":"多並公園課長","answer":"今のお話のとおり、来年度末、平成２８年３月までの完成を目指し、なるべく一日も早く工事が完成するよう今、設計作業を進めておりますので、それがまとまり次第、最終的なスケジュールが明らかになるところです。","voiceIndex":138,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4134#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":45665,"voices":142}},{"id":"h27-20150224-9","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"文教委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２６年度品川区教育委員会事務事業の点検および評価報告書","agenda":"の平成２６年度品川区教育委員会事務事業の点検および評価報告書","exchanges":[{"speaker":"南委員","kind":"質問","question":"改めて、それを選んだ基準。どういう考え方で、この２点がクローズアップされたのかというところを伺いたいと思います。あそこの委員をしておられると思います。教育委員会全体で、１人の方の学識経験者としてのご意見ではなくて、広く聞いていくことのほうが、より客観的になるかなと思うので、そのあたりについては、どう考えておられるかということを質問したいと思います。は個々に伺いたいと思います。","respondent":"渋谷指導課長、村尾学校支援担当課長、品川庶務課長","answer":"杉並区については、３０人程度学級、あるいは理科専科の教員を区独自に配置するために、１００人以上の教員を５年間採用したということで。「良い指導案」という言い方なのですが、実際に各学校の校内研究等で、それぞれ先生方が検討しながらつくり上げた指導案や。複数でやるという点も、ご意見としては踏まえて、今後は少し考えていきたいと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そのようなことなのか、そこを確認したいと思います。この２つの基準をどうして選ばれたかというのは答弁がなかったので、求めたいと思います。できるだけ客観性というか、いろいろな意見を受けとめていくということが大事だと思いますので、複数検討していきたいというお話なので、それはそれとして、ぜひ進めていただきたいと思います。学校トイレは何番でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"４ページですか。事務事業評価のＡ、Ｂ、Ｃのついているところ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"全体的にどのくらい到達しているのか、その辺をつかみたいと思うので、それを教えていただきたいと思います。ソーシャルワーカーの件です。６８番の一番下のところに、「小学校への区費スクールカウンセラーの配置を見直す必要がある」と書かれているということは、都費で全校配置されたから、区費はなくしますということなのですか。このことを確認したいのです。それから、いろいろあるのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"そのほかの巡回相談等々で、いろいろと気になる学校については相談体制をとっていくということで、採用の後の関係はどうなるかわからないけれども、とにかく区費のスクールカウンセラーは引き揚げていくと理解していいのかどうかを、最後に確認したいと思います。それについてはどうなのかという答弁をしていただきたいと思います。その辺がどういうことなのかがわかるように教えていただきたいと思います。","respondent":"品川庶務課長、村尾学校支援担当課長、田村教育次長","answer":"全体的にどうだとか、そういう予定ではなく、順次、トイレや学校施設等は改修していかなければいけないものですので。スクールカウンセラーの件なのですが、各学校に配置というのは、もう都費が配置されていますので、区費スクールカウンセラーにつきましては。そのような積み上げをしてきた結果なので、南委員のおっしゃることも十分わかるのですけれども、なかなか現実の交渉、そのようなやりとりのことになると。","voiceIndex":16,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"トイレ改修の件です。私は、一番古いところとか、においがきついところということで、そのとき、そのときで判断をする際に調査するわけです。調査をしたということは、大体その時点でどういう実態になっているのかということは、全校的につかんでいるということだと思うのです。いい環境をつくっていくことはやっていただきたいと思います。要望です。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"初めの２ページ目に、「対象事業数を１２６事業とした」と出ています。教育委員会でやっていている全事業なのですか。対象事業が１２６事業と書いています、この事務事業評価を見ていると、例えば、ＩＣＴの事業が出ていないし、事業というのが、教育委員会全体でやっているうちのどのくらいの事業数なのかを教えていただきたいです。評価Ｂに対する教育委員会の考え方を教えてください。","respondent":"品川庶務課長、野呂瀬学務課長","answer":"Ｂの評価につきましては、総合評価しか出していないという点で、Ｂの中での優劣がわかりづらいということはあります。１ページをご覧ください。先ほど少し説明したとおり、１ページの中で、基本評価というものがあります。次のページの３３番、「学校ヘルプデスク」とありますけれども、これも原則的には、パソコンのシステムに対する問い合わせ等々の事業ということで、この事務事業の中にはＩＣＴも含まれていると理解しております。","voiceIndex":24,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そうですか。私も何となくそこに入ってくるのかなと思ったのですけれども、継続のＢになっているから、区としては、平成２６年度は積極的に取り組んでいただいたというのがあったので、ここは逆に言えば拡充なのかなと思います。前の質問とも重なるのだけれども、Ｂの中でも拡充に近いＢというのが、ここの中にもあるのかなという感じです。その辺はよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"学識経験者の意見の「区固有教員の採用について」の一番最後に記載されている文章の中の「人事交流や大学院での長期研修等が行える仕組みを作ることで、教員の資質向上が期待される」と意見としてあります。この部分について、どのようなお考えか。５ページには、研修についてのプログラム固定化を避けるためのマネジメント研修等とあります。このご意見に対して、どんなお考えなのかを教えてください。","respondent":"渋谷指導課長","answer":"学識経験者のご指摘どおり、固有教員の見聞を広めて、資質向上のために人事交流の可能性については、今、さまざま検討しています。","voiceIndex":29,"id":"exchange-009"},{"speaker":"高橋委員","kind":"質問","question":"今、いろいろな可能性というお話があったのですが、固有教員の方も、そういった形で、ほかの自治体との交換留学的な可能性は、かなりハードルが高いと思いますが、あるいは、他の自治体、東京ではなくてもいいのですが、小中一貫校の先生との交換というような可能性があれば、お互いに出てくるのではないかなと思うのですが、その点はいかがでしょうか。","respondent":"渋谷指導課長","answer":"確かに、今１８人おりますので、１人いなくなってしまうというのは、それなりに痛手になるので、行って来いの交換留学みたいなことができるのかどうかということも含めて、他の自治体との可能性等々を、まさに検討しています。","voiceIndex":32,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問","question":"教育委員会意見冒頭の主な意見ということで、かなり掘り下げて意見がまとめられていらっしゃって、私はすごく興味深かったです。この取り上げ方が、教育委員の皆様のフリートークなのか、ある程度事務局側で重点だと思われるとか、この辺のやりとりを伺いたいなと思いました。１番目にある家庭教育力の向上支援。年度ごとの変化もあると思うのですが、取り上げ方について教えていただければと思います。","respondent":"品川庶務課長","answer":"一方で、教育委員も、なかなか事業を広くは見られないという点もありますので、事務局である程度出した形、プラス教育委員でも、新たにこれを挙げてほしいというものも含めた両方の形で、教育委員会の意見の項目出しをしてやったです。","voiceIndex":36,"id":"exchange-011"},{"speaker":"南委員","kind":"意見","question":"１６ページの就学援助の関係です。その点の考え方が１点です。２つ目は費用負担の問題です。１００％父母に負担していただくのか、広げていくのであれば、補助金も含めて、そういうものも考えていくべきだと思うのです。子どもが一層勉強嫌いにならないように、自主的に学習できる環境を整えるということが一番大事なことなので、そのあたりの関係で、どう設定されるのかということを聞きたいと思います。","respondent":"野呂瀬学務課長、渋谷指導課長","answer":"就学援助のご質問です。先日の一般質問でご答弁したとおり、生保の基準は引き下がっておりますけれども、品川区に対しては現行基準のまま、来年度は継続していくという姿勢です。自分の食べたものや寝るところといった、日常生活でもかかる部分については、実費負担ということで、子どもたちには適切な費用負担なのかなと考えているところです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"費用負担のところです。その点についてはどうなのか。引き下がった生保に対して、品川区の場合は１.２５ということです。その辺を確認したいのです。だとしたら、引き下がっているのですから、たとえ１.２５であっても、実態的には下がっていると私は思うのです。１.３５になるかもしれないけれども、しっかりと手当てをして、経済的な損失がないようにやるべきだと思いますので、その点の見解を伺います。","respondent":"野呂瀬学務課長","answer":"３年間で生保の基準を段階的に引き下げるということです。今の現行基準は、引き下げる前の生保の基準ということで、その基準を継続して、その基準に従っていいということですので、来年度は生保の基準が引き下がる前の基準に対しての１.２５で支給していくです。","voiceIndex":43,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"その点について、今年の夏にやるのであれば、いろいろな調査もし、教育委員会として、このようなやり方はどうか、このような場所はどうかということも含めた指導も、１つの大きな視点として捉えていただきたい。要望でいいのですけれども、お伝えしておきたいと思います。とにかく、費用負担は、親からしてみれば大変だというところはいっぱい聞いておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-014"},{"speaker":"須藤副委員長","kind":"質問","question":"いっぱいあるのだけれども、時間の関係で１つだけ。５ページの７番目、オリンピック教育推進事業というところで、最後の行に「品川区で開催されるオリンピック・パラリンピック競技の普及啓発を図る」と。何でここであえて「品川区」としたのかな。私は、せっかくやるなら、ほかの競技全体を見てやらなければいけない。どういうことなのでしょうか。","respondent":"田村教育次長","answer":"しかし、どうも最後の１行だけは「品川区で開催されるオリンピック・パラリンピック競技の普及」と急に狭くなってしまって、趣旨はおっしゃるとおりなので、そういう趣旨を踏まえて、教育委員会で事業を推進していきたいと思います。","voiceIndex":49,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。閉鎖されているときの子どもたちのプログラムは何かあるのですか。ただ学校を休みにして休んでいるのか。","respondent":"村尾学校支援担当課長","answer":"休んでいる最中は、担任からプリントや教科書で、こういう学習をしましょうという家庭学習のプログラムを各学校で出すのが一般的です。","voiceIndex":57,"id":"exchange-016"}]},{"id":"topic-02","title":"の品川区子ども読書活動推進計画の改訂","agenda":"の品川区子ども読書活動推進計画の改訂","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１つ、１６ページの学校図書の取組みという点です。学校図書はあちこち書いてありますけれども、４年ぐらい前でしょうか。本当にそのとおりだと思います。もししていなければ、結構子どもたちは朝早くから学校へ行ったりしている実態がありますので、図書室で本を読んでもいいんだよということになれば、またもっと違うと思うので、そのあたりの実態がどうなっているのかを伺いたいと思います。","respondent":"中元品川図書館長、村尾学校支援担当課長","answer":"教室に本を持っていくという活動をされているところも多いです。学級文庫ということで、定期的に本を入れかえるなどして、学校の教職員の方々は、子どもたちの手近なところに本を置くという努力をされていると伺っているところです。多くの学校は、事前に本は図書室で借りていて、教室または自分の机の中に入れて、朝の時間になったら、朝読書の時間にその本を読むという活動なので、朝、図書室をあけて。","voiceIndex":63,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"もう少し本の貸し借りも含めて、いろいろな交流が朝から晩までできるような環境があってもいいかなと私は思うので、図書室の利用状況がどの程度なのかを、１つ改めて伺いたいと思います。冬や放課後も含めた学校図書室の利用状況がどうで、図書室がオープンしている時間がいつの時間帯なのか。そこに子どもたちがどの程度利用しているのかということを教えてください。","respondent":"中元品川図書館長","answer":"ただ、中学生になりますと、部活動でありますとか、受験勉強などもありますので、なかなか放課後の時間帯に図書室に訪れるのは現実的にも難しいと伺っております。必ず昼休みにはあけるように努力をされています。","voiceIndex":66,"id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"学校の体制の中でいろいろなやり方をやっているということです。図書館事業として、子どもが本に親しむという事業を多彩に展開しているだけに、子どもが１日の大半を過ごす学校の中での図書に触れるチャンスを、本当にしっかりと位置付けていただければと思います。その辺のことをよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-019"},{"speaker":"つる委員","kind":"提案","question":"２年前ぐらいに、会派としてもこの改訂を提案させていただいていて、今回、個人的も含め、うれしく思っています。私が提案したことも幾つか盛り込んでいただいているように捉えています。今までグッズなども作製されてきました。そうしたことも含めて、当然メインは子どもたちの読書活動の推進なのですけれども、このキャラクターを、１０年に際して、何か活用していくお考えがあるのか教えてください。","respondent":"中元品川図書館長","answer":"それも毎年同じでは子どもたちが飽きてしまいますので、昨年は名前を書き込める名前シールにしたり、職員でいろいろ検討しています。新たな女の子のキャラクターをつくってはなど、内部の職員ではいろいろ考えているところがあります。まだ検討の域は出ておりません。","voiceIndex":70,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"今、笑いも出ましたけれども、何らかのきっかけは、すごく大事だと思います。せっかくつくって、子どもたちにも名前をつけてもらったというところで、より積極的な活用をやっていただいて、メインは子どもたちの読書活動推進ですが、知識等もしっかり広まっていくということに寄与していただきたいなと思います。期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"学校図書は、昔はよく生徒が係になりまして、借りたり、返したりというのをやったりしていました。今もそういうものを教室を含めて、学級図書と学校図書がどうなっているのか。それが１点。どうしても、学校図書というと、なかなか興味のあるものが少ないというイメージがあるのですけれども、その辺がどうなっているのかお聞きしたいと思います。","respondent":"中元品川図書館長","answer":"きちんと最後は校長先生がこの本を買うかどうかは決められておりますので、シリーズ物とか、『かいけつゾロリ』のシリーズが結構学校現場で人気があるのですけれども、そういうものを買うのか、それとも勉強に寄与するものとするのか。","voiceIndex":74,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり人気のあるものも読んでもらって、興味を持っていただきたいのです。昔からあるもの、また歴史的なものとか、いろいろ幅広く読むことによって、子どもたちにとって必要な図書であるというのが本当のところなのではないかなと思います。その辺のご指導は、人気が集まってしまうかもしれないのですけれども、それを最後に１点。その辺の気配りというか、指導を教えていただきたいです。","respondent":"中元品川図書館長","answer":"各学校には、１２クラス以上のところは、司書教諭の先生の配置があります。司書教諭の方であるとか、国語の先生、あと図書館から配置している学校図書館の運営支援員も選定の知識がありますので、お互いに協議しながら、最後は校長先生のご意見を伺って決めているです。","voiceIndex":76,"id":"exchange-023"}]},{"id":"topic-03","title":"の「品川区子ども・子育て計画」の策定","agenda":"の「品川区子ども・子育て計画」の策定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"だから、そのあたりのことを確認したいです。４月以降にならないと、ここは確定しないのですが、大体、今どんな感じに読んでいるのかを、今の時点でわかる範囲で教えていただきたいということです。先ほど言ったように、「長期基本計画」をもとに出して、７０カ所ではとても足りなくなるのではないかと思いますので、そのあたりの現状と、７０カ所の計画の認識を、まず１点、伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後も認可保育園につきましては、計画的に開設するという記載で、そのように認識しております。箇所数ですけれども、先ほどの３９ページでご覧いただきますと、保育園は６７カ所から７０カ所ですが、認定子ども園も４園から６園と増えております。","voiceIndex":83,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"今のところです。しかし、大事なことは、年度、年度だけで右往左往するのではなくて、一定、しっかりとした推計の予測をして、体制をとっておくという立場に立つべきだと思っているので、その点については、今の説明では受けとめる姿勢としては不十分ではないかなと思います。その点について、もう一度、考え方を伺いたいと思います。よろしくお願いします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員がおっしゃっていますとおり、今の申し込み率の現状を踏まえてということですが、今回の「子ども・子育て支援事業計画」の大きな国の目的というのは、潜在ニーズを把握せよということでございました。","voiceIndex":85,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"今の説明は、それはそれとして伺いました。本年度の現実の問題で伺いたいと思います。潜在ニーズがどのくらいだと捉えていて、保育園では６７園から７０園に増設するのか。したがって、年度途中にできるから十分に間に合うという姿勢では、私は区民の要求には応え得ないと思いますので、その点について、１点伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そこが抜けてしまえば、いくら年間に入っても、大体保育園というのは、４月１日に入れるというのがメインですから、そのような点で、私はこれだけの計画をつくられて、８,２３５人のところで５００人から６００人ぐらいの入れない状況があるということなので、そこはしっかりとフォーカスして対策をとるという姿勢になっていただきたいということを強く要望して、今日のこの段階ではやめたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-027"}]},{"id":"topic-04","title":"の委員長報告","agenda":"の委員長報告","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"昨日、請願審査のときにかかわって、今日、改めて伺いたいと思うのです。二次申請の枠が、私はかなり少ないのではないか、去年を上回る待機児が出てしまって大変になってしまうのではないかなと思ったので、いろいろ対策を求める質問をしました。認証保育所の情報提供、それから、どのくらいのあきが出ると見込まれるのか等々について、質問したいと思います。","respondent":"竹田保育課長","answer":"品川区内の認証保育所の入所可能数のお問い合わせです。今現在の制度からご説明しますと、毎月２５日前後、各認証保育所と連絡をとりまして、翌月の予定数をホームページに掲載しています。","voiceIndex":102,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"いつもの月とは違う状況があるというところは、それはそうだと思うのです。認証にとっても、全部チェックしてこなかったのでわからないですけれども、せいぜい全員入れたにしても、２００人から３００人ぐらいだと思います。このような場面ですから、答弁はいいですけれども、ぜひ重く受けとめて、来年以降、繰り返さない対策をとっていただきたいということを強く要求して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40457,"voices":111}},{"id":"h27-20150224-5","meetingId":"h27-cm02","date":"2015年2月24日","dateIso":"2015-02-24","committee":"総務委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"全体的に今回のこの協議を終えて、課題だったり、また、やはり品川区や２３区のご主張でまだ取り入れられていない問題点だったり、その辺はどんなふうなところがあるのか、そこをまず大きく伺いたいと思います。それと２ページ目の固定資産税部分が増えたわけですけれども、固定資産税が増えている要因をどう捉えているのか、今後の見通しとしてはどういうふうに捉えているのか、そこを伺いたいと思います。","respondent":"本城企画財政課長","answer":"それからあと、地方消費税につきましては、ちょっと冒頭もご説明させていただきましたが、基準財政収入額で見ると、地方消費税交付金について４８.１％の増ということで、額にすると６４９億円余ということの増収を見込んでいるものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうもありがとうございました。協議の中で、この人件費の算定について、若干細かく分かれると改善が見られたというお話でしたけれども、この３ページの資料で、新規算定等の主な項目というところで、今回の特徴が幾つか記されていますが、ここをちょっと伺いたいのです。","respondent":"本城企画財政課長","answer":"それからあと再調整ですが、国民健康保険のほうですけれども、基本的には保険料軽減の拡充対応経費ということで、５割・７割軽減だとか、そういうところのものについて、今回の新たに財源が出てきた経費について、それに充てているというものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にもう少し、この人件費の算定改善というところですけれども、定数上と実態上の差が民間委託、横滑り化を伴っていて、それへの振り替えというお話がありましたが、具体的にどの事業が振り替えの対象になっているのか、またその振り替えの割合といえばよいのか、どれぐらいの規模と伺えばよいのか、その振り替えた事業と、またその割合、規模ですか、そこを最後ご説明いただきたいと思います。","respondent":"本城企画財政課長","answer":"振り替わった全体の規模ですが、総体として人件費、標準人数を見直した等に伴って、１５０億円強ぐらいの人件費の見直しをしたところですけれども、一方振り替えたものが約１００億円程度ですので、その差額に当たるものについては振り替わらなかったという意味ではありますが。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その消費税の部分もと、よく東京は言われていたと思うのだけれども、これはとりあえず０.７だけれども、マイナスになったということを考えるとどうかという感覚があったので、そこら辺の感覚を教えていただきたいのと、それからこれ、再調整なのですけれども、再調整でいつもだと品川区、大体４％ぐらいなのかと思っているのですが、この項目を見ていると。","respondent":"本城企画財政課長","answer":"全体として交付金と消費税の関係ですが、先ほど委員もお話ございましたように、全体として地方消費税の交付金分は、先ほどちょっとご説明させていただきましたけれども、いわゆる平年度化によって４割強以上の増額が一方で図られて、他方調整税としては。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"約６００億円は増えたと。３００億円増えてしまったという理解でいいのかというのが１つ、それでそのぐらい増えているとなると、地方から見ると、やはりもう一段そこは手を入れろと言われかねないと思っておいたほうがいいのかというところを教えていただきたいのと、再調整の部分は４％で大体手当てされると思っておけばいいのか。それぐらいのことだけをちょっと教えてください。","respondent":"桑村副区長","answer":"つまり８％上がったら、今うちは６７０億円、これは２３区ですけれども。上がった分というのはどこの区も社会保障の財源として来ているので、これと市町村民税の法人税と入り違いをすることが間違いだというふうに私どもは言っているわけであります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"確認","question":"それをどうやって賄うのという話もあったり、そういうことだってもちろんあるので、インフラ整備の部分もわかるのだけれども、これだけを見ると、必ずそのわけのわからない議論にもう１回戻されてしまうとちょっと思っていたので。減債対策経費が１００億円あって、ここについては品川もやはりそれなりに来るのか。その４％分ぐらいが来るのかという確認だけしたかったのです。","respondent":"本城企画財政課長","answer":"あくまでも再調整の需要額積み上げですが、これ２３区が新たな財源に出たところで、社会保障の対策、あるいは減債対策の需要の積み上げとして計算していくことですから、それに基づいて来る額としては、品川区、大体平年どおりの額が確保できる見込みでいます。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"教えてください。３ページ目のところには、新規算定等ということがあって、財源対策のうち、公共施設改築経費の臨時的算定と財政健全化対策、これ中身をもう少しお話しできるところがあれば、あと品川区にとってはどういうものとして考えるべきなのか、考えられるのかということを教えてください。","respondent":"本城企画財政課長","answer":"これについては特別区が等しく行うべき事務を遂行することができるようにということで、これは特別区の税収だけ見るとかなり返済があるところ、一定程度２３区共通な、標準的なサービスについては、そういった税収等にかかわらず、どこでも対応できるような算定をするという。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり核兵器廃絶、恒久平和の確立に向けて、やはり３０周年にふさわしい中身にぜひしていただきたいと思うのですけれども、区に伺いたいのはなぜ核兵器がつくられ、そして広がっていったのか、そしてこれをなくすためにどんな行動が必要なのか、品川区としてはそれをどう考えていらっしゃるのかというのと、ぜひそういう中身を事業にも反映していただきたいと思うのですけれども、いかがでしょうか。","respondent":"江部総務課長","answer":"１つ目のパネル展の意味づけで、ただ起こったことをお知らせするのではなく、どうして起こってしまったのか、これをどうやったら防げるのかという視点につきましては、表示といいますか、説明をつけるなり、表示はしていこうと思っておりまして。","voiceIndex":26,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"この点を１点伺いたいのと、あともう一つ、やはりこの間の議論を聞いていますと、臨界核実験について品川区は抗議をしないと。この点を改める必要があると私は思います。まとめてこの核兵器廃絶と恒久平和の確立にぜひ区民も、議会も、また自治体も力を合わせていきたいと私は願いますけれども、いかがでしょうか。","respondent":"江部総務課長","answer":"品川区といたしましては、昭和６０年に行いましたこの宣言、これは大変重い宣言と捉えております。","voiceIndex":28,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"沖縄、それから東京だと大空襲、必ずこのところが取り上げられるのだけれども、やはり恒久平和を望むなら戦争というのはそれだけではなかったわけで、そこら辺の、今回も学童疎開とか少しあるが、もう少しいろいろな面で恒久平和を望んでいる部分とは、どうしてもそこに注目が行ってしまうのはしようがないのだけれども、本当にお亡くなりになった方というところにポイントを当てれば。","respondent":"江部総務課長","answer":"それで、要は事業が割と年度事業ということで、単発型で、核のことを踏まえたとか、将来に向けたという連続性みたいなところで、もう少し工夫をしたほうがいいだろうというのは、いろいろな先生方からいただいた意見、委員の皆様からいただいた意見もありますので。","voiceIndex":31,"id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"きゅりあんの１階の小ホール、３００人弱です。そうなってくると、ではここからどうやって普及していくのですか。具体的な方策としては何なのということです。ＰＴＡの方々の協力をいただいて、なるべく子供たちに見せようではないか、親御さんのほうに見せようではないかとか、ある一定の、強制ではないですけれども、ただ意識を持った形の啓発というのが必要ではないかと思うのですが、いかがでしょうか。","respondent":"江部総務課長","answer":"ただ、そうは言ってもやはり工夫をしていく必要があるわけで、このコンサート単体で終わりということではなく、まずこのコンサートの中身を、１つはＤＶＤにおさめまして、学校の授業とかで活用していただく資料をつくる予定にしております。それが１つ。","voiceIndex":33,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"教材にしていくというのは非常にいいことだと思うのです。全員が入れるわけではないので。ただ、やはりそれを非常にいい、講演会にもあると思うので、それをうまく使っていただきたいと思っています。それと展示のほうです。そういった点もちょっと考えていただきたいと思いました。説明文というのも方法として一つあるかと思うのですけれども、その辺の工夫はいかがでしょうか。","respondent":"江部総務課長","answer":"それから学校ごとの展示、それから展示に当たっての説明員という部分につきましては、ちょっと今後の調整になってきますけれども、確かにご意見として、やれるかというマンパワーの問題はありますが、展示物を借りてきたところがいろいろありますので、うちが自由に使えるものと。","voiceIndex":35,"id":"exchange-012"},{"speaker":"塚本副委員長","kind":"意見","question":"このコンサートなのですけれども、きゅりあん１階小ホールということで、今るる質疑があって、小学校には各３名程度とかという話も聞いたのですが、いろいろ広報する中で、来たけれども入れなかったというようなことが起こりうるかもしれないのかと、ちょっと心配があるのですけれども、東京都交響楽団の弦楽四重奏と声楽コンサートと、結構魅力的な感じもしますし、その辺の運用上。","respondent":"江部総務課長","answer":"前回、５年前は１００名に至らなかった。ただ春休み期間中と、あとこれは曜日の関係で地域住民との絡みでもありますけれども、ちょっとこれは検討、調整をしていきたいと考えています。","voiceIndex":38,"id":"exchange-013"},{"speaker":"塚本副委員長","kind":"意見","question":"広報の力を、前回１００名程度ということなので、どの程度広報するかということと呼びかけするかにも、多分かかってくるのだろうとは思うのですけれども、一方の人権都市品川でしたっけ、あのときはきゅりあんの大ホールのほうでほぼ満杯で、結構映画をやったりするというのもあったかと思うのですが、やり方によってはどんどん人が来てしまう場合もあると思うので、ちょっとその辺はよくよく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"この報告書の活用について、今概要の説明ありましたけれども、何部くらい印刷されるのか、告知の方法も改めて伺いたいと思います。やはり今の経済状況を見るならば、必要な節約という視点の見直しも、私は必要ではないかと思うのですけれども、その点についてどうだったのか伺いたいと思います。","respondent":"江部総務課長","answer":"それから経費につきましてですけれども、総予算で見直すと、予算で７３０万円程度予定しておりましたが、総額で５４０万円の執行でございました。","voiceIndex":45,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"その公費についての必要な節約ということですけれども、飛行機代、またホテル、そこが根拠として定められているということですが、やはり今の経済状況を見るならば、そこに必要な節約をしていくという見直しが必要ではないかと思ったのですが、その点だけお考えを伺いたいと思います。","respondent":"江部総務課長","answer":"これにつきましては、当初特別職の方、ビジネスクラスでということで予算計上しておりましたが、相手方との交渉の結果、訪問時期が８月から１１月、つまりちょっと寒い時期から非常に気候のいい、金額が上がる時期に変わったということがございまして。","voiceIndex":47,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今までの報告書というのが、何か聞く話によるとこれだけしっかりした報告書は今回が初めてというか、何ですか、今までそんなに中身が濃い、これは７０ページですか、８０ページにわたるものではなかったという話をちらっと聞いたのですけれども、まずどうしてこういう形でやるようになったのかというのを、もし差し支えなかったら聞かせていただきたいというのが１つと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、私のほうから。冒頭の話は、私のところで話をした部分なので。我々もちろん今、お休み状態にありますけれども、海外調査というのがあったのです。今回のこれは、もう１０年とかのスパンで行ったり、５年とか、いろいろなところがあるわけだけれども、今回帰ってきて、もちろん行政側からもご意見いただいたり、意見交換をする中で、やはりしっかりしたものを一緒につくっていきましょうと。","respondent":"江部総務課長","answer":"とりあえず６５ページをお開きいただいて、ちょっと経過をまとめてあります。１１月末、出発の前、１カ月ほど前に事前の説明会を全体でさせていただきまして、この時点で報告書をつくるという方向性が出ておりました。","voiceIndex":52,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問","question":"だからこそ、先ほどもちらっと質問がありましたけれども、これ行った成果というのは何なのですかというのは、これから出てくるものだと思っていますので、行ったことによって、この感想というのですか、これでレポート、議員一人ひとりが発言している、さまざまな角度でいろいろ書かれているレポートなので、これもぜひピックアップしていって、各事業部にパスをして、それが実現するように取り組む。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"「品川区のグローバル人材育成の参考になる」という点は、平和事業だけではなく、いろいろほかの諸課題ですとか、教育部分を視察されたというところで、ちょっとこの辺踏み込んでもう少し、もしよければ聞けたらと思ったのですけれども、今後具体的にどういった形で活かしていけるかというところはこれからのお話かと思うのですが、どのような場面でそういうことをヒントというか、得られたのかと思いまして。","respondent":"中山総務部長","answer":"だけれども、このいい部分は認める。なかなか区の場合にそういう距離感というのは、とるのが難しい。例えば補助を認めるか認めないかとなるので、こういうつき合い方というのは、今後１つあるのかと思ったという、ほかの委員もそういう感想をお持ちだと。","voiceIndex":55,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"これはパブリックコメント制度なので、全体にかかわる制度だと思いますけれども、これまで述べているように、説明会を実施したり、またこの希望者にはこの素案を配布したり、インターネットでダウンロードできますという案内ではなくて、ご意見を伺うには、計画の中身が伝わらなければ意見の言いようがないと私は思いますので、そういう意味でも説明会や資料の配布をぜひ進めていく。","respondent":"提坂人権啓発課長","answer":"ということで、広報しながわにこれをお載せしたということで、十分区民の方にはパブコメを行うということは周知できたかと考えています。今後もこのパブコメについては、区全体で検討していく課題と考えております。","voiceIndex":62,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"ほかのところを見ても、少ないときには３件だったり、５件だったりしているわけで、それで十分伝わったという評価には、私はならないと。私だってアクセスしますから。本当に７１件というのはアクセスそのものも、やはり全体からすればわずかなものであって、ここから見たって、これでお知らせが十分だとは私はならないと思うのですけれども、現状で十分なのか、改善はないのか、改めて伺いたいと思います。","respondent":"提坂人権啓発課長","answer":"今回の改訂につきましては、この方法で十分伝わったと考えております。うちの課だけの問題ではありませんけれども、パブリックコメントの周知方法など、改善についてはまた区全体で考えていく問題だと考えています。","voiceIndex":64,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"加害者の更生というところに入っていくべきなのではないかと思うのです。全く。それについてどうお考えなのか。そういう点について今後の計画、これからだと思いますが、どういう考えを持って、いろいろな部署もまたがっていると思うのですけれども、それをこちらのほうが担当になって、どういう関係性を持って進めていこうとしているのかをお聞きしたいと思います。","respondent":"提坂人権啓発課長","answer":"区で行う研修もありますけれども、東京都のウィメンズプラザなどでそういう職員を対象にした研修を企画しているように聞いておりますので、そういうところに参加させるなどを検討していきたいと考えております。","voiceIndex":67,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"その加害者更生プログラムのほうです。行こうかとか思って、違うところから入ってくる方もいらっしゃるので、そこはやはり全庁的な取り組みの１つとして位置づけていただいて、カウンセラーや専門の方がいらっしゃいますから、そこへオファーするという、そういう流れをきっちりとつくっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-024"}]},{"id":"topic-02","title":"の商店街電線類地中化道路整備工事（戸越銀座地区）その５請負契約","agenda":"の商店街電線類地中化道路整備工事（戸越銀座地区）その５請負契約","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"報告書ということなので、この間の取り組みという範囲だとは思いますけれども、いただいた意見の中に有益となる意見をということで、なかなか私の意見はどうだとかいう思いはあるのですが、ただ、最終的には正副にお任せいたしますけれども、この裏面の(4)のところです。意見だけ述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、我々が会議をした部分のところは、私もこれ書いたのだけれども、例えば深く議論をしましたと。その中で重立ったものを意見として出しているぐらいに、何かこのままでいくと、有益で９項目というと、あれだけ議論があったのがどこへ行ってしまったのというような気になるので、ちょっと１行ぐらいそこの部分は、前文でいいので触れてほしいというのを、あとはお任せします。これは後でお渡しします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"区長も施政方針の中でもおっしゃっていた政策提言も、これからいろいろなところでやっていくなどという話もあったときに、やはりせっかく総務委員会で１年間かけて議論して、最終的に考え直せまでいう意見が出たということ、本当に貴重だと思うのです。それを踏まえて、やはり今後進めていただきたい項目だと思いますので、ぜひとも、言い回し難しいと思うのですが、私は本当に書いてもいいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":38993,"voices":92}},{"id":"h27-20150225-14","meetingId":"h27-cm02","date":"2015年2月25日","dateIso":"2015-02-25","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１０時５３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ですから、この方たちの言う、地元住民が切望するというような状況ではないというふうに思っています。その辺、改めて、地元の声というのをどういうふうに捉えているのかをお願いします。","respondent":"柏原行財政改革担当課長","answer":"そういったところで、その辺の機能は外さないでほしいであるとか、それから、施設の校庭であるとか、そういったところは防災訓練で、それから、地域の方も、例えば、少年野球とか、そういったところでも使えるようにというようなことも。","voiceIndex":6,"id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"ただ、防災系を優先してほしいという声も当然あるでしょうし、また、声というだけではなくて、このエリアの特性として、防災的な機能を持ったところが必要という判断もあるかと思います。ですので、これはお声はお声として、こういうお声も確かにこれだけの数の署名が集まっているわけですから。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことをしっかりと考えていただきたいというのが１つあるわけです。そういう点でどうなのかというのを１つ伺いたいと思います。当然ラフだと思いますから、ラフでいいから教えていただきたいということと、特養ホームなり高齢者福祉施設と防災系の施設はリンクしないのか、これだけの土地がある中で、一緒になって考えていくことは不可能なのか可能なのか、その辺も伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"総括的なお答えになってしまっていますけれども、大きな考え方としてはそういう形で行くといったところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"私が一番聞きたかったのは、特養等のこういう福祉系の施設と、防災に対応した施設、そういうものが、これだけの敷地がある中で、合築という言い方がいいかどうかはわからないけれども、一緒に施設整備をすることが不可能なのかということを聞いたのですけれども、それも、そこを答弁、トータルでお答えしたということだけれども、触れていないので、ぜひそこは。","respondent":"柏原行財政改革担当課長","answer":"繰り返しの部分になってしまっていますけれども、物理的なところを考えたときに、それができるできないかというのは、その建物の大きさ、広さ等々を考えたときに、それは検討はできるかと思います。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"そういう一つ一つの区民の、この地域だけではなくて、一般的な要望も含めて、これだけの土地があればこういうものも入れることが可能か、不可能かと検討されて、それで、一定絞り込んで、需要との関係を見ながら決めていくのだろうと私は思うのですけれども、普通はそういうふうになっていくと思うのですが、そういうときに、高齢者福祉施設が１０年先には１,３６７人も入所する人が出てくるというときに。","respondent":"桑村副区長","answer":"そういうお声の中で、今、高齢者施設というものについて、区のほうで判断ができないということであります。防災機能あるいは地域の声を重視した跡施設を、これからまだ１年半近くあるわけですので、その中で検討するということしかお答えができないのではないかと思います。","voiceIndex":15,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"確かに地域の方たちは、避難、安全というところを求めておられる。しかし、避難の不安だとかがある中で、一定の規模の学校跡施設というのを活用して、そういう機能を持たせてほしいという、そこは当然だと思います。しかも、区長は防災第一とおっしゃっています。適地を探しているという答弁も去年の１０月のときにはされたのです。当然ご存じのことだと思うのですけれども、その適地の１つではないのですか。","respondent":"桑村副区長","answer":"ここのところのそういうご要望と、それから、この跡地の施設建設というのは、今、この段階では判断できないというふうに申し上げているわけで、何も高齢者施設をつくらないとか、それはこの地域ではなくて結構なのですけれども、全区域に言っているわけではありませんので。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"そういう角度で質問をしているわけで、そして、同時に、住民の地域の方々が切望しておられる、防災の機能を持たせてほしいという、そこも当然だというふうに、それも表明しているから、そちらをはねのけて特養にと言っているつもりは全くないということは誤解しないでいただきたいと、こういうふうに思っているわけです。人の発言中、言わないで。気が散りますので、お願いします。こういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"今、いろいろ質疑を聞いていて、今、ここに請願の記載のとおり、こういうものにしてしまうと決めてしまうというのは、前も行革でそんな話があって、ある程度区民のいろいろな要望があったり、地域バランスを考えて、先行きどういったものがいいのかというのを考えながら、しばらく検討してもらう時間があるのではないかということで、前回も願意に添いがたいという返答になったと思うので、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"結論を出します。先ほどお話ししたように、少し余裕を持たせて理事者のほうで考えて、区民の状況、社会情勢、いろいろなことを考えながら選択肢をつくっていくという余裕を残しておいたほうがいいので、願意に沿いがたいというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"結論を出してください。今期の行財政改革特別委員会で、施設の有効活用プランを調査、議論させていただいて、まさにこういうことを地域の声、行政需要、さまざまなその他のたくさんの声、議会の声も含めて、ある意味ではバランスをしっかりとって、区民の期待に、ニーズに応えていくということも改めて考慮しながら、そういった意味で、願意に沿いがたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"今回、結論を出していただきたいと思います。住宅密集地であるということ、それから、これは２６号線ができればアクセスがよくなりますので、そういう意味では、福祉施設でも入居系というより通所系のほうが合っているのかという感じもいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"今の議会の方向性を縛るという、議会の前回の結論を見てというふうな発言は、私は適切ではないと思います。住民の思いを出している、そのことに制限をつけるものではないから、だから、私はそういうふうには言うべきではないと思います。私は、先ほどの質疑の中で、賛成の立場で、ぜひこれを受けとめていく立場で質問したのですけれども、そういう趣旨で採択をしたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤原委員","kind":"意見","question":"本日、結論を出してください。それで、先ほど副区長からもお話がありましたけれども、まだ決めていないのだと。防災も高齢者も少子化もという形で出てくると思うので、それで、私たちでというか、私ももうあと５０日ぐらいで議員の選挙がありますから、また新しいメンバーで、いろいろな意味で協議していただいて、今、ここでがっちり固めてしまうのはどうかと考えていますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"済みません。議会にこうした請願を出すなと言ったつもりはありません。それの、請願を私たちが審議して、いろいろな思いでその結果を返していく、それについて、やはり出された方、あるいはその問題に関心を持っている方は、議会の思いというものもぜひご理解いただきたいと思うわけで、それを出すななんていうことを言ったことは一切ありませんので、誤解のないよう、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"今の発言なのですけれども、住民の、請願を出した方に、どういう内容で戻ってきますか。「願意に沿い難い」の一言です。具体的な趣旨というのはあまり書いていないです。その中で、先ほど、ここでこういうふうな結論を出したのにというふうにおっしゃった、そのことは違うのではないかということで言ったということですから、そういうふうに理解していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-015"},{"speaker":"あべ委員","kind":"意見","question":"ここで最後にいたしますけれども、私の思いが全く伝わらずまた誤解されているということだけは、言っておきたいと思います。私の意図は私が一番理解しておりますので、それをどれだけ曲げて受けとめられても、それは私の思いとは全く別のところですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-016"}]},{"id":"topic-02","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"若林委員","kind":"意見","question":"１点だけ、言葉遣い、ちょっと今気がついて、施設有効活用プランのことを「以下、本プランと省略する」とあるのですが、本プランというと、大体、プランをつくった側、いわゆる区側の言葉遣いで、議会からこういった場合には「同プラン」というふうに言うのでは、議会がつくったものではありませんので。という言葉の分け方をご検討いただければ。この２つだけ、言葉遣いで申しわけございません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-017"},{"speaker":"あべ委員","kind":"意見","question":"特段ありませんが、今のご意見については同意いたします。〔「ありがとうあります」と呼ぶ者あり〕 だって、皆さまがどうなのかわからないと、変えるか変えないかわからないでしょう。","respondent":"中塚委員長","answer":"ただいま、「同プラン」と、また、記のところの修正についてご意見がありましたけれども、頂戴したご意見をもとに、具体的検討事項のまとめ（案）を正副で修正させていただいて、議長に提出していきたいと思いますけれども、これでよろしいでしょうか。","voiceIndex":43,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"気になったのですけれども、記書きの１の一番初め、「実施初年度により」という表現になっていますけれども、これ、「実施年度により」、「初年度により」、意味がいまいち私が理解できないのですけれども、「実施初年度により」、 〔「「は」だけでいいですかね。〔「初年度だから結局、結論が出ないと」と呼ぶ者あり〕 可能性として、もろもろの実施が、初年度に実施されたからということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":15755,"voices":58}},{"id":"h27-20150226-18","meetingId":"h27-cm02","date":"2015年2月26日","dateIso":"2015-02-26","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午前１０時１１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員長","kind":"質問・要望","question":"ありがとうございました。引き続き、私からご挨拶申し上げます。本年は、２０２０年に向けて、第１回目、初年度の委員会が立ち上がり、皆さんと１年間過ごさせていただいて、特に初年度ゆえの大事さで、東京都への要望等、かなり時間を割き、そして皆様の意見を集約できたことが本当にまず一番、思いの中であります。本当にありがとうございました。では、ほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6470#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":2702,"voices":12}},{"id":"h27-20150302-3","meetingId":"h27-c-budget","date":"2015年3月2日","dateIso":"2015-03-02","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢副委員長","kind":"質問・要望","question":"会派におかれましては、一人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間を含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で、振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先に産業経済費補助金でありますけれども、これは恐らくプレミアム付区内共通商品券に移されるものと思っているわけでありますけれども、私ども自民党は、従来から１０％のプレミアムで１０億円分の発行を求めてまいりました。そういうことを踏まえた上で、国庫補助金等を活用して、今現在、品川区はどういうお考えでいるのかということを改めてお聞かせください。お願いいたします。","respondent":"米田商業・観光課長","answer":"通常の緊急経済対策としてのプレミアム付共通商品券事業につきましては、１０％のプレミアム率というようなことで実施しておりましたが、今回このような形で国から交付金がおりてくる見込みが立ちましたので、今回につきましては、プレミアム率２０％といたしまして８億円。","voiceIndex":9,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり、これを活用して区内の商店街が振興することが一番の目的だと思うので、そう考えてまいりますと、いわゆる販売の時期であるとか、それはなるべく早くお願いしたいのが１点と、できるだけ区内の商店街の中で活用できるように、利用できる店舗を増やしていく等のお考え、それからあとは、１人当たりの発売金額についても、今現在でいいのですけれども、どのようにお考えか改めてお聞かせください。","respondent":"米田商業・観光課長","answer":"あわせて、区内の商店街などに働きかけておりまして、今回、大規模な商品券事業が新規に行われるということで、加盟店の増強については、早速商店街連合会から各商店街、それから一部、今後新たに取り扱いたいという店舗もありますので、そちらにつきましては。","voiceIndex":11,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、４月中旬ぐらいの発行予定を考えているということを確認いただきましたので、いろいろな意見を聞かれていると思いますけれども、やっぱり使える店舗を拡大していただきたいというのは結構あるのです。それから、あわせて区民への周知も改めてお願いしておきます。お願いいたします。","respondent":"村尾学校支援担当課長","answer":"まさに子どもたちの不登校の問題、それからＬＩＮＥ等による情報の関係につきましては、現在も含めまして、子どもたちに対して不登校または長期欠席児童の確認、また、ＬＩＮＥ等につきましては、各学校で情報モラルについての研修を今年もやっておりますけれども。","voiceIndex":15,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こういういろいろな情報をきちんと把握をして、それを分析をして評価をして対処をしていったとするならば、恐らくこういう悲惨な事件にならなかっただろうということが容易に想像されるわけであって、今の答弁内容はそのとおりであるし、進めていってほしいのだけれども、要は、そういう案件に対して教育委員会の方々がいかに敏感になって。","respondent":"村尾学校支援担当課長","answer":"まさに学校からさまざまな情報が上がってくるように、現在も取り組んでいるところです。各学校から子どもたちの情報について入ってきますと、すぐに学校を訪問し、それぞれの状況等を確認しながら、こちらのほうで対応させていただいているところです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もう１つ踏み込んで思うのが、私たちの手に触れることができないＬＩＮＥ、非常に情報ツールが発達しています。例えば、教育委員会の方々でＬＩＮＥをやっている方はいらっしゃるのでしょうか。そういうようなことを思ってしまう。具体的にＬＩＮＥがどういうものであって、それが安易に情報交換できることをわかった上で対処をとっていくべきと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"村尾学校支援担当課長","answer":"各学校では、このＬＩＮＥ等を含めまして子どもたち向けの研修会を含めながら、まずはこの危険性、それから使い方のモラル等につきましては、十分これからも指導を進めていきたいというふうに考えております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"意見","question":"子どもたちは、そういう目の見えないところで情報交換をしているという、それが今回の悲惨な事件にもしつながっていたとするならば、やっぱりそういう新しい情報ツールに対してもっと敏感であるべきであるだろうし、そこに出てくるさまざまな情報について、児童、生徒を指導するだけではなくて、その中に入っていって教育委員会が具体的な指導を展開していくということを次にしていかないと。","respondent":"村尾学校支援担当課長","answer":"委員おっしゃるとおり、区のほうでも、まさにまずどのような情報がネット上に流れるかも含めまして、検討を進めているところです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけど、もう一歩踏み込んでほしいという思いなのです。インターネットとか、ＬＩＮＥとか、いろいろなことが展開されているのだから、それで情報交換がされて今回の事件につながったことは既に報道されているわけではないですか。やはりそのことに対しては、ぜひ敏感になって対処していただきたいということで、お願いでありますので、よろしくお願いいたします。お願いいたします。","respondent":"田口交通安全担当課長","answer":"秋に機種選定に基づいて詳細な設計の実施予定、冬頃に実施設計結果を踏まえて住民説明会を行う予定です。実際に工事が始まるのが来年度、平成２８年度４月以降で、開設予定は平成２９年４月を予定しています。","voiceIndex":23,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"今のところの予定では３基６００台ということであります。これを建設する背景について、勉強していますのであれですけれども、もう時間がありませんので、この６００台分でどれぐらいの大森駅周辺での違法駐輪が減るということをお考えでしょうか。そのことだけお答えください。お願いいたします。","respondent":"田口交通安全担当課長","answer":"当初、大森駅周辺は５００台不足ということで予想しておりました。そのうちの１６５台は平成２５年度に整備をしています。残り３３５台ですが、今回、６００台の設置ということでありますので、不足分は補えるのかというふうに考えております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"南委員","kind":"確認","question":"ですから、その辺についてどういうふうに考えておられるか。増やす方向も持っての調査なのかどうか、その辺を確認したいと思います。","respondent":"田口交通安全担当課長","answer":"今回、公園の敷地などもありますけれども、それ以上の台数の６００台を設置すれば、当面は需要に耐えられるのではないかということで、今回、６００台ということで計画をいたしました。","voiceIndex":28,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"私は、需要予測というのはしていく必要があるというふうに思っておりましたので、それはぜひ進めていただきたいし、その結果もしっかり見届けていきたいと考えています。だから、そういう点ではもっともっと増えていくと、八潮近辺にも勝島にも大量に大きなマンションができておりますので、そういう点でやっぱり増やしていくという方向性を持っていただきたいということを確認しておきたいと思います。","respondent":"田口交通安全担当課長","answer":"増やす方向ですが、先ほどお話ししたように、そのために今回、駐輪の需要予測というものを行います。この調査結果をもちまして、今後の整備については検討していきたいと考えております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"私からは、６９ページ、プレミアム付区内共通商品券発行助成と、５３ページの地方版総合戦略策定等についてお伺いいたします。先ほど、伊藤委員のほうから質問があって、ご答弁がありました。先ほどの答弁の中で、プレミアム率については２０％、発行額については８億円という確認ができました。その上で、この今回発行するものの使用期限、これはいつまでなのか教えてください。","respondent":"米田商業・観光課長","answer":"こちらにつきましては、国のほうの１つの指標ですけれども、発行から６カ月以内に使うということを１つの指標としていただいておりますので、この指標に沿うような形で現在考えておりまして、４月の、先ほど委員のほうからも中旬とございましたが。","voiceIndex":33,"id":"exchange-012"},{"speaker":"つる委員","kind":"確認","question":"６カ月以内ということで９月末日という確認ができました。その上で、今回、生活支援型ということで銘打ってあります。これを解消するために、発行単位を本当に可能な限り、例えば１万円以下、１口５,０００円の発行とするなどして、１人でも多くの方にこの商品券を手にとっていただく、こうした工夫が必要ではないかと思いますけれども、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういった意味では、１０％のプレミアム率ですと、やはり発行額としては１万円が妥当かなというようなことで考えてありますが、今回、２０％のプレミアム率ということ、それから、なるべく多くの方に買っていただいて地域内での消費ということから考えまして。","voiceIndex":35,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"５,０００円で６,０００円だと、２０％ですからお得感がかなり実感していただきやすいのかなと、そうした観点で、発行に際しては事務が非常に煩雑になったり、大変なこともあると思いますので、そうした側面的な支援も含めて、商連等としっかりと連携をとっていただいて、ぜひ５,０００円で進めていただきたいと思います。","respondent":"米田商業・観光課長","answer":"ご指摘のありましたように、いわゆる購入された方に対して実際に消費額がこの事業をやったときとやらないときでどれだけ差異が出たのか、それから、どのようなところで使ったのかというようなことの調査を行うことは必須となっておりますので。","voiceIndex":37,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きます。５３ページの地方版総合戦略策定等についてであります。まち・ひと・しごと創生について、政府が決めた達成すべき長期ビジョンについて、人口を２０６０年に１億人、経済成長を２０５０年ＧＤＰ実質成長率１.５％から２％という形で銘打たれています。今申し上げたことをそれぞれどう進めていくのか教えてください。","respondent":"柏原行財政改革担当課長","answer":"この総合戦略の考え方としては、今ございましたように、ＰＤＣＡ、ＫＰＩという設定、それからチェック機能を働かせなさいということでございまして、産業界、学識、経済界であるとか、金融機関。","voiceIndex":39,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"平成２７年度の予算でありますけれども、（仮称）しながわネウボラネットワーク検討経費も計上されておりまして、その積極的な検討に期待をするところでありますけれども、この（仮称）しながわネウボラネットワーク、これは国が言うところの子育て世代包括支援センターの整備に沿ったものであるかなと、このように捉えておりますが。","respondent":"柏原行財政改革担当課長","answer":"個々の考え方、今、ネウボラのお話も出ましたけれども、まず長期基本計画、総合実施計画が我々の基本的な事業の考え方です。それに合致させていくような形での計画になります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"本予算のほうでも確認をさせていただきたいと思いますが、本当に今後の品川区、今、地方創生というふうに言われておりますけれども、ある意味で、東京の大きな目標から考えるならば、地方、いわゆる地域創生という言い方も当たるのではないかというふうに思っているところで、本当に品川区も今人口が増えてきておりますけれども、そうしたことも含め、また今後、減少傾向になることも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"私からは、４２ページの都支出金の民生費補助金と、６３ページのひとり親家庭支援事業更正減額について伺います。子育て支援は、品川区の最重要課題としてありますけれども、このたびの補正予算を見てみますと、東京都の補助金が１億４,８３６万６,０００円の減となっておりますけれども、これは財源更正されたという記述でありますが、具体的にどの科目に移動したのかお伺いします。","respondent":"竹田保育課長","answer":"安心こども基金交付金について、今回、財源更正がございまして、財源更正とは財源の調整のことを言いますが、今回、この科目の事業のうち、国から特に緊急の対策が必要と判断された一部の事業が、３８ページ。","voiceIndex":45,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"この中の保育緊急確保事業費補助金に移行したということですけれども、その中の区内私立保育園経費について伺いますけれども、まず、これはどのような事業になっているのか伺いたいと思います。","respondent":"竹田保育課長","answer":"３８ページ、３９ページに記載のあります保育緊急確保事業費補助金の充当事業の区内私立保育園経費ですが、この中には、保育士等の処遇改善を目的とした保育士等処遇改善臨時特例事業があります。","voiceIndex":47,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"品川区内に処遇改善事業は、今、どのくらいの対象施設があるのか、そしてまた、その対象になっている施設の総額は幾らぐらいなのか、あわせて伺いたいと思います。","respondent":"竹田保育課長","answer":"区内の私立保育園全園２８園を対象と考えておりまして、予算総額が約５,１４５万円でございまして、国からの補助が４分の３、金額が３,８５８万９,０００円です。なお、都からの補助は、補助率が８分の１、金額が６４３万２,０００円です。","voiceIndex":49,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"この処遇改善事業の対象は、私立保育園だけだということですけれども、私立保育園だけという理由は何か。そして私は、このような事業は私立保育園以外も対象にしてはいかがかなと思うのですけれども、こういった事業の拡大の可能性についてもあわせて伺いたいと思います。","respondent":"竹田保育課長","answer":"先ほど、私立保育園と申し上げましたが、認証保育所につきましても別事業で補助の対象としています。公立の保育園につきましては、人事院勧告等で適切な処遇をされておりますので、主に私立保育園、認証保育所等を対象としています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"ぜひとも区のほうにもさまざまな事情があるとは思いますけれども、私としても今後は私立保育園以外でもお願いしたいと思います。次に、６３ページのひとり親家庭支援事業について伺います。ひとり親家庭への支援は、子育て支援の一環として重要なものと考えますが、これに関する事業について、今回の補正予算では、４６９万１,０００円の更正減額が行われていますが、それについて伺いたいと思います。","respondent":"伊崎子育て支援課長","answer":"具体的には、予算では、継続が６件、新規で１件と見込んでおりましたが、継続が３件で新規がゼロということで実績として出ております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"新規がゼロということなのですが、では、今後はどのような形になっていくのでしょうか。","respondent":"伊崎子育て支援課長","answer":"ですので、今年度は実績がゼロでございましたが、今後も継続をしていきたいと考えております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"続きまして、４４ページの土木費補助金について伺いたいと思います。東京都の支出金では、密集住宅市街地整備促進事業費とありますが、その中で１億８,４１３万３,０００円減額されております。品川区は、密集住宅街が多いと私は思うのですけれども、なぜその２つを減額されたのか伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"それから２つ目の不燃化１０年プロジェクトにつきましては、こちらは不燃化特区の支援メニューの中に専門家派遣、それから除却助成というのがありますけれども、これが当初の目標、見込みに対しまして実績が伸びなかったということで、そのときの歳出連動の減額となっております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"そうしますと、今まで中延地域とか、まだなかなか周知されていなかったということですね。ではないですか。今後、一生懸命取り組んでいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"最終補正ということで、３６ページの歳入について、歳入増と基金積増しを中心に、区民の暮らしを支える財源というところを伺いたいと思います。そしてもう１点、最終補正には消費税増税分は基本的に含まれていないというお話を伺ったことがあるのですけれども、消費税増税分について、補正と新年度予算、当初予算の扱いの違いというのでしょうか、そこをご説明いただきたいと思います。","respondent":"黒田税務課長、本城企画財政課長","answer":"今後の見通しですが、住民税は前年の所得にかかる税ですので、所得が伸びているというような景気の回復の動向であれば税収も伸びるというふうに考えておりますし、これには人口増も絡んでまいりますので。今回、補正の中身として、歳入増としたところ、予算計上しているものが幾つかありますけれども、一定規模の増ということで見込んだものについて今回計上したということで、地方消費税交付金については。","voiceIndex":61,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"昨年の決算特別委員会のところでは、前年比で３４億円、区の政策判断で使える規模が増えていると。当初予定していた部分を超えるお金が入っているのに、それを全部貯金に回すというのはどういう考えなのか、緊急対策に充てる考えはないのか、そこの最終補正の考え方を伺いたいと思います。","respondent":"本城企画財政課長","answer":"１つ目は、今回、基金に主にしたというのは、最終補正の性格上、年度最後の調整ということがありますので、新たなものというよりも、主に将来に備えて基金という形で、これから確実に需要が見込まれていますので、それに備えるということと、あと。","voiceIndex":64,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"例えば、２００９年１月には臨時議会を開いて補正を示している、例えば緊急経済対策を組んだこともありました。私は今の区民の格差拡大の暮らしの実態や、また保育園が足りないという、こういう実態を見ると、既に３０億円もの区の判断で使えるお金が増えている中で、こうしたところに充てるという補正を組むことを考えることはなかったのか、どういう状況だったのか、そこの状況を伺いたいと思います。","respondent":"本城企画財政課長","answer":"今回も基金ということで最終補正の時点的な性格から、主立ったものは将来に備えたということで申し上げましたが、冒頭の説明でも、当初見込みより上回ったさまざま給付関係のものを増額したり、今年度の中にもそういう補正という形で歳出増をしているものもあるものです。","voiceIndex":66,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、今の格差拡大の区民の暮らしの実態、また、保育園の不足、こういう事態を見ているときに、最終補正ではなくて、その前に、例えば補正を組んでやるとか、最終補正でも手だてを組むとか、最終補正というのは調整だけではなくて、緊急度があるからここで組んで、議決をして直ちに執行しようと、そういう性格も私はあると思いますので、なぜ収入増分を積み増しでするのか。","respondent":"本城企画財政課長","answer":"それらを含めて、今回の最終補正の段階で現実の目の前の需要に対応しつつ、将来に備えているところです。","voiceIndex":68,"id":"exchange-029"},{"speaker":"中塚委員","kind":"意見","question":"予定していなかった歳入増まで基金を積み増すのではなくて、保育園や暮らしのためにこそ充てるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"５３ページの全庁共通プロジェクト推進経費なのですけれども、そもそも全庁共通プロジェクト推進経費とは何でしょうか。次に、６７ページ、妊婦健康審査なのですけれども、平成２７年度がネウボラを検討しているそうですが、妊娠期から子育て期の支援に向けて、現状をどう捉えた上で、どういう視点で検討がなされているのか伺います。まさに諸行無常だなと感じしています。","respondent":"柏原行財政改革担当課長、太田品川保健センター所長、米田商業・観光課長","answer":"まさしく全庁にかかわるような内容で多岐にわたっている部分があります。そういったところがあるというのが１つ。産後に至りましては、すくすく赤ちゃん訪問で産後うつのチェックや、産前産後のすこやかサポート事業、母乳相談などを実施しております。これは区内を移動する方の利便性に供するということで、区内移動を想定して一部タクシー会社と協定を組み。","voiceIndex":72,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと妊婦健診なのですけれども、私が幼児人口の動向についてお伺いして、それのお答えがなかったのと、この動向を受けてさまざまな施策にどう影響があるかということもお伺いしたい。出生数に関しても、推移と今後の見通しを区としてはちゃんと押さえておかないと、これからの施策に反映できないと思うのですけれども、全くその答弁がなかったのでお伺いします。","respondent":"米田商業・観光課長、柏原行財政改革担当課長","answer":"基本的には商店街の振興というようなことでやっておりますので、あくまでも例外的なということで、使用されている数値といたしましても、ほとんどパーセンテージとしてはそんなに高くないものということで、これまでどおり。現在は、出生数、品川区の場合は伸びておりまして、年間３,０００人規模で伸びている状態。さらに、例えば平成２５年ですと３,３００人であるとか、平成２６年は３,４００人といったような形でどんどん伸びている状況にあります。","voiceIndex":76,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"企画財政でお答えをいただいたのですけれども、そういう意味において、いわゆる全庁共通プロジェクトという形でやるならば、確認なのですけれども、担当の課にはきちんとおりているのですよね、こういう人口動態とかそういうことが。それで施策をきちんとやっているのか、子育ての担当の方からお返事をいただきたいのですけれども。","respondent":"伊崎子育て支援課長","answer":"人口動態推計につきましては、長期基本計画の策定時に企画財政課のほうから全庁的にきちんと周知をされております。私どももこの推計に基づきまして、長期基本計画の策定をしたわけですし、今後につきましても実態に合った形で、なお推進していきたいと考えております。","voiceIndex":79,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"私は、３９ページ、４５ページのファミリーサポートセンター運営費ほか１０事業の確認をさせていただきたいと思います。平成２５年度の平塚ファミリーサポートセンターの活動件数は２,７７５件、大井ファミリーサポートセンターは３,７４１件ですが、平成２６年度の現在把握されている活動件数は、それぞれ何件程度でしょうか。","respondent":"伊崎子育て支援課長","answer":"将来像につきましては、先ほども議論の中でございましたが、このファミリーサポートセンターも保育緊急一時確保事業ということで、来年度から、子ども・子育て支援新制度の中の１つの事業として位置づけられますので。","voiceIndex":82,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"昨年度に比べまして、１月末時点の数となりますので、少し微増しているのかなというふうに見受けられるのですけれども、今、課題の中にございました提供会員数、こちらが微増ということでおっしゃっているのですけれども、こちらの活動件数が少し増えていることに対しての現在の提供会員数と依頼会員数のバランスはどのようになっているのでしょうか。","respondent":"伊崎子育て支援課長","answer":"今の数字から見ましても、非常に提供会員の数が１桁違う状況でありますので、こういった方たちについて、今現在、年３回ほどの募集をしまして、研修をして、会員登録をしていただいているのですけれども、そちらの周知の方法とか。","voiceIndex":84,"id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"今後また周知方法ですとか、募集の強化について、積極的にご検討していただければと思います。現在の育児支援事業、各種交流事業、育児不安、悩み、気がかりなどを解消するための相談事業などに加えて、品川区での子育てがより楽しく、子どもにとっても保護者にとっても有意義となるような機会を積極的に創出していただきたいと考えますが、今後の在宅育児の支援について、ご所見をお伺いいたします。","respondent":"伊崎子育て支援課長","answer":"委員ご指摘のとおり、在宅の子育て支援を充実していくことは、１つの大きな課題です。女性のライフコースはさまざまですので、そういったそれぞれの生き方に合わせまして、支援が必要なところには手を打っていくということは大事なことだと考えております。","voiceIndex":86,"id":"exchange-036"},{"speaker":"横山委員","kind":"質問・要望","question":"現在、シルバーセンターとの交流等は既に行っている部分があるのは存じておるのですけれども、これから例えば品川区の特色として、在宅支援、在宅でぜひ品川区で子育てをしてみたいという方を増やしていただけるような、そういった視点をもってさらに進めていっていただけたらと思います。最後は要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"１問目ですけれども、受給者死亡後の家財等の処分についてお伺いをしたいと思います。今回この補正で５,２７２万３,０００円追加されております。平成２５年度の受給者の死亡者数、お亡くなりになった数を教えていただけますでしょうか。","respondent":"伊東生活福祉課長","answer":"死亡者のお問い合わせです。平成２５年度で生活保護受給者の死亡廃止の件数としまして、２４３件ですので、そちらの方がお亡くなりになったです。","voiceIndex":91,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"２４３件、１年間でお亡くなりになっている、死亡廃止になっているということでした。我が会派も死亡後のことについて、私も含めて何回も同じご相談を受けておりますが、解決がない問題でもありますので、関連して質問します。このようなケースについて教えてください。保護受給者がお亡くなりになった場合、生活福祉課では現在どのような対応をされているのか教えてください。","respondent":"伊東生活福祉課長","answer":"残念ながら現在、保護基準の中では、そういう原状回復費用につきましては出せないというような状況です。委員ご指摘のとおり、葬祭扶助までは出しているところです。これも親族等がいない場合には葬祭扶助を出しているです。","voiceIndex":93,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"現状を答えていただきました。この問題には三者が登場します。もう一度伺いますけれども、先ほど述べた三者のうち、受給者が死亡した場合、誰が家財道具を整理し、片付け、処分をするべきなのか、道義的とか、社会的とか、法律的とかあると思うのですが、教えてください。敷金の扱いについても一般的なことで結構ですので教えてください。","respondent":"伊東生活福祉課長","answer":"それと、契約上に保証人等がいれば、保証人のほうにもご協力をいただく。そして、当然、契約の相手方であります家主とか、不動産屋とかでの対応が必要になってくるのかと思います。","voiceIndex":95,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"最後の三人目の保証人ですけれども、これも法律上はどうかあれですけれども、受給者の方の生活の立て直し、思いやりで生活の面倒を見ている方が賃貸契約の保証人になってくれと泣きつかれて、仕方なく引き受けている場合がかなり多い。だから、私が今申し上げたような現実を踏まえ、生活福祉課ではこのことについて、現状どのような問題意識、課題意識をそもそもお持ちなのかどうか教えてください。","respondent":"伊東生活福祉課長","answer":"当然、家主、敷金等でまかない切れないという部分は、先ほどの十数万というようなご指摘もありますけれども、中で出せないということで、非常に我々のほうにも困っているというようなお話があったということは認識しています。","voiceIndex":97,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"意見","question":"課長もいろいろな現状はご存じで、ただ、はっきりとしたご答弁はなかなか難しいのかなとは思います。ですが、例えば、１つ考え方として、行旅死亡人という考え方があります。そこについて、家財道具の処分といえば、清掃事務所のほうが考えられるのですけれども、この問題に関して何かお知恵がないのか、お聞かせください。","respondent":"伊東生活福祉課長、小林品川区清掃事務所長","answer":"行旅死亡人のほうですけれども、やはりこちらに関しても生活保護法と同じように、家財処分等々につきましては出せる状況がなく、一般的な葬祭に関しての部分は自治体のほうで負担するということにはなってありますので。本件の場合、ごみが生成されたのが生きている間で、その排出が死後になるということから考えますと、今、説明がありましたように、生前の権利義務を継承する者がおらず、その負担等が困難という場合には。","voiceIndex":99,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"清掃事務所長のほうからそういうお言葉をいただきましたので、また検討していただいて、みんなが悲しい思いをしないような、そしてお亡くなりになった方を弔えるような、そのような制度にしていっていただきたいと思います。７６ページ、大崎駅西口バスターミナルの話です。７６ページだと３,２００万円の減額になっていますけれども、これはどういう意味なのか、簡単に教えてください。","respondent":"溝口都市開発課長","answer":"今回の補正予算の３,２００万円の減額の件です。これにつきましては、今年度内に委員会等でご報告しました国内他都市と結ぶバスターミナル機能ではなく、普通のバスのターミナルをつくるということで、当初、予算計上をしていたものです。","voiceIndex":102,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"それに加えて、新年度の内容にも入ってしまうのですけれども、今回こういうふうに削減をされて減額をされましたので、そのことでちょっと唐突感があるので、背景についてお伺いしたいのですが、今回、具体的に大崎と高速路線バス、どこを結ぶのか、その路線が走るのか教えていただければと思います。","respondent":"溝口都市開発課長","answer":"今回計画しております国内他都市を結ぶバスターミナルですが、１つは、京都・大阪という関西圏、または、さらに仙台などの東北圏、あと新潟ですとか富山の中部地方、そういったところを結ぶ高速バスを予定しているものです。","voiceIndex":104,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"２５番目として品川区の大崎が名乗りを上げるということでよろしいのでしょうか。これもある意味ではノウハウを持っているのかなということでもあるのですが、なぜ事業のノウハウを直接持っている株式会社ではなくて、剰余金の分配を目的としていない一般社団法人が今回選ばれたのか、その点、何かメリットがあるのか教えてください。","respondent":"溝口都市開発課長","answer":"委員ご指摘のとおり、現在、関東地方で６カ所、今回新たに法に基づくバスターミナルの事業としては７カ所目のターミナルの開業という形になるというふうに考えています。","voiceIndex":106,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり新しい形だと思いますので、一般質問でもほかの委員からありましたが、運営の透明性の確保は進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問","question":"私からは、７１ページ、先ほども質問のありました大森駅水神口自転車等駐車場について、また、６９ページ、空き店舗活用支援事業、まずそこを聞きます。７３ページの大森駅歩道橋建屋調査設計委託について、先ほど調査方法が変わって減額になりましたということで、この調査方法がどう変わったのか、その辺を教えていただければと思います。２つお願いします。","respondent":"田口交通安全担当課長、稲田道路課長","answer":"こういったことも加味しながら当初の計画を変更したものです。当初、ＪＲの軌道敷内から歩道橋を調査するというふうに考えておったのですけれども、これはＪＲのほうとしても東海道本線とかが通るところであるので非常に影響が大きいです。","voiceIndex":110,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"先に委託調査の方法が変わったという部分なのですが、もともと最初に考えていた工事の手法と変わったということで、これは最初からＪＲとの打ち合わせとかという部分で、今聞いていると、最初からこの手法にという考えもできたのかなという部分があるので、その辺がどうしてここになって変わってきたかということを教えていただきたいと思います。","respondent":"稲田道路課長、松代防災まちづくり事業部長","answer":"最初から変更した後のような形で考えられなかったのかですが、これは基本的にはやはり外部からその場所を点検していくというのが基本のスタンスです。今後のほかへの対応等につきましては、まずはこの大森駐輪場でつくって、その辺のところを様子を見ながら今後の展開等についてはよく研究検討していきたいと、このように考えておるところです。","voiceIndex":113,"id":"exchange-048"},{"speaker":"大倉委員","kind":"質問","question":"当然調査されてつくるということでありますので、そこは十分に承知しているところであります。そのほかに、今まだまだ違法駐輪が多い。駐輪施設が足りない場所がこの品川区にも各駅、各商店街であったり、いろいろなところにあるかと思います。そういったところの地下とかの埋設物等の調査というのは行われているか、また今後行っていくのか教えてください。","respondent":"田口交通安全担当課長","answer":"これも来年度、こういった駐輪場をあわせまして、先ほど言いました需要予測も含めてなのですが、どのような整備手法がいいのか、そういった基本方針をまとめて今後の整備に反映させていくという計画です。","voiceIndex":118,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"やはり地元の人の声を聞くと、例えば商店街であれば、病院の前に違法駐輪が多くて救急車がとまれなくて困ったなどということも以前お話しさせていただきましたが、ぜひともそういったところに駐輪場等を設置できるように調査をしっかりしていただいて、また、地元の人の声も聞いていただきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-050"},{"speaker":"井上委員","kind":"質問・要望","question":"最初に、先ほど、ひとり親家庭支援事業のところの減額の質問がありましたけれども、これで母子家庭等高等職業訓練促進給付事業についてお答えをいただきたいのですけれども、新規需要もなく減額に至ったということで、その理由をどう分析しているかということをお伺いしたいのですけれども、利用者ニーズがないということなのか、それとも制度的に利用勝手が悪いというものなのか。","respondent":"伊崎子育て支援課長、柏原行財政改革担当課長、米田商業・観光課長","answer":"母子・父子世帯の自立支援教育訓練給付金の件についてお答えをいたします。この国が出したビジョンというのが、日本全国が人口減少に向かっていく。区民の消費の回復が鈍ってなかなか回復しないというような状況の中におきまして、国のほうでこういう施策をとり。","voiceIndex":122,"id":"exchange-051"},{"speaker":"井上委員","kind":"提案","question":"私は、ひもつきのお金に対して財政当局はどのようにお考えですかということを質問したのであって、ちょっと答弁は質問の意図とはずれているということをお伝えしたかったと思います。次の質問で、７５ページの公園新設改良費で基金繰入金から４億２,０００万円入れないで、一般財源に財源更正しておりますけれども、これについて具体的な内容をお知らせいただきたい。","respondent":"本城企画財政課長","answer":"あわせて、今回、税あるいは一般財源的なものも当初見込みより多かったところがありましたので、その部分についてはプラスして取り崩さず、今回このような処理にしたものです。その合わせたものを今回繰り越しも含めて、東品川公園については対応しています。","voiceIndex":126,"id":"exchange-052"},{"speaker":"井上委員","kind":"意見","question":"ここに一般財源として使われたということは、公園新設ではなくて、ほかのものに使われたというふうなことがわからなくなってしまうので、補正のこの書類の書き方というか、その辺もわかりにくくなっているということを指摘して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-053"},{"speaker":"沢田委員","kind":"質問","question":"３９ページの国庫支出金の国庫補助金の地域介護・福祉空間整備等交付金の地域密着型サービス施設整備費助成と、それから４３ページの同じく地域密着型サービス施設整備費助成、それから、民生費の生活保護費の扶助費のところでお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"地域介護・福祉空間整備等交付金、こちらの中で地域密着型サービス施設の整備費助成を見込んでいたところですけれども、こちらにつきましては、グループホーム２カ所、それから小規模多機能型居宅介護を１カ所ということで９,０００万円見込んでいたのですが。","voiceIndex":130,"id":"exchange-054"},{"speaker":"沢田委員","kind":"質問・要望","question":"要介護度は平均で大体どれぐらいなのかということをお聞かせください。それぞれ６カ所いろいろなことをされていますけれども、個々に経営状況というか、採算性というか、そういうことも把握されているかと思うのですけれども、その状況はどういうふうな形になっているのでしょうか。お聞かせをいただきたいと思います。","respondent":"大串福祉計画課長","answer":"介護の度合いですけれども、こちらにつきましては、いわゆる要支援の方から要介護の方まで含めてといった形になっておりますけれども、基本的には要介護３以上になりますと特養という形になってまいりますので。","voiceIndex":132,"id":"exchange-055"},{"speaker":"沢田委員","kind":"質問","question":"今そういったお話がありましたけれども、６カ所の中で複合的に運営をされているところはそれなりの採算がとれているところも、しっかりとれていたりということがあると思うのですけれども、単独で運営されているところもあると思うのですが、こういったところに対して、やはり複合型だとそれなりの施設の場所も必要ですし、整備に大変時間がかかるという部分もあると思うので。","respondent":"大串福祉計画課長","answer":"そういった形での施設整備に対しての区のほうの支援といたしまして、今年度は新規の開設がなかったといったところで減額の補正をしていますけれども、基本的にはこういった形で施設整備をされる方に対しての支援ということで、予算計上を毎年やっておるところです。","voiceIndex":134,"id":"exchange-056"},{"speaker":"沢田委員","kind":"意見","question":"そういった中で、在宅介護支援センターとの連携のことでも聞きたいのですけれども、在宅介護支援センター等、あと特養でも、ショートステイをやっていらっしゃると思うのですけれども、結構そういった特養の中のショートステイというのも利用率がかなりいっぱいになっているところもあったりして、在宅介護支援センターからのそういったショートステイと、あと。","respondent":"永尾高齢者福祉課長","answer":"それであと、ショートステイというよりは、小規模多機能は通所と泊まりをその方の状況に合わせて随時行うということで、小規模多機能でショートステイというような考え方はございません。","voiceIndex":136,"id":"exchange-057"},{"speaker":"沢田委員","kind":"質問・要望","question":"行政側がそういったことに対してしっかりと支援をしていくことによって、今あるさまざまな高齢者に対するサービスと連携をして、しっかりとそういった小規模多機能型居宅介護の施設がしっかり１３地域に早急に整備されるようにお願いをしたいと思います。次に、６４ページの生活保護費のことでお伺いをさせていただきたいと思います。","respondent":"伊東生活福祉課長","answer":"今回、平成２６年度の見込みとして、２億円ほどの扶助費の減額ということでお願いをしています。この間、生活保護受給者に関しては、上昇率がだいぶ落ち着きまして、ほんの１％、２％の上昇にとどまっているというような状況です。","voiceIndex":138,"id":"exchange-058"},{"speaker":"沢田委員","kind":"意見","question":"生活保護費を減らしていくということの、今、現状、増えていくということもあるかと思うのですけれども、区としていろいろな取組みをこの間もされてきたと思うのですけれども、不正受給を減らしていくだとか、また、高齢者以外の若年の方たちに対する就業支援等をやられてきましたし、また、ジェネリック医薬品を使っていくということで、そういった改革をされてきたと思うのですけれども。","respondent":"伊東生活福祉課長","answer":"当然不正受給に関しましても調査権がありますので、こちらのほうで詳細に調査をしまして、不正があれば、当然それは返還していただくということで対応をしておるところです。","voiceIndex":140,"id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"特に就業センターとの連携等、そういったことで若い働ける世代の就労に結びつけていったかと思うのですけれども、そのあたりの成果というか、そういった現状について、就業に関する若い世代の受給者が減ってきているのか教えてください。","respondent":"伊東生活福祉課長","answer":"そういう方々は、仕事ができるのではないかというような方々ですので、そういう方々に関しては、先ほども申したとおり、早めの就労に結びつくような支援をしていくです。若い人につきましても、特にそういうところは支援をしていきたいというふうに思っております。","voiceIndex":142,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"初めに、５０ページのリサイクル資源売払収入ですけれども、今回この補正で３,１５５万２,０００円の増額と補正をされていて、これがこのままリサイクル事業の費用のほうの更正減額というふうに充てられておりますけれども、今回この補正額で３,１５５万２,０００円に増額となった理由として、このリサイクル事業の今の現況、どのような状況であるのかということと、また、あわせまして。","respondent":"小林品川区清掃事務所長","answer":"現在、今年度二月残しておりますが、１月末で古紙全体ですと９８.３％、また、瓶・缶ですと９７.５％ということで、１００％、前年度水準を守れるかどうかというような推移です。","voiceIndex":145,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問","question":"アルミ缶とペットボトルについて単価が上がっているので、こういった収入増になったと、これはこれで大変結構なことだったというふうに思いますけれども、その一方で、全体として資源回収量は横ばいというご答弁がございました。今後、資源回収を増やしていく、回収量を増やしていこうと考えていくときに、どこら辺に課題というかチャンスがあるのか、この辺をお伺いしたいと思います。","respondent":"小林品川区清掃事務所長","answer":"今後の可能性として、もちろん各家庭に引き続き資源のリサイクルを進めていただく努力を継続していきたいと思います。一方、ごみ排出量の４７％、半分近くを事業系の廃棄物が占めておりますが、この廃棄物の中にリサイクル可能な資源が相当数含まれていると推定しております。","voiceIndex":147,"id":"exchange-062"},{"speaker":"塚本委員","kind":"質問","question":"そこで、小規模事業者向け資源回収サービスについてということで、区の収集に出すよりは安い小規模事業者向けの資源回収サービスがあったら利用したいですかというような設問をされておりまして、ここで利用したいという方が全体では２８％、事業者の規模によって若干数字が違ってくるのですけれども、５人以上１０人未満のところは一番高くて３５.２％。","respondent":"小林品川区清掃事務所長","answer":"その結果、かなりの方がコスト的なものが見合えば、リサイクルをやってみたいという意思が今回確認できましたので、従前、区が持っております事業系リサイクルシステム、これは１店舗、１企業、規模が小さいためにリサイクルの資源量が少ない、したがって。","voiceIndex":149,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。続きまして、１１５ページの共同事業拠出金で、中でも２目の保険財政共同安定化事業拠出金、これが８,４００万円強の更正減額というふうになっておりますけれども、この更正減額となった理由についてお伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"こちらの保険財政共同安定化事業拠出金の事業ですが、レセプト１件３０万円を超える医療費を対象としておりまして、２３区の医療費の合計額から一定率を拠出する形になってございまして、これが見込みよりも下回ったというのが原因というふうに考えてあります。","voiceIndex":151,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"見込みを高く設定したからというようなご答弁と伺ったのですけれども、これはいわゆる医療費の削減等を品川区として努力をした結果、こういった形での更正減額を得ることができたというような側面といえるものが何かあるのかどうか、そこをお伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"この拠出金の利率につきましては、２３区で全体の融資を振り分けている形になっていますが、それぞれの区がさまざまな形で医療費削減、例えばジェネリックの通知だとか、医療費通知をお出しすることによって、医療費の適正化に取り組んでいるという結果が少しは出ているのかと。","voiceIndex":153,"id":"exchange-065"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。そのようなご努力の結果であったというふうに私も受けとめたいと思いますので、今後ともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３８ページ、４２ページから民生費補助金、６２ページの児童福祉費、保育園の待機児童問題でお伺いいたします。新しい職場を求めて内定がやっととれたのに、子どもの預け場所がなければ、もうこれも辞退するしかない。共産党はこの間、何回も緊急対策を求めてきました。質問です。なぜ緊急対策を打たないのでしょうか。子どもと親御さんをどうするのか、今後のことについてお伺いいたします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後も平成２８年度ですが、広町の区有地に２００人を超える規模の保育施設の開設を予定しております。","voiceIndex":157,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"意見","question":"１,２５６人をどうするのかというところを明確に答えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１,２５６人の不承諾数ですが、このうち、今申し上げたとおり、在園者数も多く含まれておりますので、二次の申込みを含めて、今後対応をしてまいります。","voiceIndex":159,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４月現在、入れなかったら職を失いますよという、こういった問題をどうするのかということを聞いているので、ぜひこの点をお答えいただきたい。待機児ゼロと言いながら、ゼロは無理と考えているのか、仕方がないと思っているのか、また、親の自己責任と考えているのか、また、いずれ少子化になるのでお金のかかることはやりたくない、こういう考えを持っているのか、改めてここをお伺いしたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほど答弁申し上げましたとおり、内定者が１,６８１人、そのうち認可が１,５４３人ですので、そちらを引いた数、家庭的保育事業、そして小規模保育事業に内定を出している方が１３８人です。","voiceIndex":161,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"数字ありがとうあります。今の答弁だと、１,２５６名のうち９００名強がこの不承諾通知で行き場がないということですよね。この子たち、どうするのですか。私、さっき質問したのですけれども、どうするのでしょうか。今後、数はあるのですか。精査していく中で行き場があるかと聞いている、ないのです。この子たち、どうするのですか。もう１回聞きます、どうするのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、低くなるだけではなくて、やはり待機児童という形で、これ以外の認可外保育施設をご利用になる方、または企業の事業所内保育事業を利用になる方もいらっしゃるというふうに認識しております。","voiceIndex":163,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時間がなくなってしまうのですが、９００人よりも低いけれども、すごい数の人が存在しているのです。部長は、平成２７年度総合対策で、７０９人枠を拡大しましたと言いますけれども、この枠、実際は本当に当初予算と現実の差が大きくて、全部合わせて３７０人なのです。３７０人入れても、まだまだ、そちらの計算でも足りない、対策不足に私は反省を求めます。問われると思います。ぜひお願いいたします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後とも特に待機児童が多い０歳から２歳のお子さんに対して、小規模保育事業等の途中開設も含め、認証保育所そして小規模保育事業、認可保育施設等これらの対策、そして事業所内にも働きかけて総合的に推進してまいります。","voiceIndex":165,"id":"exchange-071"},{"speaker":"向委員","kind":"質問","question":"私からは、４８ページ、４９ページ、予防接種受託収入、６４ページ、６５ページ、定期予防接種をまず伺いたいと思います。４８ページ、４９ページの予防接種受託収入のほうのこの中に、実績見合いということでしたので、このあたりに、風しんにかかわる予防接種代もここに入ってくるのか、入らないのか、それを教えてほしいと思います。","respondent":"佐藤保健予防課長","answer":"予防接種についてのことで補正予算についてご説明を申し上げます。先に定期予防接種のところですけれども、今年度が定期予防接種単価の３年に一度の大幅な改定になっております。","voiceIndex":168,"id":"exchange-072"},{"speaker":"向委員","kind":"質問","question":"その先天性風しん症候群、検査を受けた人数とか、あらかた出てきて、来年度も一応予算には計上されているということで予算書を見ましたので、この１年で検査を受けた人数、男性と女性で分けるといいかと思うのですけれども、接種が必要と判断された人数、判断されても、結局そこから予防接種に進む、進まないということで、若干人数が変わってくるのかと思うのですけれども、これをそれぞれ教えてください。","respondent":"佐藤保健予防課長","answer":"そのうち、全ての方がこの検査から予防接種にいっていたりとか、あとは検査を受けた方以外でも既に抗体が少ないという方がいらっしゃいますので、その方は抗体検査を受けていませんけれども、こちらのほうで把握している予防接種を受けられた人数につきましては、女性が３１６人。","voiceIndex":170,"id":"exchange-073"},{"speaker":"向委員","kind":"質問","question":"わかりました。女性の約半数の方が予防接種を受けていたり、男性についても約４分の１が受けたという結果ということでした。大体１年間終わってきて、ピークの世代、男性、女性、２０代が多かったとか、３０代が多かったとか、そのあたりの印象を１年間通してどのように見られているのか。顕著だった傾向とか、わかる部分を現段階でお答えいただける範囲でいいですので、教えてほしいと思います。","respondent":"佐藤保健予防課長","answer":"本日、申し訳ありませんが、正確な世代別の数字を持ち合わせてございませんけれども、やはり先天性風しん症候群対策ということで、予防接種を打っていない男性、３０代から４０代、女性も同じような年代というところで受診者の方は受けられているように印象をもっております。","voiceIndex":172,"id":"exchange-074"},{"speaker":"向委員","kind":"質問","question":"１位が千代田区、２位が江戸川区、３位が文京区ということだったと思うのですが、そんな中で、品川区より上位に占めた区で上位になった理由、品川区と何か違うような取組みをもしされていたようであれば教えてほしいのと、本区としても、コールセンター、納付センターとか、新しい取組みとか、品川区は特に差し押さえとかはしていないので、そのあたりについて。","respondent":"高森国保医療年金課長","answer":"それぞれ国民健康保険につきましては、加入している被保険者の方の保険料でまかなうというのが一義的な考え方にシフトしていますので、区においては、滞納整理を推進しているところもありますし、また、もともと収納率が高い、住民税も含めて高いというふうな区もありますので。","voiceIndex":174,"id":"exchange-075"},{"speaker":"渡辺委員","kind":"意見","question":"７５ページ、大崎駅周辺地区再開発事業、関連して並んでいる７７ページの都市再生総合整備事業。予算措置上の大崎駅西口交通広場整備のところは、先ほど既にあくつ委員のほうから指摘があったので、重複しますので省略します。西品川一丁目地区のところ、今回の更正減額と、あと、工事の進捗具合という最初に説明がありました。この辺の内容を詳しくお聞かせください。","respondent":"溝口都市開発課長","answer":"当初予定しておりましたスケジュールよりも、まず一番初めに、当初、権利変換計画を今年の夏頃策定し、その後、工事に入っていく予定をしていたものが、権利変換計画の認可が１月末に遅れた、そういったところで事業の進捗に合わせて当初予定していたものができなくなった。","voiceIndex":177,"id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問","question":"この２点、地域、エリアとして伺っていきます。西品川一丁目地区では、かねて委員会等だったでしょうか、国家戦略特区の兼ね合いで、検討も含まれているやに聞いていますので、そういった意味でのこの２つのまちづくり、再開発の特徴を改めて伺わせてください。","respondent":"溝口都市開発課長","answer":"そういった中でまち運営プランを再開発事業者またはそういった地域の方たちが集まって運営協議会を設立して、まちをつくるだけでなく、今後の維持管理も含めてまちづくりを進めていくと考えている、そういった特徴がある地域になっております。","voiceIndex":179,"id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問","question":"今、特徴のところで、地域による運営というのは、私も一部承知をしている中で、もう一度伺いたいのが、西品川一丁目地区、大変広大な教習所跡地ということであります。この大崎の都市計画、大崎駅西口の地区計画のところの項目の中に、やはり同じように、副都心の位置づけから、『「人の住む副都心」の実現を目指す』という方針が最初の１行等にあるのです。","respondent":"溝口都市開発課長","answer":"ですから、ただオフィスビルができればいいというだけでなく、定住人口、そういったものも図れるようなマンションもあわせて建設していく、そういった複合市街地の形成を目指していくというのが１つ大崎副都心の特徴だというふうに考えております。","voiceIndex":181,"id":"exchange-078"},{"speaker":"渡辺委員","kind":"質問","question":"ここまで伺っていると、かなりいろいろ配慮されて意見集約をなされて進んでいるということがまず大きな評価をされるべきことだと思っています。そして、長期基本計画の改訂のところで、やはりエリアのところです、大崎地区のページ、今までの流れがぶれずに、あるいは拡充した経緯が十分記載がされているかと思います。仕事の面でも。そういう目で意識をどう把握されているのか伺えればと思います。","respondent":"溝口都市開発課長","answer":"そういった取組みをしていく中で、お互いにそれぞれ役割分担をしながら、よりよい大崎駅周辺のまちづくりが進められているというふうに考えているものです。","voiceIndex":183,"id":"exchange-079"},{"speaker":"渡辺委員","kind":"質問・要望","question":"コーディネーターのポジションです。そういう意味で、考えられる需要を幾つか申し上げるので、現時点のご見解を伺わさせてください。住居であり、観光の視点、お店の視点でも、十分イノベーションでいく、あるいは現状を確保していくところでのまちづくりを踏まえて、この辺を、この地区以外、どうやって行政がまちづくりに関与していく、あるいは支えていくか、あわせて最後に伺えればと思います。","respondent":"溝口都市開発課長","answer":"そういったところも１つの重要な役割を担って、中心となって、今後、エリアマネジメントというか、まちの運営管理、そういったものに当たっていくというのが一番いいのかというふうに考えているものです。地区外を含めまして地区内、まだまだ開発できるところがあります。","voiceIndex":185,"id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"この生活保護費の更正減額ですけれども、更正減額として２億７,９００万円というふうに出ておりますけれども、この減額の内容、なぜ減に至ったのか、ここには医療扶助その他扶助費と出ておりますけれども、この内容、また、その減額の要因、現況をお知らせいただきたいと思います。","respondent":"伊東生活福祉課長","answer":"ということで、年度末の執行見込みで最終的に１.６％程度までいくのかなというところを見まして、その差額として２億７,９００万円を減額補正するというものです。","voiceIndex":188,"id":"exchange-081"},{"speaker":"こんの委員","kind":"質問","question":"当初は３％増を見込んでいたけれども、執行率は１.３％でとどまるという、そうすると、事務事業概要から見ますと、毎年受給者の率が上がっている中で、こうした増を見込んでいるけれどもとどまっている、これはどういうふうにこの現状を捉えているのか。あるいは、これから増加する傾向にある中で、こうした予算の組み方というのはどのように考えていくのか教えてください。","respondent":"伊東生活福祉課長","answer":"増加率ですとかなかなか難しい部分もあろうかと思いますけれども、ここ何年かの経年変化等、あと社会情勢等を考えて、その都度、見込みで積算をしていっているところですけれども、高齢者が多くなってきているとか、いろいろな要件がございまして。","voiceIndex":190,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問","question":"一部、３０歳から３９歳の間の人数も２５８名と、これもまたこういうところでというところもあるのですけれども、こうした現状の中で、医療扶助だけではなくて、住宅扶助、こちらの現状はどのような、年齢別でとっていらっしゃるのかどうかわかりませんが、住宅扶助単独で扶助を受けていらっしゃるということではないと思いますけれども、住宅扶助だけで見たときに。","respondent":"伊東生活福祉課長","answer":"その辺は全受給者の９０％弱の方に対しては、住宅扶助を出しているというような状況にあります。","voiceIndex":192,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問","question":"ということは、全体的に年齢は関係なくというか、全般的にそれを受けていらっしゃるということだなというふうに思うのですけれども、この住宅扶助をなぜ今お聞きしたのかといいますと、いわゆる困窮される方が生活する上で生活費の大半が住むところの確保というか、住宅にかかわる、特に賃貸にお住まいの方などは非常に困窮を、収入が安定してこないと、そこが一番不安定になってくるというところで。","respondent":"伊東生活福祉課長","answer":"今年の４月１日から、生活困窮者自立支援法が施行されまして、その中で必須事業がありますので、そちらについては、自立相談支援事業、そして住居確保給付金の事業、これにつきましては必須ということですので、当然ながら品川区としても実施してまいります。","voiceIndex":194,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからの事業ですので、ぜひ実効性というか、そういったところで頑張っていただきたい、このように思います。お時間が少しありますので、大森駅水神口の駐輪場については、先ほど、何人かの委員が質問をされていたので、そことはかぶらないように１点だけ。そこら辺のところだけ教えてください。","respondent":"田口交通安全担当課長","answer":"今年の４月から基礎調査ということで、ボーリング調査を行います。その際に撤去を行いたいと考えております。","voiceIndex":196,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問","question":"９２ページのほうに、大井認知症高齢者グループホーム整備工事で工期変更等とあるのですが、「等」というのがあるので、何が起きているのでしょうかということです。増える一方だ。品川区としてどういう意気込みを持って待機児解消をやっていくのかということについてお聞きします。それからもう１つ、７７ページの義務教育施設整備基金がありますが、これ、なぜ追加が出てくるのかということです。","respondent":"本城企画財政課長、大串福祉計画課長、今井制度改革・待機児童対策担当課長","answer":"財源的には、当初見込みよりも多く税収あるいは財調の関係の基金が当初見込みより多かった、そういうものを今回それに充てているものです。なぜ工期の変更が行われたかといいますと、入札をさせていただいたのですけれども、残念ながらそれが１回目は不調に終わりまして。私ども、これまで品川区の保育計画を立てまして、待機児童解消を進めてまいりましたが、平成２７年度から５年間の計画で。","voiceIndex":199,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問","question":"債務負担行為については、これは緊急経済対策ですよという、これはこれで納得する部分はありますが、ただ、これは１点、どういう状況下に置いたときにこういう処置をするのか。例えば、去年ですと、５％から８％の消費税アップという形があって、それに合わせて対策をとっていくよということがありますが、どういう形でこれらを今後も使っていくのかということについて、考え方を教えてください。","respondent":"本城企画財政課長、今井制度改革・待機児童対策担当課長","answer":"ただ、私もそのようにご説明していたところですが、緊急というか、経済的側面だけではなくて、早期に平成２７年度当初から事業を実際に各区内の事業者等に仕事を受注してもらうことができることによって。品川区の場合、待機児童解消対策は平成２２年度からやってまいりましたが、国のほうがようやく昨年度から待機児童解消に積極的に取り組みました。これで２３区いろいろな形で進んでいくと思います。","voiceIndex":203,"id":"exchange-087"},{"speaker":"鈴木（真）委員","kind":"質問","question":"歳出のほうなのですけれども、職員費に関してです。最初の民生費ですと、児童福祉施設費の中で、保育園運営費の職員給与７,５００万円の減額、それから衛生費の中で清掃のほうの職員給与が３,６７０万円、その分の減額の理由を先に教えてください。","respondent":"竹田保育課長、堀越人事課長","answer":"民生費、児童福祉費の人件費についてご説明いたします。６２ページの給料のところですが、約７,０００万円ほどの減額になっております。作業計画上の人員は維持しておりますが、退職による分、不補充があったということ。それから、いろいろな事務の見直し等がございまして、人数減というような形でこのような差になってあらわれたところです。","voiceIndex":207,"id":"exchange-088"},{"speaker":"鈴木（真）委員","kind":"質問","question":"両方とも理由はわかりました。そういう点では、保育士に関して十分対応できているのか、その辺を教えてください。先ほど、事業系のリサイクル部分というお話がありましたけれども、一般の収集に関して、普段の収集の状況を見ていても、歩いていて本当に大変だなというふうに思っていますので、その辺どういうふうに考えていくのかお答えをお願いします。","respondent":"竹田保育課長、小林品川区清掃事務所長","answer":"個々の事情ですので、致し方ない部分もあるかと思います。それから、幼稚園教員につきましては、非常に少人数職場ですので、日ごろからいろいろ職員に声をかけて、離職にならないように配慮しています。したがいまして、日々の仕事の中で、ヒト、モノ、カネ、全て最適配分で最小コストを考える中で、直営で堅持すべき区民サービスの質を含めて、今後も努力してまいりたいと考えています。","voiceIndex":210,"id":"exchange-089"},{"speaker":"鈴木（真）委員","kind":"質問","question":"保育のほうはわかりました。ただ、やっぱりここも逆にいいますと、職場復帰している方というのは、今のお話だとあまりいないのかなという感じに聞こえたのですけれども、今ほかでも、逆に職場復帰を勧めているような状況の中で、区の方でそういうケースはどうなのかとお聞きしたいと思います。清掃に関しては、本当に大変だと思っています。保育のほうでもう１回お願いします。","respondent":"竹田保育課長","answer":"遠方に住んでいた方が育児をしながら仕事をできるように、品川区内に引っ越しされる方などもいらっしゃいます。品川区もワークライフバランスを推進しておりますので、保育士がしっかり子育てをしながら働けるという、そういう職場環境をつくってまいりたいと考えております。","voiceIndex":213,"id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"質問","question":"はい、わかりました。どうぞよろしくお願いします。がんばる地域交付金に関してです。これは国のほうは平成２５年度の補正予算で入った分ですよね。ですから、そうすると、品川区として予算を組んだときは、平成２６年度予算を組んだときには、これは数字として算定していたのか、していなかったのか、まずそこら辺が自分の中でよく理解できていないので、そこを教えてください。","respondent":"本城企画財政課長","answer":"がんばる地域交付金につきましては、年度当初予算を策定する段階では、まだこのような交付を受けられるということは決まっていませんで、平成２６年に入ってからこれを受けられるということで、それを活用して補正に今回計上したものです。","voiceIndex":215,"id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これが交付金が入ってくることによって、その分が財源が変わるということは当初の時点でわかっていて、逆に言うと、これがなぜ最終補正なのかというところをお聞きしたいと思います。財源が変わって区に歳入が入ってくるのは、いつごろ入ってくるのか、これは前にも何回か質問させていただいたことがあると思うのですけれども、交付金の入った時期はいつごろなのでしょうか。","respondent":"本城企画財政課長","answer":"今の清掃につきまして、お金の流れのタイミングとしましては、まだ現時点ではなくて、これから入ってくる見込みであるものです。それについて今回のタイミングで見込みとして最終補正に計上したというものです。","voiceIndex":217,"id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"質問","question":"まだ入っていない。これから、ここで承認をしてから払うという形になるわけですか。ただ、入るというのがわかる時期というのがありますね。先ほど、平成２６年の当初にはなかったけれども、その後、予算編成を終わった後に入ってくるということがわかった時点で、この金額は区として運用ができるというふうに判断はしないものなのでしょうか。","respondent":"本城企画財政課長","answer":"今回、交付決定を受けて、それで今回、それを踏まえた中でタイミング的に今回のこの時期になったです。","voiceIndex":219,"id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もう１回確認です。つい最近に交付が決まったということでよろしいのか。","respondent":"本城企画財政課長","answer":"そのとおりです。わりと近い時期に今回交付決定いただいて、それを踏まえての今回の補正での計上となっております。","voiceIndex":221,"id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。私もちょっとそこら辺を誤解していたような状況でした。それともう１点、簡単に。先ほど、歳入で特別区民税が補正で１０億４,８００万円増えている中、理由はもうお聞きしていますし、その辺のお答えはいいのですけれども、先ほど、納税義務者が増えたということでお話があったと思います。その年代層というのは、どういうふうに判断しているのかというのは、これは企画のほうで出ていますか。","respondent":"黒田税務課長","answer":"納税義務者が増えているですが、住民記録の転入者層で言いますと、２０代が転入超過ということで増えているということが総務省の統計から出ていまして、納税義務者でまいりますと、５歳区分ごとの年齢ですと、３０代後半から４０代前半が納税義務者の固まりとなっておりますので。","voiceIndex":223,"id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何を聞きたかったかというと、結局、今、若い層と出たからいいのですけれども、年代層によって、区としての施策がいろいろ変わってくると思うので、そこら辺で企画面でどういうふうにとお聞きしたいのは、今後の検討をしていく上で、いろいろな推計もしなければいけない、統計をとっていくところもあるでしょうけれども、そこに対してお答えを先にいただきたかったというつもりでお聞きしたのですが。","respondent":"柏原行財政改革担当課長","answer":"ですので、今後、人口の動態はもう一度調査し直すというところはあるのですけれども、そういったところを区の活性化という観点から大事な層であるというふうには考えてありますので、いろいろな層がいらっしゃるということではあるのですけれども。","voiceIndex":225,"id":"exchange-096"},{"speaker":"あべ委員","kind":"確認","question":"私からは、５１ページ、諸収入、土木費受託収入のＯ歩道橋についてと、それから６９ページのプレミアム付区内共通商品券、７１ページの大森駅水神口の駐輪場について、それから１１６ページの国民健康保険の特定健診について伺いたいと思います。特に５,０００円単位という方向で進んでいることは非常にいいなと考えています。その点について、区のお考えをお伺いしたいと思います。","respondent":"稲田道路課長、米田商業・観光課長","answer":"再度、積算をやり直しながら再度発注しようというところだったのですけれども、開発のほうでの混雑緩和の工事もあわせて同じエリア内であるというところで、開発のほうで土質調査を実施して。今回の共通商品券事業につきましては、そういうようなある程度制約といいますか、国のほうから発行に関する条件もありましたので、そのような形でやっておりますけれども、実際に商品券事業を実施するに当たっては。","voiceIndex":228,"id":"exchange-097"},{"speaker":"あべ委員","kind":"質問・要望","question":"やっぱり価格と速さといったらいいのですか、自転車が出てくる速さみたいなものとかも、すごくやっぱり機種やメーカーによっても違って、あまり価格を絞り過ぎて使いにくいと、また不法駐輪が増えてしまうということで、機種とまでは言わないですけれども、大体どういう仕組みのものにしていくかというようなことまでご検討されているのかどうか。教えてください。","respondent":"稲田道路課長、米田商業・観光課長、田口交通安全担当課長","answer":"現在まさしく調整中です。混雑緩和工事の開発組合側と我々の耐震補強、同時期に同場所をやるというところで、まさしく調整中です。その中では、５,０００円が妥当であろうというようなことで調整を進めておりますが、実際、区単位での共通商品券事業のスキームでやるときに。我々は、地下機械式以外にも、例えば、現在、大井水神公園内にあります通常のラック式のもの、こういったものを例えば平置き式にしたり、また。","voiceIndex":231,"id":"exchange-098"},{"speaker":"あべ委員","kind":"質問・要望","question":"Ｏ歩道橋については、来年度、工事が行われることにもなると思います。今でも非常に混雑しているところですし、工事ということになると、動線がまたさらに乱れると思いますので、そこら辺は安全性と流動性を十分確保していただきたいと思います。この指導実績が伸びていない原因と、その改善策を教えていただければと思います。","respondent":"高森国保医療年金課長","answer":"それを何とか改善するために、５月の中旬に受診券を送付させていただいた後に、お電話でご案内を差し上げたり、未受診の方にははがきを差し上げたりしているのですけれども、なかなか受診率が向上していないのが実情でございまして、また。","voiceIndex":235,"id":"exchange-099"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-100"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、６９ページの商店街活性化事業の中のチャレンジマート事業助成についてお伺いします。それから、時間があれば、その前の６５ページの各種がん検診追加分のところをお伺いしたいと思います。実際、その中のこのチャレンジマート事業はどういう事業なのか、改めて教えていただきたいと同時に、これが実は平成１１年から事業を開始されたというふうに伺っています。","respondent":"米田商業・観光課長","answer":"こちらにつきましては、先ほど委員のほうからもありましたように、平成１１年度から始まっておりまして、昨年度は３件の申請がございまして、今回は補正の関係では２件がうまくいかなくなった関係で減額ということで出していますけれども、大体平均的に見ますと。","voiceIndex":240,"id":"exchange-101"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、この約２,０００万円のお金を減額というか、返上するというのは、ある程度、チャレンジマート事業をやるに当たって、そういう情報とか、そこに至るまでに何かないと、これだけ大きなお金を予算立てもしないでしょうし、また、お返しすることもない、予定が狂ったといいますか、そういうこともないのかなと思いますけれども、実際、現場的にはどういう動きをなさって、また。","respondent":"米田商業・観光課長","answer":"そういった意味合いでは、概ね手を挙げてから実施に至るまで、はっきり言ってしまうと１年ぐらいかかるものですから、その中で新たな借り主が生じたとかというようなことで、実際に事業がうまくいかなくなるというようなことで。","voiceIndex":242,"id":"exchange-102"},{"speaker":"山元委員","kind":"質問","question":"この事業はとても魅力的な、金銭的にはこれがオーケーが出ると、すごく魅力的な事業ではないかと思うわりには、今、課長がおっしゃったように、１件ぐらいしか成就しないというか、ならないというお話ですが、実際に今まで１年に１件ぐらいとおっしゃっておられましたけれども、その内容的にはどういう事業というか、どういうお店というのですか、具体的にどんな店舗をやっていらっしゃるのか。","respondent":"米田商業・観光課長","answer":"２３区で見ると、品川区はこれでも多いのかというふうに、ある程度考えているところではあります。","voiceIndex":244,"id":"exchange-103"},{"speaker":"山元委員","kind":"質問・要望","question":"今、課長のお話ですと、物産展とか、保育云々とありました。これは商店街の中で空き店舗をお借りしてそういうことをやるわけですけれども、自分はこのお店をやりたいのだけれども、でも商店街が反対というか、自分の思ったものができるものなのでしょうか。それとも商店街が要望するものではないと、空き店舗を使えないのでしょうか。","respondent":"米田商業・観光課長","answer":"大体におきまして、そういう空き店舗で出店をされたいという事業者の方は、やはり事前に商店街のほうに、役員の方とかと十分話をして、いろいろある業態だったり、ない業態だったりもすることもありますので、そういう意味合いで十分に事前に調整を図っているものほど、翌年度。","voiceIndex":246,"id":"exchange-104"},{"speaker":"山元委員","kind":"提案","question":"あるところは、大学生と商店街がタッグを組んで、空き店舗を使っていろいろやるとか、いろいろな知恵があるみたいなのですが、今のお話だと、今まで物産展とか、生鮮三品云々とおっしゃっていたのですが、例えば、品川区で提案というか、こういうものはどうなのみたいな、そういう動きはなさらないのですか。","respondent":"米田商業・観光課長","answer":"それと、学生とのかかわりですけれども、実際にでき上がったそういうスペース等を使って、学生の方に商店街振興のためにイベントに参加してもらうというようなことはありますので、副次的な意味合いですけれども、そういうような活用が図られているところです。","voiceIndex":248,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３８ページ、４４ページの保育緊急確保事業費補助金、待機児解消など、飯沼委員に続いて保育園待機児問題についてお聞かせいただきたいと思います。先ほどもありましたけれども、第一次の保育園申請者の４３％に当たる１,２５６名もの多数の不承諾通知となったのですけれども、まず、このことを区としてどう受けとめているか、１点お聞かせください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに、１,２５６人という昨年度比で多い数につきましては、これは待機児童対策として新規開設が順調に進んでいないということで私も認識しております。新規開設の数が大きな影響を与えているというふうに認識しております。","voiceIndex":251,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１,０８６人が不承諾通知を受けながら二次の受け皿は３１人ということですと、１,０５５人がまた入れないという状況になりますけれども、私は本当にこれが深刻な状況ということで、たくさんのママたちから、本当に不安で不安でたまらないという声を聞いているのですけれども、これを実際にどうするのかということで改めてお聞かせいただきたいのですけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"認可外の保育料につきましては、それぞれ上限等あると思いますけれども、平均とは言いませんけれども、大体１０万円程度というふうに認識はしております。","voiceIndex":253,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、先ほど、保育園の問題は親の責任だということでの野次もありましたけれども、就労のために保育園入園を希望する、子どもが入るための保育園を整備するというのは、区の責任だと思うのですけれども、この考え方についてはいかがでしょうか。親の責任と考えるというふうなことは区としてあるでしょうか。そのことについてもお聞かせください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"区の保育実施の責任ということですが、児童福祉法第２４条第１項におきまして、就労等を含めて、地方自治体である基礎自治体が保育の実施責任があるものと認識しております。","voiceIndex":255,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童福祉法第２４条に基づいて、区の責任だということで確認をさせていただきたいと思います。平成２７年度確保方策の数というのが、３号認定、０歳から２歳児です、これが４,３１９人、２号認定の３歳から５歳が３,９１６人というふうなことで出ていますけれども、実際の４月の確保数がどうなっているのか、また、年度末にはどうなるのかということについて、この数を教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２号認定のお子さんですけれども、ニーズは３,９１６人ですが、既に平成２６年度に３,７０５人あります。ここにつきましては、４月当初、１８２人の定員の増を図りたいというふうに考えております。","voiceIndex":257,"id":"exchange-109"},{"speaker":"本多委員","kind":"質問・要望","question":"やはり副都心ですから、東京にある７つの副都心の１つですから、今後の展望ですとか、ホテルの誘致ですとか、あり方等は質疑が出ておりましたので、私からは１点だけお聞きします。副都心のこの大崎の目玉がないとずっと言われてきましたので、現在、その目玉を誘致するとか、どういうふうなお考えなのか教えてください。","respondent":"溝口都市開発課長","answer":"そういったものに親しまれるような街にしていきたいと考えておりますので、何がというか、今後そういったものも含めて、まちづくりを検討していきたいというふうに考えているものです。","voiceIndex":261,"id":"exchange-110"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に７つの副都心のうちの一番すばらしい副都心になるように、今後もいろいろ考えていっていただきたいと思います。それで、この周辺について関連で質問していくのですけれども、このバスターミナルの斜向かいになります、百反ずい道、百反坂下の自由通路が整備されまして、その百反ずい道に行く地下道の階段がすぐ斜向かいにあるのですけれども、あれは今後どういうふうな活用をするのか教えてください。","respondent":"溝口都市開発課長","answer":"今回、百反ずい道につきましては、歩行者の安全対策、または自転車と車の安全対策、そういった観点で歩道設置の工事を今現在進めているところです。委員ご質問の既存の大崎の西口から東口に渡るルートの横に渡るおりる階段のところです。","voiceIndex":263,"id":"exchange-111"},{"speaker":"本多委員","kind":"質問","question":"わかりました。本当に何か見栄えよくないなと思いながらいつも通るのですが、もうできてしまったのでしようがないのですが、それで、まずスムーズに車両が、昨年１０月に両通から一方通行になった時点でスムーズに移行できたのか、その現状を教えてください。","respondent":"稲田道路課長","answer":"昨年１０月１６日の１０時から一方通行化を開始したです。大崎署等にも確認をとったのですけれども、スムーズな通行を現在行っているところです。","voiceIndex":265,"id":"exchange-112"},{"speaker":"本多委員","kind":"質問","question":"スムーズに移行できたということでよかったです。それで、百反ずい道の歩道工事が今されていると先ほど伺いまして、昨年の決算特別委員会でしたか、議会にもその歩道工事の業者の入札が２回不調になったというような話がありました。その詳細について教えてください。今後の展望、工事を今やっているということだと思うのですけれども、それがいつ終わるのか、その辺について展望を教えてください。","respondent":"稲田道路課長","answer":"そこの最終的に道路を復旧する下請け業者、協力業者のほうに、同じ工事エリア内ですので、緊急的に随意契約をしまして、３月末日完成の予定で現在進めております。","voiceIndex":267,"id":"exchange-113"},{"speaker":"本多委員","kind":"質問・要望","question":"年度内に完成ということで、わかりました。それで、２回不調があったということで、この課題の捉え方はどのように感じていらっしゃるのか、積算の算出方法なのか、単価なのか、その辺の何か課題については、どのように思われているのでしょうか。いつもこれは東京都の基準に準じていると言われるのですが、本当に全部準じているのかどうか、その辺について説明いただきたいと思います。","respondent":"稲田道路課長","answer":"それに載っていない特別なもの、例えば今回、先ほども階段の入り口の話が出ましたけれども、そういう非常口の扉を設置するとかというふうになりますと、特別な仕様になってきますので見積もりをとったりしていくというところで、あわせて１本の工事として発注していくところです。","voiceIndex":269,"id":"exchange-114"},{"speaker":"本多委員","kind":"質問・要望","question":"この課題については、ぜひ工夫をしていっていただきたいと思います。それで、不調ということで、この平成２６年度の補正予算では、先ほどＯ歩道橋という話もありました。現時点から１年間ぐらいで結構ですので、これは経理課のほうなのですけれども、どのくらい不調があるのか、この補正予算の中だけでも結構ですし、その辺の現状を教えてください。","respondent":"立川経理課長","answer":"不調率は９.２％。昨年度は不調件数３１件でございまして、不調率は１０.３％。昨年に比べて若干減っているという状況ですけれども、区として重要な施策を展開する上で、不調のままで終わらすわけにはいかないということで、いろいろ工夫をして発注に努めてきたところです。","voiceIndex":271,"id":"exchange-115"},{"speaker":"本多委員","kind":"質問","question":"時間に余裕がなかったりした場合に、そもそもの計画が執行できない、そういう課題については、対策といいますか、現況こんなケースはこういうふうに対策したとか、年度をまたいでしまうとか、いろいろな遅れてしまうという部分について、どういうふうな課題、対策をお考えでしょうか。","respondent":"立川経理課長","answer":"不調のまま終わらせるわけにいかないということで、区としましては、設計内容、工期等を見直して、不調に至らず契約まで持っていくということに積極的に取り組んでいるところです。","voiceIndex":273,"id":"exchange-116"},{"speaker":"本多委員","kind":"質問・要望","question":"もうその辺は十分いろいろな角度から検証していただけると思いますので、十分ご配慮いただきまして、計画が予定どおり執行されることを望みます。先ほどのバスターミナルのような拡充をするために年を越すというのはすごく大歓迎なのですが、そもそもの計画が遅れてしまうという支障が出ないような方策をとっていただきたいと思います。願って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-117"},{"speaker":"高橋委員","kind":"確認","question":"先に７０ページの自転車等駐車場のことなのですが、ほかの委員の方が多くの質問をされましたので１点だけ。今年の冬に説明会実施ということで、先ほど、課長からご説明がありましたけれども、地域の方々にどのような形でご説明を丁寧にしていただけるのかということの確認を１つさせてください。","respondent":"田口交通安全担当課長","answer":"それと今後の予定です。これから基礎調査等を行いますが、ある程度詳細の実施計画、予定では今年の冬頃になると思いますが、そのときにもう一度住民説明会を行いながら丁寧に説明していきたいと考えております。","voiceIndex":277,"id":"exchange-118"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。減債基金のほうについては、以前お伺いしたときに、都市計画交付金と財調交付金および起債の償還計画、それによって積み立てているということでご答弁いただいたので、こちらは千円単位というのはわかるのですが、財調の基金とか、義務教育施設整備基金というのは、この千円単位というところがちょっとわからないので、すみません、ご説明いただきたいと思います。","respondent":"本城企画財政課長","answer":"それらを含めたものですが、そういう意味では、先ほどの公共施設の計画云々というものはまた別の要因によってそのような単位になっているものも含まれるというものです。","voiceIndex":279,"id":"exchange-119"},{"speaker":"高橋委員","kind":"質問","question":"ごめんなさい、私、理解がなかなかあれなのですが、それぞれの基金の計画に基づいて積み上げていってという感じですか。すみません、私ちょっと聞き取れなかったのですけれども。","respondent":"本城企画財政課長","answer":"１つは単位の問題と、１つはどういった見通しのものという比較的長期の問題と両方あろうかと思いますが、単位の問題について申し上げますと、かなり大きな額をまとまって、例えば今回、税収でありますとか、それらが伸びた関係で、一定程度。","voiceIndex":281,"id":"exchange-120"},{"speaker":"高橋委員","kind":"質問","question":"地域振興基金についてなのですが、平成２５年度中に６億円余の積立てが行われて、今年度末の見込額では６億三千数百万ということなのですが、当初、公益活動団体を支援することにより地域社会の振興を図るため、というような目的で始まったのですが、かなり基金の額が増えていったところから、その活用といいましょうか、地域活動のＮＰＯや。","respondent":"河内協働・国際担当課長","answer":"現状、３００万円余の助成金額の予算をいただいておりますが、現在の品川区の公益活動団体の状況を見ますと、まだまだ今後、事業費を消化できるような体力をつけていく必要があるということで、資金の提供、場の提供を伴いまして、さまざまな提供を今後行いまして。","voiceIndex":283,"id":"exchange-121"},{"speaker":"高橋委員","kind":"質問・要望","question":"当初の設置の目的のときの基金の原資から、これだけ数字的に幅広く支援ができるようになったと思いますので、３００万円ということなのですが、地域で活動されている方々により広く、今お話があったように、ぜひとも区として多くの活動支援をしていただきたいというふうに思っています。そのために幅広く声をかけて、いろいろな活動分野を広げていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-122"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、５３ページの地方版総合戦略策定費、６１ページ、大井認知症高齢者グループホーム整備費、６９ページ、プレミアム付区内共通商品券、７５ページ、やさしいまちづくり整備費、８８ページ、債務負担行為の説明の中から、時間があれば、７９ページの図書館経費についてお伺いします。よろしくお願いします。","respondent":"柏原行財政改革担当課長、大串福祉計画課長、米田商業・観光課長","answer":"ただ、区が今やっていることを広げながらという考え方もありますので、それは戦略を立てる中でいろいろ検討していきたいというふうに思っております。委員ご指摘のように、こちらは建築の工事のほうで若干金額の変更が出てきておりますけれども、整備工事監理委託のほうにつきましては。そういった意味合いから、限度額を５万円に引き上げても、今まで以上に多くの方が購入できる計算になりますので、今回、そのような基準を設定し。","voiceIndex":287,"id":"exchange-123"},{"speaker":"石田（し）委員","kind":"質問","question":"６１ページのグループホームについては、わかりました。それと、この共通商品券ですが、今、民間でもさまざまな電子マネー、いわゆる電子化をしている中で、区としてこの共通商品券について電子化のお考えがあるのか教えてください。","respondent":"米田商業・観光課長","answer":"引き続きいろいろな技法等もあると思いますので、そういった意味で適正な販売と使用に供するように研究のほうは進めてまいりたいというふうに、これは商連とも一体となって進めてまいりたいと思います。","voiceIndex":291,"id":"exchange-124"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"偽造防止は、ぜひよろしくお願いします。７５ページのやさしいまちづくり整備費ですが、これは改めてどういった事業で、どのような仕組みで行われているのか教えていただきたいと思います。ＬＥＤ照明においても、早期に着手するというよりも、これも計画的に行っていく必要があるのかなというふうに思いますので、その辺を教えてください。よろしくお願いします。","respondent":"中村都市計画課長、本城企画財政課長","answer":"やさしいまちづくり整備ですけれども、こちらは公共交通機関等の施設の不特定多数の乗降客が利用するものにつきまして、バリアフリー法に基づきまして整備をする際、国と都と区。こちらについては、例えば老朽化の云々につきましても、老朽の度合いを見ながら計画的にやっていくという、当然、緊急対応的に必要なものはその都度やっていくということだというふうに理解しておりますが、ただ、それも含めて。","voiceIndex":293,"id":"exchange-125"},{"speaker":"石田（し）委員","kind":"確認","question":"債務負担行為は、確かに４月からすぐ工事できるようにということはわかるのですが、ということは、普段の予算化のときに、この老朽化した空調設備は、一定の期間で調査をかけて、ここは老朽化しているから直していかなければいけないということがある程度はわかると思うのですけれども、例えば壊れてしまって、これは老朽化による破損だったりというので緊急的に直すというのは理解ができるのですが。","respondent":"本城企画財政課長、中村都市計画課長、堀越人事課長","answer":"それがないと、４月から契約のこともやらないといけないので、その分遅くなる分、着手も遅くなる、それを回避するための措置というものです。国の予算は補正で既に対応しておりまして、来年度予算ということで対応ということになっておりますので、今、事業者と調整をしまして。その関係で、まず１つは、その後の人事異動等によって給料月額が変わったということ、それから、育児休業代替職員の解消ですとか。","voiceIndex":296,"id":"exchange-126"},{"speaker":"浅野委員","kind":"質問","question":"特別養護老人ホーム運営費に関連して、サテライト型居住施設ですけれども、特別養護老人ホーム、また老健、病院、診療所、こちらのほうが主たる本体施設になりまして、そこが支援を行いながら、本体施設とは別の場所で密接に連携をした施設をまた１つ運営をしていくという、このような考え方というふうに聞いておりますが、こちらのほうの本体施設と、もう１つのサテライト型の施設ですけれども。","respondent":"大串福祉計画課長","answer":"基本的には運営は全て同一の法人が行いますし、そこでの収支等々は全て同一の法人の会計の中で処理をするといった形になっております。","voiceIndex":301,"id":"exchange-127"},{"speaker":"浅野委員","kind":"質問","question":"大体概要を理解したと、そのように私も思うわけですけれども、移動時間が大体２０分程度ということになりますと、品川区の場合ですと、これもどのような移動かというのもあると思うのですけれども、車でしたらかなりの距離というのでしょうか、すごい広範囲にわたって、本体施設とサテライト型の施設の設置をできるのではないかというふうに思います。","respondent":"大串福祉計画課長","answer":"そういった形で本体施設とサテライト型を一体的に運営することによって、その法人の運営形態も安定してくるといったところで、そういったメリットを考えながら、法人のほうでもサテライト型の設置についての検討を行っていくということになろうかと思います。","voiceIndex":303,"id":"exchange-128"},{"speaker":"浅野委員","kind":"質問","question":"法人としての資質と言ったらあれでしょうけれども、経営状況とか、そういうような課題もあるかと思いますが、区ではどのように、例えば今、特別養護老人ホームを運営している事業者の可能性の可否というのでしょうか、そういうものについてご見解をいただければと思います。","respondent":"大串福祉計画課長","answer":"課題といったところです。基本的には社会福祉法人が特養を設置する、その特養を設置していく中で、広域的なものと、それからサテライト的なもの、こういった一体的な運営ということで進めていく。","voiceIndex":305,"id":"exchange-129"},{"speaker":"浅野委員","kind":"提案","question":"社会福祉法人だけで実現できるとはとても思えない部分はあると考えますので、こちらのほうも要請等に関しましては応じていただくようなことを、また区のほうからも社会福祉法人のほうにも提案をしていくという、このような姿勢でぜひとも臨んでいただきたいと思いますので、この点は要望にしておきます。チャレンジマート事業助成についてお伺いしたいと思います。","respondent":"米田商業・観光課長","answer":"申し訳ありませんが、ちょっと実績等については掌握してございませんが、商店街単体でやっているよりは、商店街も商店街連合会が入ることによって、さらなる利用の向上につながっているものと考えています。","voiceIndex":307,"id":"exchange-130"},{"speaker":"浅野委員","kind":"意見","question":"空き店舗の課題というのは、どの商店街でも出てくる可能性が高いと、そのように思いますので、こちらのほうの支援を商店街のほうとしっかりと連携をとりながら、活気ある商店街をつくっていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":309,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"短く３点お聞きしたいと思います。１点目が、６５ページの３款民生費、３項生活保護費、生活保護費更正減額２億円について。２点目が、６９ページ、５款産業経済費、３目中小企業対策費、空き店舗活用支援事業、これも減額ですね。共通商品券普及促進事業。生活保護費のほうですけれども、この更正減額、医療扶助その他扶助費、大きな減額がありますけれども、これについて改めてお聞きしたいと思います。","respondent":"伊東生活福祉課長","answer":"平成２６年度の執行状況ですけれども、１月末現在で、生活保護受給者の世帯数の増加が１.３％増であったということと、これから年度末に向けてもう少し上がるのかなというところで、１.６％まで増えるであろうということを見込みまして、それで差し引きしますと。","voiceIndex":311,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"生活保護費は１００億円を超える大きな金額ですから、当然見込みというのはぴったり合うなどというのはおかしいですね。当然増加するだろう、その中でやっているのだというふうに思います。まあまあ、しようがないよというのでしょうか、それとも見込みをちゃんとしっかりしなさい、数字そのもののとらまえ方がおかしいのではないのという形で指導があるのでしょうか、その辺についてお聞きしたいと思います。","respondent":"伊東生活福祉課長","answer":"こちらのほうで予算の見込みをつくりまして、都を経由しまして国のほうに補助金の申請をするというような段取りになってありますけれども、一旦都のほうで取りまとめということがありますので、我々のほうで考えに及ばない部分が多少あるとすれば。","voiceIndex":313,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"よくわかりました。そうですよね。２番目、６９ページの空き店舗活用事業、これは先ほどほかの委員からもお話がありましたけれども、今年度は３件申請があったけれども、１件しかできなかったということで、これももう１５年も経つ制度ですから、３年間の家賃補助があって、その後どうなのかなという気がするのです。その助成が終わった後、いまだに営業できているのでしょうか。","respondent":"米田商業・観光課長","answer":"そういった中では、私どものほう、３年の家賃補助が切れた後も継続をしていただいているところが多いというふうに正直思っておりますけれども、実質的に把握しておりますところでは、４件が何らかの事情により閉店しているというような現状があります。","voiceIndex":317,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"これは要件の中に、当然ながら商店街の活性化ということですから、商店街に空き店舗があると連続しない、あるいは集客力が減るということで、商店街だしということで、当然これは商店街から申請ということになっているのだと思いますけれども、商店街から外れたところで空き店舗がある、こういうような方で、実際そういうものを見かけるのです、それが区の補助を受けているというものを見かけますけれども。","respondent":"米田商業・観光課長","answer":"委員ご指摘のとおり、商店街が申請する事業ですので、現在のところ、商店街の街区内にある空き店舗が対象となります。","voiceIndex":319,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、商店街に含まれていないものは入っていないという解釈でよろしいのですね、わかりました。改めて調査をしてみたいと思います。実は、商店街の中でこんな話を聞いたのです。これは実際に本当かどうかという実地調査はまだしていないのですけれども、こういうことが区に入っていますでしょうか。その点だけお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"現状のところ、私どものほうではそういったことを正直把握しておりませんが、当然空き店舗活用支援事業については、商店街が中心となって行っている事業ですので、商店街の会員になり、それから商店街の会費、こういうようなことがもし仮に行われていないとすれば。","voiceIndex":321,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。これが共通商品券ということで品川区は言っていますけれども、内閣府のほうでも、ほとんどはプレミアム付商品券かななどということを言っているそうですけれども、実際これは品川区として共通商品券以外にほかの用途でどうしようかという計画を考えたのかどうかということと、２３区は横並びで全部共通商品券なのかどうか、その辺をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"委員ご指摘のありましたように、地域住民生活等緊急支援のための交付金ですが、こちらについては、ある程度縛りはあるのですけれども、消費喚起、生活支援に供するというようなことで、自由に使っていいというような側面も一部にはありますが。","voiceIndex":323,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"今度、それの単位が５,０００円になったものですから、５００円券が１０枚ですから、そんな意味で使えるかなと思うのですけれども、販路拡大を考えたときに、扱う店を増やす努力、区商連にお話をしているということなのですけれども、行政として必ずこれは全部売れるというふうに考えているのかどうかということと、これは売れ残ってしまった場合、返さなくてはいけないのではないかと思うのですが。","respondent":"米田商業・観光課長","answer":"当然これについては４月のなるべく早い時期に売り出しをかけて、区商連としては、売るためのさまざまな努力をする。","voiceIndex":325,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり売れ残らないように、消費拡大策ですから区民の皆様が買ってくれるような形、区商連にしても、とにかく取扱い店舗を増やしてもらって、これが商店街活性化と同時に、商店街に加入する商店が増えるような施策をしていただきたいというふうに思います。３点目の７７ページ、都市防災まちづくり事業費更正減額、これの中身についてお聞きしたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"１点目が防災街区整備事業、こちらは中延地区の旧同潤会地区の事業の、これは委託経費なのですけれども、もともとは平成２７年度に都市計画決定を予定しておりまして、そこから進める事業だったのですが、地域の機運の高まり等、全て前倒しでうまくいった場合に。","voiceIndex":327,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"これは低迷している消費を喚起するということと、それから、経済弱者に対する生活支援ほかのために使うというふうになっていますが、まず、今まで発行しているプレミアム付共通商品券ですが、これは過去にどのような職種のお店に使われたり、それから使われた方の年齢層の把握などというのは、これは過去のデータとして、公表はしないにしても、きちんと区のほうは持っているのでしょうか。","respondent":"米田商業・観光課長","answer":"そういった意味では、３０代以降７０代の方については、若干高齢者層が多いですけれども、ほぼ均等に使われている。それから、男女別では、若干女性のほうの購入の割合が多いというようなことで現状を把握しています。","voiceIndex":332,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"わかりました。区民の中の使っている人の層ですが、これも幅広くと言われますが、やはりある程度一定の中の枠には入ってしまうのかなというふうに今思いました。生活弱者、本当に困っている人にも使ってくれというふうにありますが、これはちょっとそれとはかけ離れているのではないですか。違いますか。","respondent":"米田商業・観光課長","answer":"この交付金ですけれども、国のほうからいろいろ来ている中では、交付金の給付というか、対象者が所得等で限定されるということよりも、広く全般に行き渡るような使われ方ということで、特にプレミアム付共通商品券の事業のようなものが推奨されていることから。","voiceIndex":334,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"逆に、裕福な方も購入できるという、幅広いのはわかるのですが、全て全額を、総額をそこに全員に幅広くと言っても、やはり購入できるのは一部の人ということになるわけなら、やはり何か対応を考えなければいけないのではないですか。そして、交付金事業の一部は、生活弱者に対応できるような対応策もきちんと考える必要があるのではないかと思うのですが、その辺についてご見解をお聞かせください。","respondent":"米田商業・観光課長","answer":"そういった意味でも、今回の商品券事業については、プレミアム率を上げるとともに、購入の口数といいますか、単価を切り下げて、どなたでも購入ができるように、それで地域での商店街等でのお買い物に資するようにということで。","voiceIndex":336,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"品川区はますます高齢化しています。私は、一部は構わないと思う。でも、やはり本当に困っている人たちには全く１円の利益も行かないのです。区民に優しくないじゃないですか。次にもう１つ、区の経済対策についてお聞きしたいと思います。でも、区として、その後、あの数字を見て、何か緊急経済対策はやったのですか。その辺、企画としてはどのようにお考えなのかお聞かせください。","respondent":"本城企画財政課長","answer":"産業経済的な分野におきましては、引き続き、中小企業融資あっ旋制度あるいは就業支援対策等、そういったものについて、引き続きあるいは拡大しながらやっていきましたり、あるいは、子育て世帯、所得が低い世帯に対する給付金、これは国の財源を活用して実施する等々。","voiceIndex":338,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"この間、ずっと物価が上がって、今度４月からまた物価が上がる。本当にこういう状況を見ていて、私はリーマンショックより大変な時期だと思うのです。だって、何も知らない間に自分の所得、収入が目減りしているわけです。私は今こそ大変な時期だと思うのです。それに対してなぜもっと早く動けないのか。私はそれはしっかり考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、介護保険特別会計補正予算のところで、１４４ページの介護給付費等準備基金について伺いたいと思います。この介護給付費等準備基金は、保険料上昇抑制に充てていくというものです。そして実際に、第四期、第五期の最後には、どれぐらい残ったのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第五期につきましては、積立てが４,６１９万５,０４５円です。取り崩しが３億６,６６７万４,４２３円の見込みとなっております。最終的に基金残高の見込額は、こちらの予算書に記載してありますとおり、１７億８,０８７万７,０００円です。","voiceIndex":342,"id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと細かく答えていただいたのですけれども、第四期で２３億５,０００万円ほどあったものを、取り崩しは８億円、そして幾ら残る計画で、実際に年度末に幾ら残ったのか。そして、第五期も幾らから幾ら取り崩して、実際に残ったのは年度末で幾らだったのかということをお聞きしたかったのですが、そこをわかりやすく端的にご説明いただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"すみません、第四期の計画のときに幾ら取り崩す予定だったかという書類が手元にないもので、第五期のほうで申し上げますと、計画のときには１０億８,０００万円を取り崩すという予定でございましたけれども。","voiceIndex":344,"id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと聞きたいところが違うのですけれども、第五期で見てみますと、１８億８,０００万円から１０億円取り崩して８億円残るという計画、こういった答弁が、この間の質問でもされているのです。そして、平成２７年度から始まる第六期は、幾らからどれぐらい取り崩して幾ら残る計画なのか、ここを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"第五期につきましては、実際の取り崩し額が３億６,６００万円余になっております。第六期につきましては、現在の推計でいきますと、１１億５,０００万円を取り崩す予定になっております。その結果、基金の残額は、６億２,６００万円余というような計画を立てているところです。","voiceIndex":346,"id":"exchange-147"},{"speaker":"石田（ち）委員","kind":"質問","question":"第六期も１７億円、１４５ページでは、平成２６年度末の基金見込額が１７億８,０００万円余と、ここから１１億５,０００万円取り崩して６億２,６００万円ほど余るということですけれども、要は、第五期の最後、第六期には残りが８億円と言っていたのが、１７億円になっていると。９億円も多く残る結果になっているのですけれども、なぜ増えるのか、この理由を具体的に伺いたいのですが。","respondent":"永尾高齢者福祉課長","answer":"推計をするに際しては、過去３年間の給付の見込みと、現在、区内にお住まいの方がそのまま年齢を上げたということで計算をしているものですけれども、第五期につきましては、予想よりも元気な高齢者、前期高齢者の数が予想よりも多かったということと、あと。","voiceIndex":348,"id":"exchange-148"},{"speaker":"石田（ち）委員","kind":"質問","question":"１７億８,０００万円から１１億５,０００万円を取り崩して６億２,６００万円残るという計画ですけれども、平成２９年度末にはまた増えているということになっていくのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういうことを考えますと、先ほど申し上げましたとおり、残額は６億３,０００万円弱になるのではないかというふうに見込んでいるところです。","voiceIndex":350,"id":"exchange-149"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までの第四期、第五期の計画を見ていて、その計画と第六期が特別何か違いがあるのでしょうか。違わないのであれば、また増えていくというのが計画の結果になってくるのではないでしょうか。それで、今度の平成２７年度の４月以降は、要支援者の予防給付サービス取り上げが始まるわけですから、これがさらに増えていくという状況にもなってくると思うのですけれども、そこら辺はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"第六期以降は、どんどん高齢者の数が増えていき、また、多分予想でいきますと、第七期になりますと、前期高齢者と後期高齢者が逆転するような見込みが立てられているところです。","voiceIndex":352,"id":"exchange-150"},{"speaker":"石田（ち）委員","kind":"質問","question":"取り崩すという計画ですけれども、この間は取り崩さずに済んでいると、むしろ大幅に増えていると。しかし、計画では８億円残るという計算でやっていけると計画を立てたわけです。そこが１７億円余って、１７億円の残高で、９億円は浮いているわけですので、保険料のさらなる軽減に使っても、計画上は支障はないということでいいでしょうか。","respondent":"永尾高齢者福祉課長","answer":"もう既に保険料の軽減を現在の予定でもしている、国に比べて区のほうでは軽減をかけているところです。","voiceIndex":354,"id":"exchange-151"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第五期と第六期の保険料全段階の差は、５億１,６６３万円です。せめて住民税非課税の方への値上げ中止、そして、そのほかの段階の方への保険料軽減ということを今こそしていくべきではないかと思うのです。９億円余るわけですから、その半分ちょっと、５億１,６６３万円で値上げはストップできると思うのですけれども、ぜひ進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それで、９億円浮いているというようなお話でございましたけれども、これは第五期までのお話でございまして、第六期以降、これからどんどんサービスが大きくなっていくことが見込まれておりますので、これでも財政的には厳しいのではないかというふうに考えているところです。","voiceIndex":356,"id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひともこれを軽減、そして値上げは非課税の方には中止をできるだけの財政力を持っていますので、そして、そういうところに準備基金は充てるようにというふうに充てる目的もありますので、ぜひそこに使っていただきたいと思います。そしてこの介護保険料、低所得者ほど厳しくのしかかるこの介護保険料こそ、今は引き下げに進んでいくべきだと思います。ここを改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":358,"id":"exchange-153"},{"speaker":"いながわ委員","kind":"確認","question":"選挙費なのですけれども、確認なのですけれども、衆議院選があって、たしか１１月末頃にその補正が組まれたと思うのですが、ここには区長と区議の補選の分しか載っていないのですが、それは一体どういうことなのかというのが１点。公費の負担減があったため、恐らく３,８００万円余が更正減額されていると思うのですが、これはどういった試算の中でこの予算を実際に組まれたのかということを教えてください。","respondent":"工藤選挙管理委員会事務局長","answer":"今回の選挙費ですけれども、衆議院選が昨年の１２月に入りまして、約１億４,６００万円ほど補正を組ませていただきました。こちらにつきましては、まだ集計というか、最終的ないわゆる総計の金額は出ておりませんので、こちらのほうはそのままです。","voiceIndex":360,"id":"exchange-154"},{"speaker":"いながわ委員","kind":"質問","question":"橋梁に関しても同じことが言えるのですが、平成２６年度予算では９,４００万円が、橋梁長寿命化修繕経費で計上されたけれども全て落とされて更正減額ということ、しかしながら、設計、施行監理委託費とかは平成２６年度は１,５２０万円ということなので、今回、４２０万円の減ですから、１,１００万円は何かしらに使ったのかなという、もちろん７３ページの橋梁です。","respondent":"稲田道路課長","answer":"都市計画道路補助２０５号線の件についてお答えします。２０５号線電線共同溝工事を今年度やる予定だったのですが、先行する既設埋設企業者の工事がずっと遅れてきまして、なかなか我々の電線共同溝工事が発注できなかったです。","voiceIndex":362,"id":"exchange-155"},{"speaker":"いながわ委員","kind":"意見","question":"債務負担行為で７,０００万円になっているのですけれども、平成２７年度の予算書には、平成２６年度債務負担行為で７,１００万円になっているけれども、その１００万円というのはどこから出てきたのかということを聞きたかったのです。","respondent":"稲田道路課長","answer":"すみません、７,１００万円の７,０００万円との差の１００万円なのですが、これも道路用地整備費で１００万円が乗っているです。","voiceIndex":364,"id":"exchange-156"},{"speaker":"いながわ委員","kind":"質問・要望","question":"橋梁のほうはもう時間がないのであれなのですけれども、何が言いたかったかというと、恐らく予算を本当に時間をかけて組んでいて、私たちの審議もあって、今こうしてやって、また執行されているわけですから、予算に関しては本当に重みがあると私は思っているので、ぜひ今後はなるべくしっかりとした執行を、もちろんしっかりされていると思うのですけれども、執行していただきたいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問","question":"私は、７７ページの不燃化１０年プロジェクト、それから何度も出ておりますけれども、６９ページのプレミアム付区内共通商品券発行助成でお聞きしたいと思います。それから、前段の２つのほうで、特に除却助成のほうは、これは予測していたものと件数が減ったのか、それとも金額的に減ったのか、両方とも減ったのか、その辺の状況も教えてください。","respondent":"寺嶋木密整備担当課長","answer":"除却のほうにつきましては、件数なのか、それとも金額なのかというところですけれども、これは個々個別の土地の広さとか建物によって違うので、予算上はm2で計算せざるを得ないのですけれども、実際には、件数も、それから金額も含めて。","voiceIndex":368,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問","question":"除却のほうは何となくわかりました。それとも今のお話だと、区のほうで事前にあらかたこの辺の場所をというところで出たものについて載せているのか、予算化しているのか、その辺はどんな感じなのですか。","respondent":"寺嶋木密整備担当課長","answer":"どこかの地区に限定されているかとか、どこかの土地に限定されているかといったことではございません。全ての地区において事業用地として必要と思われるものにつきましては、候補として考えておりまして、それで交渉するです。","voiceIndex":370,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、平成２７年度予算のほうでは、今度は１億円強の用地取得費というのが計上されているので、これについては本予算なのであまり細かくは聞けないのですけれども、例えば、新しい年度のほうでは、今度、どちらかというと、荏原地域ではなくて、大井だとか、そちらの地域のほうも新たに加わってくると思うのですけれども。","respondent":"寺嶋木密整備担当課長","answer":"予算上は、候補地が幾つかある中で、当然全てがうまくいくということはなかなか難しいですけれども、一定程度、戸数が出た段階で、予算上は全て計上するというよりは、不用額を出すわけにいきませんので、大方、その戸数とか交渉の状況によっても違うのですけれども。","voiceIndex":372,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"確認","question":"そうすると、この不燃化１０年プロジェクトの事業の中で、平成２６年度は固定資産税と都市計画税の減免も入っていたかと思うのですけれども、それについては補正に出ていないので、どこかに連動して予定どおりというか、あまりこれは補正で減額ということではないということでよろしいでしょうか、確認です。","respondent":"寺嶋木密整備担当課長","answer":"固定資産税と都市計画税の減免につきましては、東京都の都税のほうでやっているものなので、直接予算計上しているものではありませんので、こちらの予算上は当初予算も含めて一切記載はないです。","voiceIndex":374,"id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いろいろな意見があると思いますけれども、非常にこれは有効だと考えていますので、しっかり周知をしていただきたいと思いますけれども、その上で、答弁の中で、４月中旬ぐらいからできれば発売したいというお話でありますけれども、これもまた来年度の予算に入ってしまうといけないのですけれども、一応来年度の予算にも多分６億円ぐらいの発行額の規模の上乗せ分がもう入っているのですけれども、それは。","respondent":"米田商業・観光課長","answer":"来年度の当初予算に関しましては、実際のところ、そういうような作業を行っている中で国のほうの情報もとれましたので、こちらにつきましては、春期の発行状況を見ながら、また考えてまいりたい、このように考えてあります。","voiceIndex":376,"id":"exchange-162"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。では、来年度の予算のほうに盛り込まれているものの審議については、またそのときにもし必要であればやらせていただきます。考え方としては、それも含めて検討する、こういうことで考えておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":378,"id":"exchange-163"},{"speaker":"渡部委員","kind":"質問・要望","question":"３８ページの保育園、そして４０ページ、共通商品券です。売り方として８億円一気にですから、今までにないようなことも想定されるのかというところで、さまざま注意してやっていただきたい。しかも、５００円券、枚数で勘定すると一気に１９２万枚出るのです。まして８億円という金額が動くわけですから、慎重に丁寧に。しっかり国に要望していくことも大事だと思うのですが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"現時点では、国のほうからそういうような制度としてお金がおりてまいりますので、こちらをまず来年度のなるべく早い時期にしっかりとやって、その上でいろいろな検証事項等が出てくると思います。そういうものを踏まえて、また考えてまいりたいと思います。","voiceIndex":380,"id":"exchange-164"},{"speaker":"渡部委員","kind":"質問・要望","question":"さまざまな議論があると思います。その辺がわかるような仕組みづくりもこの予算内で進めていただければと思いますので、これは要望をしておきます。残念ながら３,０００人弱のお申込みの中で１,２００何名の数字も出ております。この数字が７０名か何か増えているわけです。いきなり１歳児は産まれないわけですから。ぜひその辺に関しまして、お考えを述べていただければと思いますが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"それにあわせまして、我々の保育の、教育のバイブルである「のびのび育つしながわっこ」を改訂する作業を平成２６年度実施してきたところであります。","voiceIndex":382,"id":"exchange-165"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区で子育ていただく方にさまざまな観点から満足をしていただきたい。品川区で育った子どもたちが、これからも世界で羽ばたけるように活躍もしてもらいたい。地域の大人たちで地域の子どもたちを育てるような品川区となるよう、これからもさまざまな施策に取り組んでいただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":384,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":124862,"voices":388}}]);
